INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26228, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旧衣服", "is_correct": true, "explanation": "旧衣服指穿过的衣物，“这些旧衣服已经穿了五年”符合句意。"}, {"text": "新衣服", "is_correct": false, "explanation": "语义：穿了五年的衣服不可能还是新的，与“穿了五年”矛盾。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“穿”的宾语应是衣物，不能说“穿行李”。"}, {"text": "书本", "is_correct": false, "explanation": "搭配：“穿”不能支配“书本”，不能说“穿书本”。"}], "explanations": {"旧衣服": "旧衣服指穿过的衣物，“这些旧衣服已经穿了五年”符合句意。", "新衣服": "语义：穿了五年的衣服不可能还是新的，与“穿了五年”矛盾。", "行李": "搭配：“穿”的宾语应是衣物，不能说“穿行李”。", "书本": "搭配：“穿”不能支配“书本”，不能说“穿书本”。"}, "sentence_index": 0, "correct_answer": "旧衣服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的旧衣服很好听。", "explanation": "这里应该用〈旋律〉。旧衣服指穿过的衣物，不能用来评价歌曲。"}, {"text": "这个问题的旧衣服很难。", "explanation": "这里应该用〈难度〉。旧衣服只指衣物，不能用来说问题的难易。"}, {"text": "这家饭馆的旧衣服很好吃。", "explanation": "这里应该用〈味道〉。旧衣服只指衣物，不能用来说饭菜好吃与否。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26228, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旧衣服", "is_correct": true, "explanation": "旧衣服指穿过的衣物，“别人穿过的旧衣服”符合句意。"}, {"text": "新衣服", "is_correct": false, "explanation": "语义：别人穿过的衣服不再是新的，“别人穿过的新衣服”自相矛盾。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“穿”的宾语应是衣物，不能说“别人穿过的饮料”。"}, {"text": "米饭", "is_correct": false, "explanation": "搭配：“穿”不能支配“米饭”，不能说“穿过的米饭”。"}], "explanations": {"旧衣服": "旧衣服指穿过的衣物，“别人穿过的旧衣服”符合句意。", "新衣服": "语义：别人穿过的衣服不再是新的，“别人穿过的新衣服”自相矛盾。", "饮料": "搭配：“穿”的宾语应是衣物，不能说“别人穿过的饮料”。", "米饭": "搭配：“穿”不能支配“米饭”，不能说“穿过的米饭”。"}, "sentence_index": 6, "correct_answer": "旧衣服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的叔叔是我小时候的旧衣服，一直陪着我。", "explanation": "这里把〈旧衣服〉用来指人。“旧衣服”只指已被人穿过、不再崭新的衣物，不能用来指人。"}, {"text": "这只狗是我家的旧衣服，每天陪我散步。", "explanation": "这里把〈旧衣服〉用来指动物。“旧衣服”只指衣物，不能用来指狗这样的动物。"}, {"text": "奶奶是我家最老的旧衣服，大家都很尊敬她。", "explanation": "这里把〈旧衣服〉用来指人。“旧衣服”只指衣物，不能用来指奶奶这样的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26228, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她找到一只旧衣服，洗干净后送给了表妹。", "corrected_sentence": "她找到一件旧衣服，洗干净后送给了表妹。", "error_description": "量词错误：旧衣服应用“件”，“只”用于动物或成对物中的一个。应把“一只旧衣服”改为“一件旧衣服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26228, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她翻出一件旧衣服们，准备捐出去。", "corrected_sentence": "她翻出一件旧衣服，准备捐出去。", "error_description": "复数错误：“旧衣服”是衣物，不能加复数标记“们”，应说“一件旧衣服”，不能说“一件旧衣服们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
