INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26232, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "老师让你回家做的事情。", "primary_collocate": null, "pronunciation": "zuò yè", "ipa": "tswo˥˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "老师今天布置了很多作业。", "target_word": "作业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天晚上先写作业，再看电视。", "target_word": "作业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份作业明天早上要交给老师。", "target_word": "作业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘了带作业，老师有点生气。", "target_word": "作业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的数学作业有三道题。", "target_word": "作业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业做完以后，我才能出去玩。", "target_word": "作业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈检查了我的作业，说字写得很好。", "target_word": "作业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末作业太多了，我做不完。", "target_word": "作业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同桌想抄我的作业，我没有同意。", "target_word": "作业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写下了今天的作业。", "target_word": "作业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "作业本", "label": "复合"}, {"form": "暑假作业", "label": "复合"}, {"form": "作業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "作业：老师布置、学生回家完成的功课", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3730d27a-05b6-43d9-b563-68f34a3445ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26232, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "作业", "is_correct": true, "explanation": "正确：作业（zuòyè）指老师布置、学生回家完成的功课。"}, {"text": "昨夜", "is_correct": false, "explanation": "zuó（第二声）与 zuò（第四声）声调不同，意思是昨天夜里。"}, {"text": "做客", "is_correct": false, "explanation": "语音：kè 以辅音 k 开头，yè 为零声母，二者开头不同，意思是到别人家里拜访。"}, {"text": "作恶", "is_correct": false, "explanation": "语音：è 与 yè 只差一个 y 介音（yè 有，è 没有），意思是做坏事。"}], "explanations": {"作业": "正确：作业（zuòyè）指老师布置、学生回家完成的功课。", "昨夜": "zuó（第二声）与 zuò（第四声）声调不同，意思是昨天夜里。", "做客": "语音：kè 以辅音 k 开头，yè 为零声母，二者开头不同，意思是到别人家里拜访。", "作恶": "语音：è 与 yè 只差一个 y 介音（yè 有，è 没有），意思是做坏事。"}, "sentence_index": null, "correct_answer": "作业"}, "level_3": {"options": [{"text": "学业", "is_correct": false, "explanation": "语义：“布置学业”不通，“学业”不是可以布置的具体任务。"}, {"text": "作业", "is_correct": true, "explanation": "正确：“布置作业”是常见搭配，指老师让学生课后完成的任务。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“布置”的对象是任务，不能说“布置很多成绩”。"}, {"text": "考勤", "is_correct": false, "explanation": "搭配：“考勤”是记录出勤的事务，不能说“布置很多考勤”。"}], "explanations": {"学业": "语义：“布置学业”不通，“学业”不是可以布置的具体任务。", "作业": "正确：“布置作业”是常见搭配，指老师让学生课后完成的任务。", "成绩": "搭配：“布置”的对象是任务，不能说“布置很多成绩”。", "考勤": "搭配：“考勤”是记录出勤的事务，不能说“布置很多考勤”。"}, "sentence_index": 0, "correct_answer": "作业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生给病人做的作业很成功。", "explanation": "这里应该用〈手术〉。作业是学生课后的练习，给病人做的治疗性操作要用手术。"}, {"text": "他在作业中拿了冠军，大家都很佩服。", "explanation": "这里应该用〈比赛〉。作业是课后练习，在竞赛中拿冠军要用比赛。"}, {"text": "考试时老师发给我们每人一张作业。", "explanation": "这里应该用〈考卷〉。作业是课后要完成的练习，考试时发的应是考卷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早饭", "is_correct": false, "explanation": "语义：“早饭”不是需要检查的学习内容，与“字写得很好”的评价无关。"}, {"text": "作业", "is_correct": true, "explanation": "正确：“检查作业”是常见搭配，后句“字写得很好”也指向作业的书写。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：“检查生日”不成立，“生日”不能被检查。"}, {"text": "校服", "is_correct": false, "explanation": "语义：校服可以检查，但与“字写得很好”的评价不相关，句意不通。"}], "explanations": {"早饭": "语义：“早饭”不是需要检查的学习内容，与“字写得很好”的评价无关。", "作业": "正确：“检查作业”是常见搭配，后句“字写得很好”也指向作业的书写。", "生日": "搭配：“检查生日”不成立，“生日”不能被检查。", "校服": "语义：校服可以检查，但与“字写得很好”的评价不相关，句意不通。"}, "sentence_index": 6, "correct_answer": "作业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次实验取得了显著作业。", "explanation": "这里应该用〈成果〉。作业指学生布置的练习，实验取得的成果要用成果。"}, {"text": "他每天晚上都玩作业。", "explanation": "这里应该用〈游戏〉。作业是学生布置的练习，不能拿来玩，玩的是游戏。"}, {"text": "剧团今晚的作业很精彩。", "explanation": "这里应该用〈演出〉。作业是学生布置的练习，剧团的表演要用演出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师今天布置了一只作业。", "corrected_sentence": "老师今天布置了一份作业。", "error_description": "错误形式：一只作业；正确形式：一份作业。“只”用于动物或成对的东西，作业应用“份”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把两份作业们都交了。", "corrected_sentence": "他把两份作业都交了。", "error_description": "错误形式：作业们；正确形式：作业。“们”只用于人，不能加在“作业”后面表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
