INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26234, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做完一件事之后，再做一些事情让它变得更好。", "primary_collocate": null, "pronunciation": "hòu chǔ lǐ", "ipa": "xou˥˩ ʈʂʰu˨˩ li˨˩˦", "syllable_count": 3, "sentences": [{"text": "画完画以后，他还要做一些后处理，让颜色更好看。", "target_word": "后处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片不用做后处理，已经很清楚了。", "target_word": "后处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "录完音以后，后处理能把杂音去掉。", "target_word": "后处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "视频的后处理比拍摄更花时间。", "target_word": "后处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会做照片的后处理，朋友们都请他帮忙。", "target_word": "后处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木桌做好后，还要做后处理，比如刷漆。", "target_word": "后处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们用软件做图片的后处理。", "target_word": "后处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布织好以后，后处理让它变得更软。", "target_word": "后处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有后处理，这段视频的声音听起来很乱。", "target_word": "后处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的后处理能让一张普通照片变得更漂亮。", "target_word": "后处理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "后处理环节", "label": "复合"}, {"form": "后处理软件", "label": "复合"}, {"form": "後處理", "label": "繁体"}], "register": "书面", "sense_fingerprint": "后处理：完成一件事后再做的改进性工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5fcd1e1-fe75-4807-99d7-b2e4db8a4067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26234, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后处理", "is_correct": true, "explanation": "正确：后处理指完成后再做的改进，与“画完画以后”的时序相符。"}, {"text": "前处理", "is_correct": false, "explanation": "语义：前处理发生在作画之前，与“画完画以后”的时序矛盾。"}, {"text": "草稿", "is_correct": false, "explanation": "语义：草稿是完成前的初稿，不是画完之后再做的步骤。"}, {"text": "颜料", "is_correct": false, "explanation": "搭配：「颜料」多说“调”，不说“做一些颜料”来让画面颜色更好看。"}], "explanations": {"后处理": "正确：后处理指完成后再做的改进，与“画完画以后”的时序相符。", "前处理": "语义：前处理发生在作画之前，与“画完画以后”的时序矛盾。", "草稿": "语义：草稿是完成前的初稿，不是画完之后再做的步骤。", "颜料": "搭配：「颜料」多说“调”，不说“做一些颜料”来让画面颜色更好看。"}, "sentence_index": 0, "correct_answer": "后处理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他还没开始画画，就先做后处理，让颜色更好看。", "explanation": "这里应该用〈准备〉。后处理指做完一件事之后再做改进，不能用于事情开始之前。"}, {"text": "他给狗洗完澡以后，又做了后处理，让狗更健康。", "explanation": "这里应该用〈护理〉。后处理指做完一件事之后的改进，不能用于照顾动物的健康。"}, {"text": "电梯的后处理要每半年做一次，保证安全。", "explanation": "这里应该用〈检修〉。后处理指做完一件事后的改进，不能表示设备的定期维护。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26234, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后处理", "is_correct": true, "explanation": "正确：后处理指做完之后的加工，与“用软件做图片”的语境相符。"}, {"text": "缝纫", "is_correct": false, "explanation": "语义：缝纫是用针线缝制衣物，与“用软件做图片”无关。"}, {"text": "录音", "is_correct": false, "explanation": "搭配：「录音」针对声音，不能用于图片。"}, {"text": "人工", "is_correct": false, "explanation": "语义：人工指靠人力完成，与“用软件做”的方式相反。"}], "explanations": {"后处理": "正确：后处理指做完之后的加工，与“用软件做图片”的语境相符。", "缝纫": "语义：缝纫是用针线缝制衣物，与“用软件做图片”无关。", "录音": "搭配：「录音」针对声音，不能用于图片。", "人工": "语义：人工指靠人力完成，与“用软件做”的方式相反。"}, "sentence_index": 6, "correct_answer": "后处理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他读完书以后做了后处理，把书放回了书架。", "explanation": "这里应该用〈收拾〉。后处理指做完一件事之后再做改进，不是把东西收回原处。"}, {"text": "这台洗衣机的后处理每三个月要做一次。", "explanation": "这里应该用〈保养〉。后处理指做完一件事之后再做改进，不能表示定期维护。"}, {"text": "这首歌还没写完，他就急着做后处理，让歌更好听。", "explanation": "这里应该用〈修改〉。后处理要在事情做完之后进行，歌还没写完时不能说后处理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "拍完照片后，我常常做了一点后处理，让天空更蓝。", "corrected_sentence": "拍完照片后，我常常做一点后处理，让天空更蓝。", "error_description": "错误形式：“常常做了一点后处理”；正确形式：“常常做一点后处理”。“常常”表示经常性的动作，与表示完成的“了”不相容，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "照片拍好以后，要做一只后处理才能发布。", "corrected_sentence": "照片拍好以后，要做一些后处理才能发布。", "error_description": "错误形式：“一只后处理”；正确形式：“一些后处理”。“只”用于动物或成对物品中的一个，后处理不能用“只”计量，应说“一些”或“一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
