INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26236, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个人或东西挤进去，把别人的位置占了。", "primary_collocate": null, "pronunciation": "jǐ zhàn", "ipa": "tɕi˨˩ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "他挤过来，挤占了我的位置。", "target_word": "挤占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人挤占了我们排好的位置。", "target_word": "挤占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从旁边挤进来，挤占了我的座位。", "target_word": "挤占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要挤占别人的位置。", "target_word": "挤占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人挤占了前排的座位，后面的人看不见。", "target_word": "挤占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗挤占了弟弟的小床。", "target_word": "挤占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个大箱子挤占了我的座位。", "target_word": "挤占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想挤占我的位置，我没有让。", "target_word": "挤占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车上人多，有人挤占了老人的座位。", "target_word": "挤占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们抢着挤占最前面的位置。", "target_word": "挤占", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挤占了", "label": "体标：了"}, {"form": "挤占着", "label": "体标：着"}, {"form": "挤占过", "label": "体标：过"}, {"form": "擠佔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或物挤进去占了别人的座位或位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3730d27a-05b6-43d9-b563-68f34a3445ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26236, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挤占", "is_correct": true, "explanation": "正确：“挤占”指硬挤进去把别人的位置占了，符合“挤过来”的语境。"}, {"text": "让出", "is_correct": false, "explanation": "语义：“让出”是把位置让给别人，与“挤过来”强行占据的意思相反。"}, {"text": "预留", "is_correct": false, "explanation": "搭配：“预留”的位置是事先留给某人的，不能与“挤过来”的情境搭配。"}, {"text": "空出", "is_correct": false, "explanation": "语义：“空出”表示位置自然空了，与“挤过来”的强行占据不符。"}], "explanations": {"挤占": "正确：“挤占”指硬挤进去把别人的位置占了，符合“挤过来”的语境。", "让出": "语义：“让出”是把位置让给别人，与“挤过来”强行占据的意思相反。", "预留": "搭配：“预留”的位置是事先留给某人的，不能与“挤过来”的情境搭配。", "空出": "语义：“空出”表示位置自然空了，与“挤过来”的强行占据不符。"}, "sentence_index": 0, "correct_answer": "挤占"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直挤占着我，不肯离开。", "explanation": "这里应该用〈陪伴〉。“挤占”的对象是位置或座位，不能用于人。"}, {"text": "小偷挤占了我的钱包。", "explanation": "这里应该用〈夺走〉。“挤占”指挤进去把别人的位置占了，钱包不能被挤进去占位。"}, {"text": "他挤占了我的名字。", "explanation": "这里应该用〈借用〉。“挤占”指挤进去把别人的位置占了，名字不能被挤进去占位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26236, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挤占", "is_correct": true, "explanation": "正确：“挤占”指占去别人的座位，符合“一个大箱子”占了我座位的语境。"}, {"text": "陪伴", "is_correct": false, "explanation": "语义：“陪伴”是跟随相处，不能表示占去座位。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是观看或品味，不能表示箱子占去座位。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”需要人作主语，“一个大箱子”不能修理座位。"}], "explanations": {"挤占": "正确：“挤占”指占去别人的座位，符合“一个大箱子”占了我座位的语境。", "陪伴": "语义：“陪伴”是跟随相处，不能表示占去座位。", "欣赏": "语义：“欣赏”是观看或品味，不能表示箱子占去座位。", "修理": "配价：“修理”需要人作主语，“一个大箱子”不能修理座位。"}, "sentence_index": 6, "correct_answer": "挤占"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他挤占了我的信。", "explanation": "这里应该用〈拆开〉。“挤占”指挤进去把别人的位置占了，信不能被挤进去占位。"}, {"text": "他挤占了我的雨伞。", "explanation": "这里应该用〈拿走〉。“挤占”指挤进去把别人的位置占了，雨伞不能被挤进去占位。"}, {"text": "他挤占了我的早饭。", "explanation": "这里应该用〈吃掉〉。“挤占”指挤进去把别人的位置占了，早饭不能被挤进去占位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26236, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车门一开，他就挤占得靠门的座位。", "corrected_sentence": "车门一开，他就挤占了靠门的座位。", "error_description": "错误在于“挤占”后面的助词。应说“挤占了靠门的座位”，“得”不能引出这样的补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26236, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "观众挤占了着台前的位置。", "corrected_sentence": "观众挤占了台前的位置。", "error_description": "错误在于体标的叠用。“了”与“着”不能同时用在同一动词上。应说“挤占了台前的位置”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
