INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家药店位于在医院旁边。", "corrected_sentence": "这家药店位于医院旁边。", "error_description": "错误：“位于”后面又加了“在”，写成“位于在”。“位于”本身已表示处在某处，不能再加“在”，应去掉“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家超市位于了地铁站对面。", "corrected_sentence": "这家超市位于地铁站对面。", "error_description": "错误：“位于”后面多加了“了”，写成“位于了”。“位于”表示处在某处，是静态动词，不能加“了”，应去掉“了”，正确的是“这家超市位于地铁站对面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
