INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26242, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "把脏水变干净，让水可以再用。", "primary_collocate": null, "pronunciation": "fèi shuǐ chǔ lǐ", "ipa": "feɪ˥˩ ʂweɪ˨˩˦ ʈʂʰu˨˩˦ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "工厂每天都做废水处理。", "target_word": "废水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做好了废水处理，水就可以浇花。", "target_word": "废水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厂里的废水处理出了问题，河水会变脏。", "target_word": "废水处理", "complexity_tier": "T3", "furigana": "fèi shuǐ chǔ lǐ", "sentence_source": "generated"}, {"text": "我们学校也在做废水处理。", "target_word": "废水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "废水处理很重要，大家要重视。", "target_word": "废水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的废水处理方法很简单。", "target_word": "废水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工作是废水处理。", "target_word": "废水处理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经过废水处理，脏水变清了。", "target_word": "废水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房的废水处理不好，会有臭味。", "target_word": "废水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们讲了废水处理的过程。", "target_word": "废水处理", "complexity_tier": "T3", "furigana": "fèi shuǐ chǔ lǐ", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "废水处理：把脏水变干净、让水再用的做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eafd00e7-0c74-47ca-a160-5befa431b7b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26242, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "废水处理", "is_correct": true, "explanation": "正确。“做废水处理”是常见说法，指对污水进行处理，与“工厂每天都做”相符。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学生的学习任务，工厂不做作业，句意不通。"}, {"text": "废气", "is_correct": false, "explanation": "搭配：“做废气”不成立，“废气”是排放物，不能用“做”来搭配。"}, {"text": "手术", "is_correct": false, "explanation": "语义：手术需要医院或医生进行，工厂不做手术，句意不通。"}], "explanations": {"废水处理": "正确。“做废水处理”是常见说法，指对污水进行处理，与“工厂每天都做”相符。", "作业": "语义：“作业”是学生的学习任务，工厂不做作业，句意不通。", "废气": "搭配：“做废气”不成立，“废气”是排放物，不能用“做”来搭配。", "手术": "语义：手术需要医院或医生进行，工厂不做手术，句意不通。"}, "sentence_index": 0, "correct_answer": "废水处理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这瓶矿泉水要先经过废水处理才能喝。", "explanation": "这里应该用〈灭菌〉。矿泉水本身是干净的饮用水，只需要杀菌；“废水处理”指把脏水净化，不能用在这里。"}, {"text": "这块蛋糕要先经过废水处理才能吃。", "explanation": "这里应该用〈加工〉。蛋糕是食品，不是脏水；“废水处理”只用于把脏水变干净，食品应说加工。"}, {"text": "空气污染很严重，我们要对空气做废水处理。", "explanation": "这里应该用〈治理〉。空气不是水，“废水处理”只针对水；空气污染要说治理，不能用这个词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26242, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "废水处理", "is_correct": true, "explanation": "正确。“他的工作是废水处理”表示他从事污水净化的工作，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是一种工作，不能作“工作是”的表语。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是疾病，不是工作内容，句意不通。"}, {"text": "白天", "is_correct": false, "explanation": "搭配：“白天”是时间词，不能充当“工作”的内容，搭配不当。"}], "explanations": {"废水处理": "正确。“他的工作是废水处理”表示他从事污水净化的工作，与句意相符。", "颜色": "语义：“颜色”不是一种工作，不能作“工作是”的表语。", "感冒": "语义：“感冒”是疾病，不是工作内容，句意不通。", "白天": "搭配：“白天”是时间词，不能充当“工作”的内容，搭配不当。"}, "sentence_index": 6, "correct_answer": "废水处理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的电脑坏了，需要废水处理。", "explanation": "这里应该用〈维修〉。“废水处理”指污水净化，电脑坏了应说维修，不能用这个词。"}, {"text": "这块金子很贵，要先经过废水处理才能卖。", "explanation": "这里应该用〈鉴定〉。金子不是脏水，“废水处理”不能用于金子；卖金子前要说鉴定。"}, {"text": "这本书很旧，要先经过废水处理才能读。", "explanation": "这里应该用〈修复〉。书是纸制品，不是脏水；旧书要说修复，不能用“废水处理”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每天都废水处理，保证水能再用。", "corrected_sentence": "我们每天都做废水处理，保证水能再用。", "error_description": "词性错误：「废水处理」是名词，不能直接作谓语，应加动词「做」，说「做废水处理」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市有一家废水处理。", "corrected_sentence": "这个城市有一家废水处理厂。", "error_description": "中心语缺失：「一家废水处理」漏掉了中心语，应为「一家废水处理厂」。“废水处理”修饰名词“厂”，不能省去“厂”直接用来计量“家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26244, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坚固", "is_correct": true, "explanation": "“坚固”与“薄弱”意思相反，指东西结实、不容易坏，是反义词。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”形容心情愉快，与“薄弱”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、不模糊，与“薄弱”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容没有声音或不吵闹，与“薄弱”没有反义关系。"}], "correct_answer": "坚固", "explanations": {"坚固": "“坚固”与“薄弱”意思相反，指东西结实、不容易坏，是反义词。", "高兴": "“高兴”形容心情愉快，与“薄弱”没有反义关系。", "清楚": "“清楚”形容明白、不模糊，与“薄弱”没有反义关系。", "安静": "“安静”形容没有声音或不吵闹，与“薄弱”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26244, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "结实", "is_correct": true, "explanation": "“结实”与“薄弱”意思相反，指东西牢固、不容易坏，是反义词。"}, {"text": "温暖", "is_correct": false, "explanation": "“温暖”形容温度或感觉，与“薄弱”没有反义关系。"}, {"text": "宽阔", "is_correct": false, "explanation": "“宽阔”形容面积大，与“薄弱”没有反义关系。"}, {"text": "柔和", "is_correct": false, "explanation": "“柔和”形容温和、不刺眼，与“薄弱”没有反义关系。"}], "correct_answer": "结实", "explanations": {"结实": "“结实”与“薄弱”意思相反，指东西牢固、不容易坏，是反义词。", "温暖": "“温暖”形容温度或感觉，与“薄弱”没有反义关系。", "宽阔": "“宽阔”形容面积大，与“薄弱”没有反义关系。", "柔和": "“柔和”形容温和、不刺眼，与“薄弱”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26244, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不结实，很容易坏。", "primary_collocate": null, "pronunciation": "bó ruò", "ipa": "pwɔ˧˥ ʐwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "旧房子的墙体很薄弱，一推就倒。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河边的堤坝有一处地方很薄弱，要马上修。", "target_word": "薄弱", "complexity_tier": "T3", "furigana": "hé biān de dī bà yǒu yí chù dì fang hěn bó ruò, yào mǎ shàng xiū", "sentence_source": "generated"}, {"text": "这座旧桥的结构薄弱，大卡车不能过。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这间旧屋的屋顶很薄弱，下大雨会漏。", "target_word": "薄弱", "complexity_tier": "T3", "furigana": "zhè jiān jiù wū de wū dǐng hěn bó ruò, xià dà yǔ huì lòu", "sentence_source": "generated"}, {"text": "这道围墙的底部很薄弱，要加固。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这扇窗的结构很薄弱，大风一吹就破。", "target_word": "薄弱", "complexity_tier": "T3", "furigana": "zhè shàn chuāng de jié gòu hěn bó ruò, dà fēng yī chuī jiù pò", "sentence_source": "generated"}, {"text": "旧船的船底薄弱，不能去远海。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个书架的结构很薄弱，放不了太多书。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老树的树枝薄弱，风大时容易断。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "帐篷的支架薄弱，一刮风就倒了。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "薄弱：东西的结构不结实，容易坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eafd00e7-0c74-47ca-a160-5befa431b7b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26244, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "薄弱", "is_correct": true, "explanation": "“薄弱”表示东西不结实、容易坏，与“墙体一推就倒”的语境相符。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水或眼神，不能形容墙体。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”形容人的心情，墙体没有心情。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，墙体不能响亮。"}], "explanations": {"薄弱": "“薄弱”表示东西不结实、容易坏，与“墙体一推就倒”的语境相符。", "清澈": "搭配：“清澈”形容水或眼神，不能形容墙体。", "高兴": "语义：“高兴”形容人的心情，墙体没有心情。", "响亮": "搭配：“响亮”形容声音，墙体不能响亮。"}, "sentence_index": 0, "correct_answer": "薄弱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山顶的空气很薄弱，走路很累。", "explanation": "这里应该用〈稀薄〉。薄弱指东西不结实、容易坏，空气少要用稀薄。"}, {"text": "这块玻璃的颜色很薄弱，看东西很模糊。", "explanation": "这里应该用〈浅〉。薄弱指东西不结实、容易坏，颜色浅淡要用浅。"}, {"text": "他的胡子很薄弱，没什么形象。", "explanation": "这里应该用〈稀疏〉。薄弱指东西不结实，毛发少而分散要用稀疏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26244, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "薄弱", "is_correct": true, "explanation": "“薄弱”表示东西不结实，与“船底不能去远海”的语境相符。"}, {"text": "甜蜜", "is_correct": false, "explanation": "搭配：“甜蜜”形容感情或滋味，不能形容船底。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，船底不能聪明。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容人的性情，船底不能温柔。"}], "explanations": {"薄弱": "“薄弱”表示东西不结实，与“船底不能去远海”的语境相符。", "甜蜜": "搭配：“甜蜜”形容感情或滋味，不能形容船底。", "聪明": "语义：“聪明”形容人的智力，船底不能聪明。", "温柔": "语义：“温柔”形容人的性情，船底不能温柔。"}, "sentence_index": 6, "correct_answer": "薄弱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间的温度很薄弱，有点冷。", "explanation": "这里应该用〈低〉。薄弱指东西不结实、容易坏，温度偏低要说低。"}, {"text": "这杯茶的颜色很薄弱，像白开水一样。", "explanation": "这里应该用〈淡〉。薄弱指东西不结实、容易坏，颜色浅要用淡。"}, {"text": "这座小镇的天空很薄弱，看不到星星。", "explanation": "这里应该用〈暗淡〉。薄弱指东西不结实、容易坏，天色昏暗要用暗淡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26244, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座老桥的桥墩是薄弱，车不能过。", "corrected_sentence": "这座老桥的桥墩很薄弱，车不能过。", "error_description": "错误：形容词“薄弱”作谓语时前面不加“是”，一般用程度副词“很”。应说“很薄弱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26244, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个仓库的墙面比较很薄弱。", "corrected_sentence": "这个仓库的墙面很薄弱。", "error_description": "错误：程度副词重复，“比较”和“很”都表示程度，只用一个即可。正确说法是“很薄弱”或“比较薄弱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
