INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26246, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人们做事情的地方，比如军队住的地方。", "primary_collocate": null, "pronunciation": "jī dì", "ipa": "tɕi˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "士兵们住在基地里。", "target_word": "基地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个基地很大，也很安静。", "target_word": "基地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人每天在基地训练。", "target_word": "基地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基地的门口有两个人。", "target_word": "基地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐车去了那个基地。", "target_word": "基地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在基地里工作。", "target_word": "基地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基地里有很多房子。", "target_word": "基地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个基地是新建的。", "target_word": "基地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在基地的操场上玩球。", "target_word": "基地", "complexity_tier": "T3", "furigana": "hái zi men zài jī dì de cāo chǎng shàng wán qiú", "sentence_source": "generated"}, {"text": "老师带我们参观了基地。", "target_word": "基地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "训练基地", "label": "复合"}], "register": "通用", "sense_fingerprint": "人们工作、训练或居住的固定场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eafd00e7-0c74-47ca-a160-5befa431b7b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26246, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基地", "is_correct": true, "explanation": "正确：“住在基地里”指士兵住在军队的固定场所，与语境相符。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆供人读书，不是士兵居住的地方，“住在图书馆里”不合常理。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：动物园是动物的居所，士兵不会住在那里。"}, {"text": "银行", "is_correct": false, "explanation": "搭配：“住在”后接的是可以居住的地方，“银行”不能说“住在银行里”。"}], "explanations": {"基地": "正确：“住在基地里”指士兵住在军队的固定场所，与语境相符。", "图书馆": "语义：图书馆供人读书，不是士兵居住的地方，“住在图书馆里”不合常理。", "动物园": "语义：动物园是动物的居所，士兵不会住在那里。", "银行": "搭配：“住在”后接的是可以居住的地方，“银行”不能说“住在银行里”。"}, "sentence_index": 0, "correct_answer": "基地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "盖房子以前要先打好基地。", "explanation": "这里应该用〈地基〉。地基是房子下面的基础部分，基地是人们工作、训练的场所。"}, {"text": "学好汉语，发音是基地。", "explanation": "这里应该用〈基础〉。基础指事物发展的根本，基地是场所。"}, {"text": "这个故事有真实的基地。", "explanation": "这里应该用〈根据〉。根据指作为依据的事实，基地是场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基地", "is_correct": true, "explanation": "正确：“基地里有很多房子”说的是场所里的建筑，与语境相符。"}, {"text": "口袋", "is_correct": false, "explanation": "语义：口袋装不下很多房子，“口袋里有很多房子”不合常理。"}, {"text": "池塘", "is_correct": false, "explanation": "语义：池塘里不会有成片的房子，与语境矛盾。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“书包里”装的是书本文具，“书包里有很多房子”搭配不当。"}], "explanations": {"基地": "正确：“基地里有很多房子”说的是场所里的建筑，与语境相符。", "口袋": "语义：口袋装不下很多房子，“口袋里有很多房子”不合常理。", "池塘": "语义：池塘里不会有成片的房子，与语境矛盾。", "书包": "搭配：“书包里”装的是书本文具，“书包里有很多房子”搭配不当。"}, "sentence_index": 6, "correct_answer": "基地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的汉语基地很扎实。", "explanation": "这里应该用〈基础〉。“扎实”修饰基础，基地是场所，不能用来形容语言能力。"}, {"text": "这个数字是我们的基地。", "explanation": "这里应该用〈基准〉。基准是衡量的标准，基地是活动场所，不能说“这个数字是基地”。"}, {"text": "公司拿出一笔基地支持科研。", "explanation": "这里应该用〈基金〉。“拿出一笔”搭配的是款项，应说基金，基地是场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "士兵们每天基地里训练。", "corrected_sentence": "士兵们每天在基地里训练。", "error_description": "表示训练处所的“基地里”前要用介词“在”引出，应说“在基地里训练”，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆基地是新建的。", "corrected_sentence": "这座基地是新建的。", "error_description": "量词错误：「基地」是场所，不能用「辆」计量，可用「个」或「座」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
