INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26256, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26256, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让脏的东西变干净。", "primary_collocate": null, "pronunciation": "jìng huà", "ipa": "tɕiŋ˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "这个机器能把脏水净化成干净的水。", "target_word": "净化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污水净化以后，才可以用来浇花。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种过滤器可以净化自来水。", "target_word": "净化", "complexity_tier": "T3", "furigana": "zhè zhǒng guò lǜ qì kě yǐ jìng huà zì lái shuǐ", "sentence_source": "generated"}, {"text": "房间里放几盆花，可以净化空气。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要先净化河水，才能喝。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人正在净化游泳池里的水。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雨净化了空气，天空特别蓝。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在家里装了一台净化水的机器。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小湖能自己净化湖水。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙子可以净化脏水，让水变清。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "净化了", "label": "体标"}, {"form": "净化过", "label": "体标"}, {"form": "净化器", "label": "复合"}], "register": "中性", "sense_fingerprint": "把脏水、脏空气等处理干净", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0ed7dbc-a6e5-40ee-911c-fb724370c835') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26256, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "净化", "is_correct": true, "explanation": "正确。「净化」表示把脏水处理干净，与「脏水」「干净的水」的变化相符。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：烘干是把水蒸发掉，不能把脏水变成干净的水，与句意矛盾。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：装饰与处理脏水无关，「装饰成干净的水」说不通。"}, {"text": "涂抹", "is_correct": false, "explanation": "搭配：「涂抹」不能与「成干净的水」搭配，也不能用于处理脏水。"}], "explanations": {"净化": "正确。「净化」表示把脏水处理干净，与「脏水」「干净的水」的变化相符。", "烘干": "语义：烘干是把水蒸发掉，不能把脏水变成干净的水，与句意矛盾。", "装饰": "语义：装饰与处理脏水无关，「装饰成干净的水」说不通。", "涂抹": "搭配：「涂抹」不能与「成干净的水」搭配，也不能用于处理脏水。"}, "sentence_index": 0, "correct_answer": "净化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天净化地，地面很干净。", "explanation": "这里应该用〈扫〉。扫地是清除灰尘，「净化」多指水、空气等杂质的清除，不说「净化地」。"}, {"text": "用熨斗净化裤子，裤子很平整。", "explanation": "这里应该用〈熨〉。熨裤子要用熨斗把褶子压平，「净化」指去除杂质，不用于熨烫。"}, {"text": "老师每天净化作业，很辛苦。", "explanation": "这里应该用〈批改〉。批改作业是检查评定，「净化」不用于作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "净化", "is_correct": true, "explanation": "正确。「净化」与「天空特别蓝」的结果相符，表示大雨使空气变干净。"}, {"text": "污染", "is_correct": false, "explanation": "语义：污染空气会让天空变灰，与「天空特别蓝」的结果矛盾。"}, {"text": "烧焦", "is_correct": false, "explanation": "语义：烧焦不能用于空气，「大雨烧焦了空气」与句意不通。"}, {"text": "装满", "is_correct": false, "explanation": "搭配：「装满」不能与「空气」搭配表示大雨的作用，句子不通。"}], "explanations": {"净化": "正确。「净化」与「天空特别蓝」的结果相符，表示大雨使空气变干净。", "污染": "语义：污染空气会让天空变灰，与「天空特别蓝」的结果矛盾。", "烧焦": "语义：烧焦不能用于空气，「大雨烧焦了空气」与句意不通。", "装满": "搭配：「装满」不能与「空气」搭配表示大雨的作用，句子不通。"}, "sentence_index": 6, "correct_answer": "净化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用颜料净化布，布变得很鲜艳。", "explanation": "这里应该用〈染〉。染布是给布上色，「净化」指去除杂质，不能用于上色。"}, {"text": "学校要净化学生的能力，让他们更强。", "explanation": "这里应该用〈培养〉。能力要靠培养来提高，「净化」指去除杂质，不用于能力。"}, {"text": "我们净化了这堵墙，墙面很白。", "explanation": "这里应该用〈粉刷〉。粉刷墙面是涂上颜色，「净化」指去除脏东西，不用于墙面涂饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器把脏水净化了成干净的水。", "corrected_sentence": "这台机器把脏水净化成了干净的水。", "error_description": "了的位置错误：「了」应紧跟补语「成」之后，即「净化成了」，不能放在「成」之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人用过滤器把净化河水。", "corrected_sentence": "工人用过滤器净化河水。", "error_description": "把字错误：「把」字句需「把+宾语+动词」，此处「把」后直接接动词，「把净化河水」不通，应删去「把」，正确为「工人用过滤器净化河水」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
