INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26258, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "加入其他材料中，用来改善其性能的物质。", "primary_collocate": null, "pronunciation": "zhù jì", "ipa": "ʈʂu˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "给橡胶加一点助剂，它就不容易老化。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种助剂可以让油漆干得更快。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人往水泥里放了一些助剂。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶助剂能让塑料变得更软。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在面粉里没有加任何助剂。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂里买来一批新助剂，价格不便宜。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种助剂用得越多，成本就越高。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把助剂慢慢倒进桶里搅一搅。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用了这种助剂，纸变得更白了。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说明书上写着助剂的用法。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "化学助剂", "label": "复合"}], "register": "书面", "sense_fingerprint": "加入后能让别的东西变好的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64cd21cc-e9a4-402b-8f56-12dc24689644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26258, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "助剂", "is_correct": true, "explanation": "“助剂”是加入后能让别的东西变好的物质，“给橡胶加一点助剂”通顺。"}, {"text": "糖", "is_correct": false, "explanation": "语义：糖加入橡胶后不能防止老化，句子说不通。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，加入橡胶不能使其不易老化，句子说不通。"}, {"text": "辣椒", "is_correct": false, "explanation": "语义：辣椒不能使橡胶不容易老化，与句意不合。"}], "explanations": {"助剂": "“助剂”是加入后能让别的东西变好的物质，“给橡胶加一点助剂”通顺。", "糖": "语义：糖加入橡胶后不能防止老化，句子说不通。", "汽油": "语义：汽油是燃料，加入橡胶不能使其不易老化，句子说不通。", "辣椒": "语义：辣椒不能使橡胶不容易老化，与句意不合。"}, "sentence_index": 0, "correct_answer": "助剂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这瓶助剂能让虫子死掉，效果很好。", "explanation": "这里应该用〈杀虫剂〉。助剂用来改善材料性能，不能杀虫，杀虫要说杀虫剂。"}, {"text": "这瓶助剂颜色很深，写字很清楚。", "explanation": "这里应该用〈墨水〉。助剂是加入材料里的物质，本身不用来写字，颜色深、写字清楚要说墨水。"}, {"text": "这瓶助剂能让墙变蓝，很好看。", "explanation": "这里应该用〈颜料〉。助剂本身不是颜色，能让墙变蓝要说颜料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26258, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "助剂", "is_correct": true, "explanation": "“助剂”指用于改善性能的物质，“用得越多，成本就越高”说的是材料，相符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能“用得越多，成本就越高”，句子说不通。"}, {"text": "口音", "is_correct": false, "explanation": "搭配：“用”后面一般接物品或方法，不说“用口音”。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是消耗的材料，说“用得越多成本越高”不合理。"}], "explanations": {"助剂": "“助剂”指用于改善性能的物质，“用得越多，成本就越高”说的是材料，相符。", "空气": "语义：空气不能“用得越多，成本就越高”，句子说不通。", "口音": "搭配：“用”后面一般接物品或方法，不说“用口音”。", "歌曲": "语义：歌曲不是消耗的材料，说“用得越多成本越高”不合理。"}, "sentence_index": 6, "correct_answer": "助剂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个仓库是用助剂盖的。", "explanation": "这里应该用〈水泥〉。助剂是加入主要材料里起辅助作用的物质，盖房子的材料要说水泥。"}, {"text": "他是我们组的助剂，大家都很依赖他。", "explanation": "这里应该用〈助手〉。助剂只指加入材料中的物质，不能用来称人，帮忙的人要说助手。"}, {"text": "这把助剂很好用，修自行车离不开它。", "explanation": "这里应该用〈扳手〉。助剂是加入材料中的物质，不是工具，修车用的工具要说扳手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把助剂们倒进桶里了。", "corrected_sentence": "我把助剂倒进桶里了。", "error_description": "错误：“们”用错了。“助剂”是物质名词，不能加“们”表示复数，“们”只用于指人或有生命的名词。正确：“我把助剂倒进桶里了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厂里进了一只助剂，很快就用完了。", "corrected_sentence": "厂里进了一包助剂，很快就用完了。", "error_description": "错误：量词“只”。正确：“包”。“助剂”的量词用“包”，“只”多用于动物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26260, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "超前", "is_correct": true, "explanation": "正确。“超前”与“滞后”相对，指发展快于正常或预期的时间。"}, {"text": "保持", "is_correct": false, "explanation": "保持：表示维持原来的状态，与“滞后”没有反义关系。"}, {"text": "参与", "is_correct": false, "explanation": "参与：表示加入某项活动，与“滞后”没有反义关系。"}, {"text": "承认", "is_correct": false, "explanation": "承认：表示认可某个事实，与“滞后”没有反义关系。"}], "correct_answer": "超前", "explanations": {"超前": "正确。“超前”与“滞后”相对，指发展快于正常或预期的时间。", "保持": "保持：表示维持原来的状态，与“滞后”没有反义关系。", "参与": "参与：表示加入某项活动，与“滞后”没有反义关系。", "承认": "承认：表示认可某个事实，与“滞后”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26260, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "超前", "is_correct": true, "explanation": "正确。“超前”与“滞后”相对，指供应或发展快于正常时间。"}, {"text": "思考", "is_correct": false, "explanation": "思考：表示用脑子考虑问题，与“滞后”没有反义关系。"}, {"text": "收藏", "is_correct": false, "explanation": "收藏：表示妥善保存起来，与“滞后”没有反义关系。"}, {"text": "传播", "is_correct": false, "explanation": "传播：表示扩散开来，与“滞后”不是反义词。"}], "correct_answer": "超前", "explanations": {"超前": "正确。“超前”与“滞后”相对，指供应或发展快于正常时间。", "思考": "思考：表示用脑子考虑问题，与“滞后”没有反义关系。", "收藏": "收藏：表示妥善保存起来，与“滞后”没有反义关系。", "传播": "传播：表示扩散开来，与“滞后”不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26260, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "事情比正常时间慢。", "primary_collocate": null, "pronunciation": "zhì hòu", "ipa": "ʈʂʅ⁵¹ xoʊ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "今天的会议开始时间滞后了一个小时。", "target_word": "滞后", "complexity_tier": "T3", "furigana": "jīn tiān de huì yì kāi shǐ shí jiān zhì hòu le yí gè xiǎo shí", "sentence_source": "generated"}, {"text": "由于设备故障，这批产品的交付时间滞后了一周。", "target_word": "滞后", "complexity_tier": "T3", "furigana": "yóu yú shè bèi gù zhàng, zhè pī chǎn pǐn de jiāo fù shí jiān zhì hòu le yí zhōu", "sentence_source": "generated"}, {"text": "这份报告的完成时间滞后了好几天。", "target_word": "滞后", "complexity_tier": "T3", "furigana": "zhè fèn bào gào de wán chéng shí jiān zhì hòu le hǎo jǐ tiān", "sentence_source": "generated"}, {"text": "因为大雪，这次的物资运输滞后了一天。", "target_word": "滞后", "complexity_tier": "T3", "furigana": "yīn wèi dà xuě, zhè cì de wù zī yùn shū zhì hòu le yì tiān", "sentence_source": "generated"}, {"text": "这次考试成绩的公布滞后了。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "付款滞后会影响我们的合作。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于人手不够，工程进度有点儿滞后。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络不好，视频的声音总是滞后。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作滞后了，我只好今晚加班。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说孩子的发育有些滞后。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "滞后了", "label": "体标"}, {"form": "滯後", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事情进行得比正常时间慢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64cd21cc-e9a4-402b-8f56-12dc24689644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26260, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "滞后", "is_correct": true, "explanation": "正确。滞后（zhì hòu）指事情进行得比正常时间慢。"}, {"text": "之后", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，“之后”意思是某件事以后。"}, {"text": "事后", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），“事后”意思是事情发生以后。"}, {"text": "日后", "is_correct": false, "explanation": "rì 与 zhì 声母不同（r 与 zh），“日后”意思是将来的某个时候。"}], "explanations": {"滞后": "正确。滞后（zhì hòu）指事情进行得比正常时间慢。", "之后": "zhī（第一声）与 zhì（第四声）声调不同，“之后”意思是某件事以后。", "事后": "shì 与 zhì 声母不同（sh 与 zh），“事后”意思是事情发生以后。", "日后": "rì 与 zhì 声母不同（r 与 zh），“日后”意思是将来的某个时候。"}, "sentence_index": null, "correct_answer": "滞后"}, "level_3": {"options": [{"text": "滞后", "is_correct": true, "explanation": "正确。“滞后了一个小时”说明会议开始得比原定时间晚，符合句意。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：“讨论”的主体是人，“时间”不能讨论，句子不通。"}, {"text": "等待", "is_correct": false, "explanation": "配价：“等待”需要有人作主语，“会议开始时间”不能等待。"}, {"text": "检查", "is_correct": false, "explanation": "语义：“检查”指查看事物，开始时间不能被检查一个小时。"}], "explanations": {"滞后": "正确。“滞后了一个小时”说明会议开始得比原定时间晚，符合句意。", "讨论": "语义：“讨论”的主体是人，“时间”不能讨论，句子不通。", "等待": "配价：“等待”需要有人作主语，“会议开始时间”不能等待。", "检查": "语义：“检查”指查看事物，开始时间不能被检查一个小时。"}, "sentence_index": 0, "correct_answer": "滞后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份报告，他滞后了三天才交。", "explanation": "这里应该用〈拖延〉。滞后说的是事情的进程比正常时间慢，不用来说人故意拖延。"}, {"text": "孩子又滞后了十分钟才到学校。", "explanation": "这里应该用〈迟到〉。滞后描述事情的进程，不用于描述人到达得晚。"}, {"text": "他在机场滞后了一晚上。", "explanation": "这里应该用〈滞留〉。滞后指事情比正常时间慢，表示人被困在某处要用“滞留”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滞后", "is_correct": true, "explanation": "正确。“工程进度有点儿滞后”说明工程进行得比计划慢，与“人手不够”的原因相符。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：“讨论”的主体是人，“进度”不能讨论，句子不通。"}, {"text": "发布", "is_correct": false, "explanation": "语义：“发布”是公开宣布，进度不能发布，句子不通。"}, {"text": "坚持", "is_correct": false, "explanation": "配价：“坚持”要有人作主语，“进度有点儿坚持”不成立。"}], "explanations": {"滞后": "正确。“工程进度有点儿滞后”说明工程进行得比计划慢，与“人手不够”的原因相符。", "讨论": "语义：“讨论”的主体是人，“进度”不能讨论，句子不通。", "发布": "语义：“发布”是公开宣布，进度不能发布，句子不通。", "坚持": "配价：“坚持”要有人作主语，“进度有点儿坚持”不成立。"}, "sentence_index": 6, "correct_answer": "滞后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的颜色滞后了。", "explanation": "这里应该用〈变深〉或〈变淡〉。滞后用于发展和进程，颜色没有“滞后”的说法。"}, {"text": "他走在队伍最后面，滞后得很远。", "explanation": "这里应该用〈落后〉。滞后说的是事情的进程比正常时间慢，人在队伍中落在后面要说“落后”。"}, {"text": "他在教室里滞后了一个小时。", "explanation": "这里应该用〈逗留〉。滞后指进程比正常时间慢，不表示人停在某处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这趟列车的发车时间滞后得二十分钟。", "corrected_sentence": "这趟列车的发车时间滞后了二十分钟。", "error_description": "错误：“滞后”后面用了“得”。正确：“滞后了二十分钟”。“得”后面要接表示程度的成分，如“滞后得厉害”；说已经发生的时间量要用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批货物的到达时间被滞后了好几天。", "corrected_sentence": "这批货物的到达时间滞后了好几天。", "error_description": "错误：“滞后”前面用了“被”。正确：“到达时间滞后了好几天”。“滞后”不带宾语，不能用于“被”字句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
