INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26262, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种用来给衣服染颜色的东西。", "primary_collocate": null, "pronunciation": "ǒu dàn rǎn liào", "ipa": "oʊ̯²¹⁴ tan⁵¹ ʐan²¹⁴ liɑʊ̯⁵¹", "syllable_count": 4, "sentences": [{"text": "妈妈说这种偶氮染料不太安全。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用偶氮染料把白衬衫染成了蓝色。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶偶氮染料是红色的。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里有很多种偶氮染料。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "染衣服要先买偶氮染料。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "偶氮染料不能放在孩子手边。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐用偶氮染料染了一条黄裙子。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "偶氮染料很便宜，颜色也很亮。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把偶氮染料倒进热水里。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一包绿色的偶氮染料。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "瓶", "label": "量词"}], "register": "专业", "sense_fingerprint": "给衣服染色用的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64cd21cc-e9a4-402b-8f56-12dc24689644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26262, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偶氮染料", "is_correct": true, "explanation": "正确。“妈妈说这种偶氮染料不太安全”，说的是一种染色用品，符合句意。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“安全”说的是物品或环境是否有危险，月亮不能说不安全。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天不是产品，说它不安全没有意义。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“安全”多用于物品、食品、环境，不和“天空”搭配。"}], "explanations": {"偶氮染料": "正确。“妈妈说这种偶氮染料不太安全”，说的是一种染色用品，符合句意。", "月亮": "语义：“安全”说的是物品或环境是否有危险，月亮不能说不安全。", "春天": "语义：春天不是产品，说它不安全没有意义。", "天空": "搭配：“安全”多用于物品、食品、环境，不和“天空”搭配。"}, "sentence_index": 0, "correct_answer": "偶氮染料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子用偶氮染料刷牙。", "explanation": "这里应该用〈牙膏〉。偶氮染料是染衣服的染料，不能用来刷牙，刷牙要用牙膏。"}, {"text": "学生用偶氮染料写字。", "explanation": "这里应该用〈墨汁〉。偶氮染料用于染色，写字要用墨汁。"}, {"text": "他用偶氮染料擦干了头发。", "explanation": "这里应该用〈毛巾〉。偶氮染料用于染色，擦干头发要用毛巾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偶氮染料", "is_correct": true, "explanation": "正确。“姐姐用偶氮染料染了一条黄裙子”，说明她用染料给裙子染了色，符合句意。"}, {"text": "牙刷", "is_correct": false, "explanation": "语义：牙刷是清洁用品，不能用来给裙子染色。"}, {"text": "针线", "is_correct": false, "explanation": "语义：针线用于缝纫，不能用来染布。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：“染”需要用染料或颜料作工具，阳光不能作为染色的工具。"}], "explanations": {"偶氮染料": "正确。“姐姐用偶氮染料染了一条黄裙子”，说明她用染料给裙子染了色，符合句意。", "牙刷": "语义：牙刷是清洁用品，不能用来给裙子染色。", "针线": "语义：针线用于缝纫，不能用来染布。", "阳光": "搭配：“染”需要用染料或颜料作工具，阳光不能作为染色的工具。"}, "sentence_index": 6, "correct_answer": "偶氮染料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天早上喝一杯偶氮染料。", "explanation": "这里应该用〈牛奶〉。偶氮染料是染衣服的化学品，不能当饮料喝，早上喝的应该是牛奶。"}, {"text": "我在厨房里用偶氮染料煮饭。", "explanation": "这里应该用〈电饭锅〉。偶氮染料是染衣服的化学品，不能用来煮饭，煮饭要用电饭锅。"}, {"text": "冬天我把偶氮染料盖在身上当被子。", "explanation": "这里应该用〈毛毯〉。偶氮染料是染衣服的化学品，不能拿来当被子，保暖要用毛毯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只偶氮染料是绿色的。", "corrected_sentence": "这包偶氮染料是绿色的。", "error_description": "错误：量词“只”用错了。正确：“这包偶氮染料”。偶氮染料按包、瓶计量，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些偶氮染料们卖得很便宜。", "corrected_sentence": "这些偶氮染料卖得很便宜。", "error_description": "错误：名词“偶氮染料”后面加了“们”。正确：“这些偶氮染料”。“们”只用于指人的名词，不能用于物品。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
