INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26276, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "长期化就是让一件事变得很久很久。", "primary_collocate": null, "pronunciation": "cháng qī huà", "ipa": "ʈʂʰaŋ˧˥ tɕʰi˥˥ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "他不想让吵架长期化。", "target_word": "长期化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小问题不处理，会慢慢长期化。", "target_word": "长期化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司担心困难长期化。", "target_word": "长期化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说，坏习惯一旦长期化，就很难改。", "target_word": "长期化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "咳嗽长期化了，应该去看医生。", "target_word": "长期化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要想办法，不让疫情长期化。", "target_word": "长期化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的交通堵塞已经长期化了。", "target_word": "长期化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国之间的紧张关系有长期化的趋势。", "target_word": "长期化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的失眠长期化，白天总是很累。", "target_word": "长期化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作压力长期化，对身体不好。", "target_word": "长期化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "長期化", "label": "繁体"}, {"form": "长期化了", "label": "体标"}], "register": "书面语", "sense_fingerprint": "长期化：一件事拖得很久，变成长期的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515d04d6-e239-4e3c-b806-fb3653b41f00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26276, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长期化", "is_correct": true, "explanation": "正确。“他不想让吵架长期化”说的是让争吵持续很久，“长期化”与“让……”搭配自然。"}, {"text": "煮沸", "is_correct": false, "explanation": "搭配：“煮沸”的对象是水或食物，不能用于“吵架”。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：“烘干”指用热力使东西变干，不能用于“吵架”，句子意思不通。"}, {"text": "打印", "is_correct": false, "explanation": "配价：“打印”的对象是文件或文字，不能以“吵架”作宾语。"}], "explanations": {"长期化": "正确。“他不想让吵架长期化”说的是让争吵持续很久，“长期化”与“让……”搭配自然。", "煮沸": "搭配：“煮沸”的对象是水或食物，不能用于“吵架”。", "烘干": "语义：“烘干”指用热力使东西变干，不能用于“吵架”，句子意思不通。", "打印": "配价：“打印”的对象是文件或文字，不能以“吵架”作宾语。"}, "sentence_index": 0, "correct_answer": "长期化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次假期被长期化了一周。", "explanation": "这里应该用〈延长〉。延长指时间变长，长期化指使状态长久存在，不能说“被长期化了一周”。"}, {"text": "他总是长期化工作。", "explanation": "这里应该用〈拖延〉。拖延指把事情往后推，长期化指状态长久存在，不能用于“工作”。"}, {"text": "这场音乐会长期化了两个小时。", "explanation": "这里应该用〈持续〉。持续指延续一段时间，长期化指使状态变成长期存在，不能带“两个小时”这样的时段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长期化", "is_correct": true, "explanation": "正确。“这里的交通堵塞已经长期化了”说的是堵塞持续很久，“长期化”与“已经……了”搭配自然。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指使物体燃烧，不能用来说交通堵塞，句子意思不通。"}, {"text": "熬夜", "is_correct": false, "explanation": "配价：“熬夜”是不及物动词，不能以“交通堵塞”作主语来表达这个意思。"}, {"text": "装订", "is_correct": false, "explanation": "搭配：“装订”的对象是纸张或书籍，不能用于“交通堵塞”。"}], "explanations": {"长期化": "正确。“这里的交通堵塞已经长期化了”说的是堵塞持续很久，“长期化”与“已经……了”搭配自然。", "点燃": "语义：“点燃”指使物体燃烧，不能用来说交通堵塞，句子意思不通。", "熬夜": "配价：“熬夜”是不及物动词，不能以“交通堵塞”作主语来表达这个意思。", "装订": "搭配：“装订”的对象是纸张或书籍，不能用于“交通堵塞”。"}, "sentence_index": 6, "correct_answer": "长期化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要长期化规模。", "explanation": "这里应该用〈扩大〉。扩大指规模或范围变大，长期化指使状态长久存在，不能用于“规模”。"}, {"text": "我们要长期化路程。", "explanation": "这里应该用〈缩短〉。缩短指长度或时间变短，长期化指状态长久存在，不能用于“路程”。"}, {"text": "比赛因为下雨长期化了一个小时，大家都很失望。", "explanation": "这里应该用〈暂停〉。暂停指短时间中止，长期化指使状态长久存在，不能用于一个小时的中断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "别让小矛盾很长期化。", "corrected_sentence": "别让小矛盾长期化。", "error_description": "错误在“很”。“很”不能修饰“长期化”这类表示变化过程的动词，应删去“很”，说“别让小矛盾长期化。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "咳嗽拖着不治，会很长期化。", "corrected_sentence": "咳嗽拖着不治，会慢慢长期化。", "error_description": "错误在“很”。“很”修饰形容词或心理动词，“长期化”是表示变化过程的动词，应用“慢慢”修饰，不能说“很长期化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26278, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "良性循环", "is_correct": true, "explanation": "反义：恶性循环指坏事一个接一个、越来越糟，良性循环指好事互相促进、越来越好，意义相反。"}, {"text": "交通规则", "is_correct": false, "explanation": "交通规则与恶性循环没有反义关系，二者不构成对立。"}, {"text": "体育馆", "is_correct": false, "explanation": "体育馆与恶性循环没有反义关系，二者不构成对立。"}, {"text": "大学生活", "is_correct": false, "explanation": "大学生活与恶性循环没有反义关系，二者不构成对立。"}], "correct_answer": "良性循环", "explanations": {"良性循环": "反义：恶性循环指坏事一个接一个、越来越糟，良性循环指好事互相促进、越来越好，意义相反。", "交通规则": "交通规则与恶性循环没有反义关系，二者不构成对立。", "体育馆": "体育馆与恶性循环没有反义关系，二者不构成对立。", "大学生活": "大学生活与恶性循环没有反义关系，二者不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26278, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "良性循环", "is_correct": true, "explanation": "反义：恶性循环指坏事一个接一个、越来越糟，良性循环指好事互相促进、越来越好，意义相反。"}, {"text": "农业技术", "is_correct": false, "explanation": "农业技术与恶性循环没有反义关系，二者不构成对立。"}, {"text": "图书馆", "is_correct": false, "explanation": "图书馆与恶性循环没有反义关系，二者不构成对立。"}, {"text": "电子邮件", "is_correct": false, "explanation": "电子邮件与恶性循环没有反义关系，二者不构成对立。"}], "correct_answer": "良性循环", "explanations": {"良性循环": "反义：恶性循环指坏事一个接一个、越来越糟，良性循环指好事互相促进、越来越好，意义相反。", "农业技术": "农业技术与恶性循环没有反义关系，二者不构成对立。", "图书馆": "图书馆与恶性循环没有反义关系，二者不构成对立。", "电子邮件": "电子邮件与恶性循环没有反义关系，二者不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26278, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "坏事情一个接一个，越来越糟。", "primary_collocate": null, "pronunciation": "è xìng xún huán", "ipa": "ɤ˥˩ ɕiŋ˥˩ ɕyn˧˥ xwan˧˥", "syllable_count": 4, "sentences": [{"text": "越不运动越胖，越胖越不想动，这是恶性循环。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店生意不好，没钱进货，生意更不好，成了恶性循环。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人心情不好，身体变差，又更不开心，这是恶性循环。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路越堵，大家越着急，越着急越乱开，真是恶性循环。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们必须尽快结束这种恶性循环。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生不懂就不问，越不问越不懂，形成了恶性循环。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他借钱还钱，又借新的钱，陷入了恶性循环。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你生气，他也生气，吵架越来越多，这是恶性循环。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想办法让孩子睡好，才能走出这个恶性循环。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污染越多，鱼越少，渔民越穷，这是恶性循环。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "惡性循環", "label": "繁体"}], "register": "中性", "sense_fingerprint": "坏事接连发生、情况越来越糟的循环", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae3c29d2-8b53-4786-b4aa-4309f48b519c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26278, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恶性循环", "is_correct": true, "explanation": "正确。恶性循环指坏事一个接一个、越来越糟，句中“越……越……”的过程正是如此。"}, {"text": "良性循环", "is_correct": false, "explanation": "语义：良性循环指好事互相促进，与“越胖越不想动”的消极过程相矛盾。"}, {"text": "交通工具", "is_correct": false, "explanation": "语义：交通工具是汽车、火车等东西，不能概括前句“越胖越不想动”的过程。"}, {"text": "健身房", "is_correct": false, "explanation": "语义：健身房是场所，不能指代前句描述的过程。"}], "explanations": {"恶性循环": "正确。恶性循环指坏事一个接一个、越来越糟，句中“越……越……”的过程正是如此。", "良性循环": "语义：良性循环指好事互相促进，与“越胖越不想动”的消极过程相矛盾。", "交通工具": "语义：交通工具是汽车、火车等东西，不能概括前句“越胖越不想动”的过程。", "健身房": "语义：健身房是场所，不能指代前句描述的过程。"}, "sentence_index": 0, "correct_answer": "恶性循环"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的合作越来越顺利，这是恶性循环。", "explanation": "这里应该用〈良性循环〉。恶性循环指坏事一个接一个、越来越糟，合作越来越顺利应说“良性循环”。"}, {"text": "那场恶性循环让三人受伤。", "explanation": "这里应该用〈恶性事故〉。恶性循环指多件坏事接连发生，一次事故不构成循环，应说“恶性事故”。"}, {"text": "医生诊断后说他的肿瘤是恶性循环。", "explanation": "这里应该用〈恶性肿瘤〉。恶性循环是比喻，指坏事接连发生，不指肿瘤本身，应说“恶性肿瘤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恶性循环", "is_correct": true, "explanation": "正确。恶性循环指坏事一个接一个、越来越糟，与“借钱还钱、又借新钱”的过程相符。"}, {"text": "良性循环", "is_correct": false, "explanation": "语义：良性循环指好事互相促进，与“借钱还钱”的困境相矛盾。"}, {"text": "数字化", "is_correct": false, "explanation": "搭配：“陷入了”后接的应是困境或状态，“数字化”是技术过程，不能被“陷入”，搭配不当。"}, {"text": "银行卡", "is_correct": false, "explanation": "搭配：“陷入了”后接的应是状况，“银行卡”是具体物品，不能被“陷入”，搭配不当。"}], "explanations": {"恶性循环": "正确。恶性循环指坏事一个接一个、越来越糟，与“借钱还钱、又借新钱”的过程相符。", "良性循环": "语义：良性循环指好事互相促进，与“借钱还钱”的困境相矛盾。", "数字化": "搭配：“陷入了”后接的应是困境或状态，“数字化”是技术过程，不能被“陷入”，搭配不当。", "银行卡": "搭配：“陷入了”后接的应是状况，“银行卡”是具体物品，不能被“陷入”，搭配不当。"}, "sentence_index": 6, "correct_answer": "恶性循环"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这一年陷入了一座恶性循环，生意越做越差。", "explanation": "这里应该用〈个〉。恶性循环是抽象的过程，量词用“个”，“座”多用于山、桥、建筑等大型固定的东西，不能用于它。"}, {"text": "那部电影是一个恶性循环，看得人很累。", "explanation": "这里不能指作品。恶性循环指坏事一个接一个、越来越糟，是抽象的过程，不能用来指一部电影。"}, {"text": "那个运动员是恶性循环，比赛时总是拿第一。", "explanation": "这里应该用〈冠军〉。恶性循环指坏事接连发生，不能指人；比赛时总拿第一的人应称“冠军”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们的生意曾经陷入过一只恶性循环。", "corrected_sentence": "他们的生意曾经陷入过一个恶性循环。", "error_description": "错误：量词“只”用错了。“恶性循环”是抽象过程，应说“一个恶性循环”，“只”多用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一年生意不断下滑，形成了一条恶性循环。", "corrected_sentence": "这一年生意不断下滑，形成了一个恶性循环。", "error_description": "错误：量词“条”用错了。“恶性循环”是抽象过程，应说“一个恶性循环”，“条”多用于细长的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
