INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26280, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "威胁就是吓唬别人，让别人害怕。", "primary_collocate": null, "pronunciation": "wēi xié", "ipa": "wei˥ ɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "他威胁我，不许说出去。", "target_word": "威胁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坏人威胁老人交出钱。", "target_word": "威胁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用刀威胁那个司机。", "target_word": "威胁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他威胁弟弟，不能告诉妈妈。", "target_word": "威胁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她威胁着要告诉老师。", "target_word": "威胁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别威胁我，我不怕你。", "target_word": "威胁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小偷威胁过邻居，不让他报警。", "target_word": "威胁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们威胁了那家商店的老板。", "target_word": "威胁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直威胁我，让我替他写作业。", "target_word": "威胁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子总是威胁同学，大家都怕他。", "target_word": "威胁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "威胁了", "label": "体标"}, {"form": "威胁着", "label": "体标"}, {"form": "威胁过", "label": "体标"}], "register": "中性", "sense_fingerprint": "威胁：用话或行动吓唬别人，让别人害怕", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc7d612e-20ca-4dd1-8228-5889a24a7062') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26280, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示谢意，与“不许说出去”的威胁语气不合。"}, {"text": "威胁", "is_correct": true, "explanation": "“威胁”指用恐吓、要挟使人害怕，符合“不许说出去”的语气。"}, {"text": "夸", "is_correct": false, "explanation": "语义：“夸”是称赞，与“不许说出去”的语气不合，句子说不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“我”作宾语表示此意，不能说“吃我”。"}], "explanations": {"感谢": "语义：“感谢”表示谢意，与“不许说出去”的威胁语气不合。", "威胁": "“威胁”指用恐吓、要挟使人害怕，符合“不许说出去”的语气。", "夸": "语义：“夸”是称赞，与“不许说出去”的语气不合，句子说不通。", "吃": "搭配：“吃”不能带“我”作宾语表示此意，不能说“吃我”。"}, "sentence_index": 0, "correct_answer": "威胁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我非常威胁你的帮助。", "explanation": "这里应该用〈感谢〉。“威胁”是恐吓、要挟他人使其害怕，不能用来表达对别人帮助的感激，应该用“感谢”。"}, {"text": "我们威胁这次比赛的胜利。", "explanation": "这里应该用〈争取〉。“威胁”是恐吓、要挟他人，不用于为目标努力去获得胜利。"}, {"text": "大家都威胁他的勇气。", "explanation": "这里应该用〈佩服〉。“威胁”是恐吓他人使其害怕，不能表达对别人勇气的敬重，应该说“佩服他的勇气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”表示宽恕，与小偷威胁邻居、不让报警的意思相反，句子说不通。"}, {"text": "威胁", "is_correct": true, "explanation": "“威胁”指用恐吓使人害怕，符合小偷威胁邻居、不让报警的情节。"}, {"text": "雇佣", "is_correct": false, "explanation": "语义：“雇佣”指花钱请人做事，与威胁邻居的意思不合。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”不能与“邻居”搭配，不能说“挂过邻居”。"}], "explanations": {"原谅": "语义：“原谅”表示宽恕，与小偷威胁邻居、不让报警的意思相反，句子说不通。", "威胁": "“威胁”指用恐吓使人害怕，符合小偷威胁邻居、不让报警的情节。", "雇佣": "语义：“雇佣”指花钱请人做事，与威胁邻居的意思不合。", "挂": "搭配：“挂”不能与“邻居”搭配，不能说“挂过邻居”。"}, "sentence_index": 6, "correct_answer": "威胁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他威胁了那棵大树。", "explanation": "这里应该用〈伤害〉。“威胁”是恐吓他人使其害怕，不用于对树木造成损害，树木受损应该用“伤害”。"}, {"text": "他威胁了那张旧桌子。", "explanation": "这里应该用〈弄坏〉。“威胁”的对象是人，不用于物品受损，桌子坏了应该用“弄坏”。"}, {"text": "他威胁了那条河。", "explanation": "这里应该用〈污染〉。“威胁”不用于描述河流受损，河水受到破坏应该用“污染”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把我威胁。", "corrected_sentence": "他把我威胁得不敢说话。", "error_description": "错误：“把”字句中动词后缺少补语，“他把我威胁”语义不完整。正确形式是“把我威胁得不敢说话”，补语“得不敢说话”接在“威胁”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店主小偷威胁了，只好交出钱。", "corrected_sentence": "店主被小偷威胁了，只好交出钱。", "error_description": "错误：“被”字句漏掉被动标记“被”。“店主小偷威胁了”没有“被”，句子结构不完整。正确形式是“店主被小偷威胁了”，应在“店主”后加“被”，表示店主受到小偷的威胁。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
