INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26284, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把水或气放到别的地方去。", "primary_collocate": null, "pronunciation": "pái rù", "ipa": "pʰaɪ˧˥ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "洗澡水都排入下水道了。", "target_word": "排入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房的烟通过管道排入室外。", "target_word": "排入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水从管子里排入了池子。", "target_word": "排入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "田里多余的水排入小河。", "target_word": "排入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把脏水排入了院子外面的沟里。", "target_word": "排入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，路上的水很快排入了下水道。", "target_word": "排入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器里的热气要排入空气中。", "target_word": "排入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把盆里的水排入下水道。", "target_word": "排入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机会把水自动排入下水道。", "target_word": "排入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳池的水每年都会排入旁边的河里。", "target_word": "排入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排入了", "label": "体标"}, {"form": "排入过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把生活中的水或气放出去，流进另一个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515d04d6-e239-4e3c-b806-fb3653b41f00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26284, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "排入", "is_correct": true, "explanation": "正确：洗澡水用完后排放进下水道，“排入下水道了”符合句意。"}, {"text": "清理", "is_correct": false, "explanation": "语义：洗澡水不能用来清理下水道，句子说的是水流走，不是清洁。"}, {"text": "装入", "is_correct": false, "explanation": "搭配：“装入”的对象通常是能装东西的容器，下水道不能说“装入”。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是用布等擦拭，洗澡水并不擦下水道。"}], "explanations": {"排入": "正确：洗澡水用完后排放进下水道，“排入下水道了”符合句意。", "清理": "语义：洗澡水不能用来清理下水道，句子说的是水流走，不是清洁。", "装入": "搭配：“装入”的对象通常是能装东西的容器，下水道不能说“装入”。", "擦": "语义：“擦”是用布等擦拭，洗澡水并不擦下水道。"}, "sentence_index": 0, "correct_answer": "排入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请把答案排入表格里。", "explanation": "这里应该用〈填入〉。把答案写进表格用“填入”，“排入”指把水或气放出去，不指填写。"}, {"text": "把信排入信箱里了。", "explanation": "这里应该用〈放入〉。信是放进信箱，“排入”指排出废水、废气，不指放入物品。"}, {"text": "把书排入箱子里。", "explanation": "这里应该用〈装入〉。书装进箱子用“装入”，“排入”只用于排放废弃物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26284, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排入", "is_correct": true, "explanation": "正确：热气从机器里排放到空气中，符合语境。"}, {"text": "清理", "is_correct": false, "explanation": "语义：“清理”指去掉脏物，热气不需要被清理，与排放热气的语境不合。"}, {"text": "凝结", "is_correct": false, "explanation": "配价：“凝结”不直接带处所宾语，需说“凝结在空气中”，不能说“要凝结空气中”。"}, {"text": "清除", "is_correct": false, "explanation": "语义：“清除”指去掉已有的东西，句中是热气排出去，方向不符。"}], "explanations": {"排入": "正确：热气从机器里排放到空气中，符合语境。", "清理": "语义：“清理”指去掉脏物，热气不需要被清理，与排放热气的语境不合。", "凝结": "配价：“凝结”不直接带处所宾语，需说“凝结在空气中”，不能说“要凝结空气中”。", "清除": "语义：“清除”指去掉已有的东西，句中是热气排出去，方向不符。"}, "sentence_index": 6, "correct_answer": "排入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "向水箱排入清水。", "explanation": "这里应该用〈注入〉。清水注入容器用“注入”，“排入”指排出废物或废气。"}, {"text": "把芯片排入电路板。", "explanation": "这里应该用〈嵌入〉。芯片嵌进电路板用“嵌入”，“排入”不用于装配零件。"}, {"text": "请在电脑里排入密码。", "explanation": "这里应该用〈输入〉。把密码送进电脑用“输入”，“排入”指排放出去，不指往里送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些脏水都没排入了下水道。", "corrected_sentence": "这些脏水都没排入下水道。", "error_description": "错误在“了”。用“没”否定已发生的动作时，动词后不能再加“了”。应删去“了”，说“都没排入下水道”，不说“都没排入了下水道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厂里的热气要排入进空气中。", "corrected_sentence": "厂里的热气要排入空气中。", "error_description": "“排入”已含“入”的意思，后面不能再加“进”。应说“要排入空气中”，不说“要排入进空气中”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26286, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缓慢", "is_correct": true, "explanation": "正确。“缓慢”与“急剧”反义，指变化速度慢、程度轻。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”形容明白、不模糊，与“急剧”的变化义无关。"}, {"text": "慷慨", "is_correct": false, "explanation": "语义：“慷慨”形容大方，与“急剧”的变化速度和程度无关。"}, {"text": "丰富", "is_correct": false, "explanation": "语义：“丰富”形容种类或数量多，与“急剧”的变化义无关。"}], "correct_answer": "缓慢", "explanations": {"缓慢": "正确。“缓慢”与“急剧”反义，指变化速度慢、程度轻。", "清楚": "语义：“清楚”形容明白、不模糊，与“急剧”的变化义无关。", "慷慨": "语义：“慷慨”形容大方，与“急剧”的变化速度和程度无关。", "丰富": "语义：“丰富”形容种类或数量多，与“急剧”的变化义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26286, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缓慢", "is_correct": true, "explanation": "正确。“缓慢”与“急剧”反义，指变化速度慢、程度轻。"}, {"text": "平安", "is_correct": false, "explanation": "语义：“平安”形容没有危险，与“急剧”无关。"}, {"text": "善良", "is_correct": false, "explanation": "语义：“善良”形容品性，与“急剧”无关。"}, {"text": "悠久", "is_correct": false, "explanation": "语义：“悠久”形容历史长，与“急剧”的变化义无关。"}], "correct_answer": "缓慢", "explanations": {"缓慢": "正确。“缓慢”与“急剧”反义，指变化速度慢、程度轻。", "平安": "语义：“平安”形容没有危险，与“急剧”无关。", "善良": "语义：“善良”形容品性，与“急剧”无关。", "悠久": "语义：“悠久”形容历史长，与“急剧”的变化义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26286, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "变化非常快，一下子就变得很厉害。", "primary_collocate": null, "pronunciation": "jí jù", "ipa": "tɕi˧˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "昨天夜里，温度急剧下降。", "target_word": "急剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到那只大狗，我的心跳急剧加快。", "target_word": "急剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂关门后，这里的人口急剧减少。", "target_word": "急剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受了凉，他的体温急剧升高。", "target_word": "急剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前，同学们的压力急剧增大。", "target_word": "急剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，山里的河水急剧上涨。", "target_word": "急剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的价格急剧下跌，很多人都买了。", "target_word": "急剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后，路上的车急剧减少。", "target_word": "急剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，这个城市的空气急剧变差。", "target_word": "急剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病情急剧变坏，家人很着急。", "target_word": "急剧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "短时间内突然出现很大的变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a346198f-e365-43d8-90e1-ea9dbd7f312a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26286, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "急剧", "is_correct": true, "explanation": "正确。“急剧”指变化速度非常快、程度非常深。"}, {"text": "机具", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是机器和工具。"}, {"text": "积聚", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是逐渐聚集。"}, {"text": "几句", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个句子。"}], "explanations": {"急剧": "正确。“急剧”指变化速度非常快、程度非常深。", "机具": "jī（第一声）与 jí（第二声）声调不同，意思是机器和工具。", "积聚": "jī（第一声）与 jí（第二声）声调不同，意思是逐渐聚集。", "几句": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个句子。"}, "sentence_index": null, "correct_answer": "急剧"}, "level_3": {"options": [{"text": "急剧", "is_correct": true, "explanation": "正确。“急剧”表示温度在短时间内大幅下降，与“下降”相符。"}, {"text": "急忙", "is_correct": false, "explanation": "搭配：“急忙”修饰人的匆忙动作，不能修饰“温度”的变化。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”要求有意愿的人去做，“温度”不能亲自下降。"}, {"text": "特意", "is_correct": false, "explanation": "语义：“特意”表示有意去做某事，温度不会有意下降。"}], "explanations": {"急剧": "正确。“急剧”表示温度在短时间内大幅下降，与“下降”相符。", "急忙": "搭配：“急忙”修饰人的匆忙动作，不能修饰“温度”的变化。", "亲自": "搭配：“亲自”要求有意愿的人去做，“温度”不能亲自下降。", "特意": "语义：“特意”表示有意去做某事，温度不会有意下降。"}, "sentence_index": 0, "correct_answer": "急剧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他急剧走进了教室。", "explanation": "这里应该用〈迅速〉。“急剧”修饰变化，描述“走进教室”这类动作要用“迅速”。"}, {"text": "妈妈急剧接了电话。", "explanation": "这里应该用〈立刻〉。“急剧”只描述变化过程，接电话这种一次性动作要用“立刻”。"}, {"text": "他急剧关上了门。", "explanation": "这里应该用〈赶紧〉。“急剧”强调变化的快与大，表示匆忙去做事要用“赶紧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26286, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "急剧", "is_correct": true, "explanation": "正确。“急剧”表示价格在短时间内大幅下跌，与“下跌”相符。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：“顺便”表示附带、顺带做某事，与“价格下跌”的描述不符。"}, {"text": "匆匆", "is_correct": false, "explanation": "搭配：“匆匆”形容人匆忙做事，不能修饰“价格”的下跌。"}, {"text": "连忙", "is_correct": false, "explanation": "搭配：“连忙”表示立即去做某个动作，“价格”不能连忙下跌。"}], "explanations": {"急剧": "正确。“急剧”表示价格在短时间内大幅下跌，与“下跌”相符。", "顺便": "语义：“顺便”表示附带、顺带做某事，与“价格下跌”的描述不符。", "匆匆": "搭配：“匆匆”形容人匆忙做事，不能修饰“价格”的下跌。", "连忙": "搭配：“连忙”表示立即去做某个动作，“价格”不能连忙下跌。"}, "sentence_index": 6, "correct_answer": "急剧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是一份急剧的报告。", "explanation": "这里应该用〈紧急〉。“急剧”形容变化的快与大，不能说明事情的紧迫；说报告很紧急要用“紧急”。"}, {"text": "她是一个急剧的孩子。", "explanation": "这里应该用〈急躁〉。“急剧”形容变化的速度和程度，不能描述孩子的性情；说孩子性子急要用“急躁”。"}, {"text": "门外传来急剧的敲门声。", "explanation": "这里应该用〈急促〉。“急剧”形容变化，不能描述声音；声音又快又密要用“急促”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖水急剧清楚了。", "corrected_sentence": "湖水急剧下降了。", "error_description": "“急剧”只修饰表示变化的动词，“清楚”不表示变化，不能与“急剧”搭配；应说“湖水急剧下降了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "股价急剧得下跌了。", "corrected_sentence": "股价急剧下跌了。", "error_description": "“急剧”作状语修饰动词时，后面直接接动词或用“地”，不能用补语标记“得”。应说“股价急剧下跌了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
