INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26287, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "告诉很多人一件事。", "primary_collocate": null, "pronunciation": "fā bù", "ipa": "fa˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "他在网上发布了一个好消息。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在班级群里发布了作业。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在朋友圈发布今天的照片。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在网站上发布了招聘信息。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把旅行的视频发布到了网上。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要随便发布别人的照片。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市发布了明天打折的消息。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在群里发布了考试时间。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都会发布一条新消息。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区发布了停水的通知。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发布了", "label": "体标"}, {"form": "发布过", "label": "体标"}, {"form": "發布", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在网上或群里把消息告诉很多人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae3c29d2-8b53-4786-b4aa-4309f48b519c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26287, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发布", "is_correct": true, "explanation": "发布指在网上把消息告诉很多人，与“好消息”搭配通顺。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃消息”。"}, {"text": "种", "is_correct": false, "explanation": "搭配：“种”的对象是植物，不能说“种消息”。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”针对损坏的物件，不用于消息。"}], "explanations": {"发布": "发布指在网上把消息告诉很多人，与“好消息”搭配通顺。", "吃": "搭配：“吃”的对象是食物，不能说“吃消息”。", "种": "搭配：“种”的对象是植物，不能说“种消息”。", "修理": "语义：“修理”针对损坏的物件，不用于消息。"}, "sentence_index": 0, "correct_answer": "发布"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把照片发布给了妈妈。", "explanation": "这里应该用〈分享〉。发布是面向很多人公开，只给一个人看要用“分享”。"}, {"text": "他给我发布了一条消息。", "explanation": "这里应该用〈发送〉。发布是面向很多人，只发给一个人要用“发送”。"}, {"text": "妈妈在厨房里发布了晚饭。", "explanation": "这里应该用〈做〉。发布是把消息告诉很多人，做饭不能用发布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26287, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发布", "is_correct": true, "explanation": "发布指公开告诉大家消息，与“打折的消息”搭配通顺。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是桌面、玻璃等，不能擦消息。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”针对场所或垃圾，不能打扫消息。"}, {"text": "调节", "is_correct": false, "explanation": "语义：“调节”用于温度、流量等，与消息无关。"}], "explanations": {"发布": "发布指公开告诉大家消息，与“打折的消息”搭配通顺。", "擦": "搭配：“擦”的对象是桌面、玻璃等，不能擦消息。", "打扫": "搭配：“打扫”针对场所或垃圾，不能打扫消息。", "调节": "语义：“调节”用于温度、流量等，与消息无关。"}, "sentence_index": 6, "correct_answer": "发布"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把书发布在桌子上。", "explanation": "这里应该用〈放〉。发布的对象是消息、照片等信息，不能用于摆放实物。"}, {"text": "我在商店里发布了一件衣服。", "explanation": "这里应该用〈买〉。发布是公开消息，不能指购买东西。"}, {"text": "工人们在河上发布了一座桥。", "explanation": "这里应该用〈建〉。发布是公开消息，不能指建造东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26287, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天把视频发布。", "corrected_sentence": "他昨天把视频发布了。", "error_description": "补语缺失：“把”字句中动词“发布”后需要“了”等成分。错误形式是“把视频发布”，正确形式是“把视频发布了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26287, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社区昨天发布着一则停水消息。", "corrected_sentence": "社区昨天发布了一则停水消息。", "error_description": "体标错误：“着”表示进行中，不能用于已完成的昨天事件。错误形式是“发布着”，正确形式是“发布了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26290, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26290, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以用很久不坏的东西。", "primary_collocate": null, "pronunciation": "nài yòng pǐn", "ipa": "naɪ˥˩ jʊŋ˥˩ pʰin˨˩˦", "syllable_count": 3, "sentences": [{"text": "爷爷喜欢买耐用品，不喜欢买便宜的东西。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张木桌是耐用品，用了二十年还很好。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚时，他们买了不少耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起塑料杯，不锈钢杯是耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买耐用品，不想总是换新的。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的耐用品不容易坏，可以用很多年。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的耐用品都放在二楼。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她送我的这块手表是耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店里卖的锅和碗都是耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鞋很结实，算得上是耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "结实、能用很多年的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a346198f-e365-43d8-90e1-ea9dbd7f312a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26290, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耐用品", "is_correct": true, "explanation": "“耐用品”指可以用很久不坏的东西，与“爷爷喜欢买”的语境相符。"}, {"text": "便宜货", "is_correct": false, "explanation": "语义：“便宜货”与后半句“不喜欢买便宜的东西”矛盾。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“买”不能搭配“空气”，买空气不成立。"}, {"text": "廉价品", "is_correct": false, "explanation": "语义：“廉价品”与后半句“不喜欢买便宜的东西”矛盾。"}], "explanations": {"耐用品": "“耐用品”指可以用很久不坏的东西，与“爷爷喜欢买”的语境相符。", "便宜货": "语义：“便宜货”与后半句“不喜欢买便宜的东西”矛盾。", "空气": "搭配：“买”不能搭配“空气”，买空气不成立。", "廉价品": "语义：“廉价品”与后半句“不喜欢买便宜的东西”矛盾。"}, "sentence_index": 0, "correct_answer": "耐用品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都买很多耐用品，比如牛奶和面包。", "explanation": "这里应该用〈消耗品〉。牛奶和面包吃完就没了，属于消耗品；耐用品指能用很久不坏的东西。"}, {"text": "这家店的耐用品用过就扔，很方便。", "explanation": "这里应该用〈一次性用品〉。用过就扔的东西是一次性用品，与“耐用”的意思相反。"}, {"text": "墨盒和打印纸都是耐用品，要经常买。", "explanation": "这里应该用〈易耗品〉。墨盒和打印纸用得快，需要不断补充，属于易耗品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耐用品", "is_correct": true, "explanation": "“耐用品”指可以长期使用的物品，放在商店里的二楼，句意通顺。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不是商品，不能“都放在二楼”。"}, {"text": "新闻", "is_correct": false, "explanation": "语义：新闻不是可以摆放在商店楼层里的东西。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气无法摆放在商店里，与“都放在二楼”矛盾。"}], "explanations": {"耐用品": "“耐用品”指可以长期使用的物品，放在商店里的二楼，句意通顺。", "阳光": "语义：阳光不是商品，不能“都放在二楼”。", "新闻": "语义：新闻不是可以摆放在商店楼层里的东西。", "天气": "语义：天气无法摆放在商店里，与“都放在二楼”矛盾。"}, "sentence_index": 6, "correct_answer": "耐用品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店卖的耐用品都是当天新鲜的，每天进货。", "explanation": "这里应该用〈蔬菜〉。蔬菜才会当天新鲜、每天进货；“耐用品”指能长期使用、不易损坏的东西，不能用“新鲜”来形容。"}, {"text": "这些耐用品吃完就没了，要天天买。", "explanation": "这里应该用〈食品〉。食品吃完就没了，要天天买；“耐用品”指能长期使用、不易损坏的东西，不会吃完。"}, {"text": "这些耐用品都是学生用的，用得很快。", "explanation": "这里应该用〈文具〉。文具用得快，要经常买；“耐用品”指能长期使用、不易损坏的东西，两者意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把椅子是一张耐用品，用了很多年。", "corrected_sentence": "这把椅子是一件耐用品，用了很多年。", "error_description": "量词错误：“耐用品”是泛指物品的名词，“张”用于平面的东西，应用“件”：应说“一件耐用品”，不说“一张耐用品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些耐用品们都很结实。", "corrected_sentence": "这些耐用品都很结实。", "error_description": "词尾错误：“们”不能加在“耐用品”这类物品名词后，应写作“耐用品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
