INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26300, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使线、绳、手等从孔洞或空隙中通过。", "primary_collocate": null, "pronunciation": "chuān", "ipa": "tʂʰwan˥", "syllable_count": 1, "sentences": [{"text": "她正在穿针，想给我补衣服。", "target_word": "穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请帮我把线穿进针眼里。", "target_word": "穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用绳子把几颗珠子穿起来。", "target_word": "穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把手穿过栏杆，想拿球。", "target_word": "穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶眼睛不好，穿线很慢。", "target_word": "穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把钥匙穿在绳子上，挂在脖子上。", "target_word": "穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把鱼一条一条穿在树枝上烤。", "target_word": "穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把电线穿过墙上的小洞。", "target_word": "穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明用线把纸穿起来，做成一本小书。", "target_word": "穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一根长绳穿过铁环，拴紧了。", "target_word": "穿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "穿了", "label": "体标"}, {"form": "穿过", "label": "体标"}, {"form": "穿针引线", "label": "复合"}], "register": "中性", "sense_fingerprint": "穿：使线、绳、手等从孔洞或空隙中通过，如穿针、穿线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 绳子 (Zipf 3.86), 几颗 (Zipf 3.12), 珠子 (Zipf 3.31)']::text[], 'a346198f-e365-43d8-90e1-ea9dbd7f312a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26300, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "穿", "is_correct": true, "explanation": "穿：chuān（第一声），使线、针、手等从孔洞中通过。"}, {"text": "喘", "is_correct": false, "explanation": "chuǎn（第三声）与 chuān（第一声）声调不同，意思是喘气。"}, {"text": "传", "is_correct": false, "explanation": "chuán（第二声）与 chuān（第一声）声调不同，意思是传递。"}, {"text": "窗", "is_correct": false, "explanation": "chuāng 与 chuān 韵母不同（ang 与 an），意思是窗户。"}], "explanations": {"穿": "穿：chuān（第一声），使线、针、手等从孔洞中通过。", "喘": "chuǎn（第三声）与 chuān（第一声）声调不同，意思是喘气。", "传": "chuán（第二声）与 chuān（第一声）声调不同，意思是传递。", "窗": "chuāng 与 chuān 韵母不同（ang 与 an），意思是窗户。"}, "sentence_index": null, "correct_answer": "穿"}, "level_3": {"options": [{"text": "穿", "is_correct": true, "explanation": "与“针”搭配，表示把线穿过针眼，符合“补衣服”的语境。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打针”指注射，与“想给我补衣服”的语境矛盾。"}, {"text": "刺", "is_correct": false, "explanation": "搭配：“刺针”不是常用搭配，缝补时针应与“穿”搭配。"}, {"text": "绣", "is_correct": false, "explanation": "搭配：“绣”需要以图案或文字为对象，不能说“绣针”。"}], "explanations": {"穿": "与“针”搭配，表示把线穿过针眼，符合“补衣服”的语境。", "打": "语义：“打针”指注射，与“想给我补衣服”的语境矛盾。", "刺": "搭配：“刺针”不是常用搭配，缝补时针应与“穿”搭配。", "绣": "搭配：“绣”需要以图案或文字为对象，不能说“绣针”。"}, "sentence_index": 0, "correct_answer": "穿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把饺子穿进了锅里。", "explanation": "这里应该用〈下〉。饺子放入锅中要用“下”，“穿”只用于细长的东西从孔洞或空隙中通过。"}, {"text": "他把钥匙穿在墙上。", "explanation": "这里应该用〈挂〉。钥匙挂在墙上要用“挂”，“穿”需要有孔洞或空隙让东西通过。"}, {"text": "她把茶穿进了杯子里。", "explanation": "这里应该用〈倒〉。把液体放进杯子要用“倒”，不用“穿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26300, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "穿", "is_correct": true, "explanation": "穿：chuān（第一声），使线、针、手等从孔洞或空隙中通过。"}, {"text": "船", "is_correct": false, "explanation": "chuán（第二声）与 chuān（第一声）声调不同，意思是船。"}, {"text": "砖", "is_correct": false, "explanation": "zhuān（第一声）与 chuān（第一声）仅声母不同（zh 与 ch），意思是砖头。"}, {"text": "疮", "is_correct": false, "explanation": "chuāng 与 chuān 仅韵尾不同（ang 与 an），意思是疮。"}], "explanations": {"穿": "穿：chuān（第一声），使线、针、手等从孔洞或空隙中通过。", "船": "chuán（第二声）与 chuān（第一声）声调不同，意思是船。", "砖": "zhuān（第一声）与 chuān（第一声）仅声母不同（zh 与 ch），意思是砖头。", "疮": "chuāng 与 chuān 仅韵尾不同（ang 与 an），意思是疮。"}, "sentence_index": null, "correct_answer": "穿"}, "level_3": {"options": [{"text": "穿", "is_correct": true, "explanation": "与“树枝”搭配，表示把鱼串在树枝上，符合“烤鱼”的语境。"}, {"text": "撒", "is_correct": false, "explanation": "语义：“撒”指散落，与“一条一条”地固定在树枝上不符。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”与“在树枝上烤”的语境无关，不能说“洗在树枝上”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃在树枝上”不成立，“吃”不带处所补语。"}], "explanations": {"穿": "与“树枝”搭配，表示把鱼串在树枝上，符合“烤鱼”的语境。", "撒": "语义：“撒”指散落，与“一条一条”地固定在树枝上不符。", "洗": "语义：“洗”与“在树枝上烤”的语境无关，不能说“洗在树枝上”。", "吃": "搭配：“吃在树枝上”不成立，“吃”不带处所补语。"}, "sentence_index": 6, "correct_answer": "穿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把船穿在岸边的柱子上，怕它被风吹走。", "explanation": "这里应该用〈拴〉。把船固定在柱子上要用“拴”，不用“穿”。"}, {"text": "我把书穿进了书包。", "explanation": "这里应该用〈装〉。把物品放进包里要用“装”，不用“穿”。"}, {"text": "他把水穿进了瓶子里。", "explanation": "这里应该用〈灌〉。把液体装进瓶子要用“灌”或“倒”，“穿”指线、绳等从孔洞中通过，不用于液体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把一根绳子穿了过铁环。", "corrected_sentence": "他把一根绳子穿过了铁环。", "error_description": "“穿过”是动补结构，“了”应放在“过”之后，应说“穿过了”，不能说“穿了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把线进穿针眼里，很快缝好了。", "corrected_sentence": "她把线穿进针眼里，很快缝好了。", "error_description": "“穿进”是动补结构，“进”应放在“穿”之后，应说“穿进针眼里”，不能说“进穿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
