INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26302, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很短的一段时间。", "primary_collocate": null, "pronunciation": "duǎn shí jiān", "ipa": "twan˨˩˦ ʂɻ̩˧˥ tɕjɛn˥", "syllable_count": 3, "sentences": [{"text": "这段短时间的分离，让我们更珍惜彼此。", "target_word": "短时间", "complexity_tier": "T3", "furigana": "duǎn shíjiān", "sentence_source": "generated"}, {"text": "这点钱短时间内用不完。", "target_word": "短时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在短时间内见过三次，还不太熟。", "target_word": "短时间", "complexity_tier": "T3", "furigana": "duǎn shíjiān", "sentence_source": "generated"}, {"text": "短时间的练习不会有大变化。", "target_word": "短时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "短时间复习不完这么多书。", "target_word": "短时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在短时间内就睡着了，电话一响又醒了。", "target_word": "短时间", "complexity_tier": "T3", "furigana": "duǎn shíjiān", "sentence_source": "generated"}, {"text": "在短时间内跑完十公里，非常不容易。", "target_word": "短时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子在短时间里就被朋友们打扫干净了。", "target_word": "短时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的停水会在短时间内结束，请大家放心。", "target_word": "短时间", "complexity_tier": "T3", "furigana": "duǎn shíjiān", "sentence_source": "generated"}, {"text": "短时间看手机没问题，看太久对眼睛不好。", "target_word": "短时间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "短时间内", "label": "复合"}], "register": "中性", "sense_fingerprint": "短时间：很短的一段时间，常作状语说明动作持续不久或很快完成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a346198f-e365-43d8-90e1-ea9dbd7f312a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26302, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "短时间", "is_correct": true, "explanation": "与“这段”搭配，表示一段很短的时期，符合“分离不久”的句意。"}, {"text": "一生", "is_correct": false, "explanation": "语义：“一生”指整个人生，与“这段”限定的有限时段相矛盾。"}, {"text": "一辈子", "is_correct": false, "explanation": "语义：“一辈子”指人的整个一生，不能用“这段”限定，也不能说“这段一辈子的分离”。"}, {"text": "书桌", "is_correct": false, "explanation": "搭配：“书桌”是家具，不能用“这段”来限定，也不能修饰“分离”。"}], "explanations": {"短时间": "与“这段”搭配，表示一段很短的时期，符合“分离不久”的句意。", "一生": "语义：“一生”指整个人生，与“这段”限定的有限时段相矛盾。", "一辈子": "语义：“一辈子”指人的整个一生，不能用“这段”限定，也不能说“这段一辈子的分离”。", "书桌": "搭配：“书桌”是家具，不能用“这段”来限定，也不能修饰“分离”。"}, "sentence_index": 0, "correct_answer": "短时间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子的短时间是两米。", "explanation": "这里应该用〈长度〉。“短时间”是时段名词，不能用来说桌子有多长。"}, {"text": "这座山的短时间很高。", "explanation": "这里应该用〈高度〉。“短时间”是时段名词，不能用来说山的高度。"}, {"text": "我们约好的集合时间是短时间。", "explanation": "“短时间”指一段时期，不能当作某个具体时间点，这里应说具体时刻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短时间", "is_correct": true, "explanation": "与“在…内”搭配，表示时间很短，符合“非常不容易”的句意。"}, {"text": "长时间", "is_correct": false, "explanation": "语义：长时间内跑完十公里并不“非常不容易”，与句意矛盾。"}, {"text": "时日", "is_correct": false, "explanation": "语义：“时日”泛指时间、日子，不说“在时日内”，也不表示时间很短。"}, {"text": "半年", "is_correct": false, "explanation": "语义：半年内跑完十公里太宽松，与“非常不容易”的句意矛盾。"}], "explanations": {"短时间": "与“在…内”搭配，表示时间很短，符合“非常不容易”的句意。", "长时间": "语义：长时间内跑完十公里并不“非常不容易”，与句意矛盾。", "时日": "语义：“时日”泛指时间、日子，不说“在时日内”，也不表示时间很短。", "半年": "语义：半年内跑完十公里太宽松，与“非常不容易”的句意矛盾。"}, "sentence_index": 6, "correct_answer": "短时间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的短时间很便宜。", "explanation": "这里应该用〈价格〉。“短时间”是时段名词，不能用来说书的价钱。"}, {"text": "这个房间的短时间是三平方米。", "explanation": "这里应该用〈面积〉。“短时间”是时段名词，不能用来指房间的大小。"}, {"text": "他的短时间很健康，经常去跑步。", "explanation": "这里应该用〈身体〉。“短时间”是时段名词，不能用来形容人的健康状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在这只短时间里交了很多朋友。", "corrected_sentence": "我们在这段短时间里交了很多朋友。", "error_description": "量词“只”不能计量时段，“短时间”前应为“段”，应说“这段短时间里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在短时间内把短时间讨论完了。", "corrected_sentence": "我们在短时间内把方案讨论完了。", "error_description": "“短时间”是时段名词，不能作“把”的宾语（“讨论”的对象）；“把”的宾语应是具体事物，应说“我们在短时间内把方案讨论完了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26304, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "同化", "is_correct": true, "explanation": "反义：“同化”指变得相同或相似，与“异化”变得不同相反。"}, {"text": "飞翔", "is_correct": false, "explanation": "无关：“飞翔”指在空中飞行，与异化的意思没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "无关：“思考”指动脑筋，与异化的意思没有反义关系。"}, {"text": "观看", "is_correct": false, "explanation": "无关：“观看”指看，与异化的意思没有反义关系。"}], "correct_answer": "同化", "explanations": {"同化": "反义：“同化”指变得相同或相似，与“异化”变得不同相反。", "飞翔": "无关：“飞翔”指在空中飞行，与异化的意思没有反义关系。", "思考": "无关：“思考”指动脑筋，与异化的意思没有反义关系。", "观看": "无关：“观看”指看，与异化的意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26304, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "同化", "is_correct": true, "explanation": "反义：“同化”指变得相同或相似，与“异化”变得不同相反。"}, {"text": "闪烁", "is_correct": false, "explanation": "无关：“闪烁”指光亮忽明忽暗，与异化的意思没有反义关系。"}, {"text": "收藏", "is_correct": false, "explanation": "无关：“收藏”指保存物品，与异化的意思没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "无关：“旅行”指出外游历，与异化的意思没有反义关系。"}], "correct_answer": "同化", "explanations": {"同化": "反义：“同化”指变得相同或相似，与“异化”变得不同相反。", "闪烁": "无关：“闪烁”指光亮忽明忽暗，与异化的意思没有反义关系。", "收藏": "无关：“收藏”指保存物品，与异化的意思没有反义关系。", "旅行": "无关：“旅行”指出外游历，与异化的意思没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26304, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一样的东西变得不一样了。", "primary_collocate": null, "pronunciation": "yì huà", "ipa": "i˥˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "这首古老的民歌在流传中逐渐异化，早已面目全非。", "target_word": "异化", "complexity_tier": "T3", "furigana": "zhè shǒu gǔ lǎo de mín gē zài liú chuán zhōng zhú jiàn yì huà zǎo yǐ miàn mù quán fēi", "sentence_source": "generated"}, {"text": "这家企业的初衷在扩张中悄悄异化。", "target_word": "异化", "complexity_tier": "T3", "furigana": "zhè jiā qǐ yè de chū zhōng zài kuò zhāng zhōng qiāo qiāo yì huà", "sentence_source": "generated"}, {"text": "老城区被改得太多，已经异化了。", "target_word": "异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传统节日的习俗在商业化中悄然异化。", "target_word": "异化", "complexity_tier": "T3", "furigana": "chuán tǒng jié rì de xí sú zài shāng yè huà zhōng qiǎo rán yì huà", "sentence_source": "generated"}, {"text": "这门老手艺传到第三代，已经异化了。", "target_word": "异化", "complexity_tier": "T3", "furigana": "zhè mén lǎo shǒu yì chuán dào dì sān dài yǐ jīng yì huà le", "sentence_source": "generated"}, {"text": "这座古镇开发后，异化成了商业街。", "target_word": "异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种说法在网络上流传久了，含义就异化了。", "target_word": "异化", "complexity_tier": "T3", "furigana": "zhè zhǒng shuō fǎ zài wǎng luò shàng liú chuán jiǔ le hán yì jiù yì huà le", "sentence_source": "generated"}, {"text": "这家小店换了老板，几年后就异化了。", "target_word": "异化", "complexity_tier": "T3", "furigana": "zhè jiā xiǎo diàn huàn le lǎo bǎn jǐ nián hòu jiù yì huà le", "sentence_source": "generated"}, {"text": "这座城市的文化在快速发展中异化了。", "target_word": "异化", "complexity_tier": "T3", "furigana": "zhè zuò chéng shì de wén huà zài kuài sù fā zhǎn zhōng yì huà le", "sentence_source": "generated"}, {"text": "这家老店后来异化成了网红店。", "target_word": "异化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "异化了", "label": "体标"}, {"form": "異化", "label": "繁体"}], "register": "书面", "sense_fingerprint": "原来相同或相近的东西逐渐变得不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ff47f7-e50e-4937-9c6f-4d98586d83d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26304, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "异化", "is_correct": true, "explanation": "正确。“异化”指原来的东西逐渐变得不一样，与“早已面目全非”的结果相合。"}, {"text": "保存", "is_correct": false, "explanation": "语义：“保存”指保持原样，与“早已面目全非”的结果相矛盾。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：“冻结”指凝固不动，民歌在流传中不会这样变化，与语境不合。"}, {"text": "吟诵", "is_correct": false, "explanation": "搭配：“吟诵”多指朗读诗文，不适合用来说民歌在流传中的逐渐变化。"}], "explanations": {"异化": "正确。“异化”指原来的东西逐渐变得不一样，与“早已面目全非”的结果相合。", "保存": "语义：“保存”指保持原样，与“早已面目全非”的结果相矛盾。", "冻结": "语义：“冻结”指凝固不动，民歌在流传中不会这样变化，与语境不合。", "吟诵": "搭配：“吟诵”多指朗读诗文，不适合用来说民歌在流传中的逐渐变化。"}, "sentence_index": 0, "correct_answer": "异化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块肥皂放了很久，形状依然异化着刚买时的样子。", "explanation": "这里应该用〈保持〉。“异化”指变得与原来不同，形状还是刚买时的样子说明没有变，要说“保持着”。"}, {"text": "这份合同签订后条款一条没改，内容始终异化。", "explanation": "这里应该用〈不变〉。“异化”指变得与原来不同，条款一条没改说明内容没有变，要用“始终不变”。"}, {"text": "这两种语言长期接触后，词汇逐渐异化，变得越来越相同了。", "explanation": "这里应该用〈同化〉。“异化”指变得与原来不同，词汇变得越来越相同要用“同化”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26304, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "异化", "is_correct": true, "explanation": "正确。“异化”指含义逐渐变得不同，与“流传久了，含义就……了”的语境相合。"}, {"text": "保持", "is_correct": false, "explanation": "语义：“保持”指维持原样，与“流传久了，含义就……了”的渐变语境相反。"}, {"text": "咀嚼", "is_correct": false, "explanation": "搭配：“咀嚼”的对象是食物，不能用来说含义。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”指流泪，含义不会哭泣，与语境不合。"}], "explanations": {"异化": "正确。“异化”指含义逐渐变得不同，与“流传久了，含义就……了”的语境相合。", "保持": "语义：“保持”指维持原样，与“流传久了，含义就……了”的渐变语境相反。", "咀嚼": "搭配：“咀嚼”的对象是食物，不能用来说含义。", "哭泣": "语义：“哭泣”指流泪，含义不会哭泣，与语境不合。"}, "sentence_index": 6, "correct_answer": "异化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器经过异化又能运转了。", "explanation": "这里应该用〈修复〉。“异化”指变得与原来不同，表示让坏掉的机器恢复运转要用“修复”。"}, {"text": "这座山几千年来始终异化，还是老样子。", "explanation": "这里应该用〈不变〉。“异化”指变得与原来不同，“还是老样子”说明没有变化，要用“始终不变”。"}, {"text": "这间屋子装修后仍然异化着以前的样子。", "explanation": "这里应该用〈保持〉。“异化”指变得与原来不同，仍是以前的样子说明没有变，要说“保持着”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首民歌在流传中异化面目全非。", "corrected_sentence": "这首民歌在流传中异化得面目全非。", "error_description": "动词“异化”后面接表示结果的补语时要用“得”引出，应写作“异化得面目全非”；漏掉“得”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家小店在快速发展中慢慢异化了景点。", "corrected_sentence": "这家小店在快速发展中慢慢异化成了景点。", "error_description": "“异化”表示变成另一种样子时，后面要用“成”引出结果，应写作“异化成了景点”；“异化了景点”是误用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
