INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26308, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "负荷就是一个人或一台机器要承受的重量或工作量。", "primary_collocate": null, "pronunciation": "fù hè", "ipa": "fu˥˩ xɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这台洗衣机的负荷是十公斤。", "target_word": "负荷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "货车装得太满，超过了它能承受的负荷。", "target_word": "负荷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天搬砖，身体的负荷很重。", "target_word": "负荷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电脑同时开太多软件，负荷就会变大。", "target_word": "负荷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座桥的负荷有限，大卡车不能过。", "target_word": "负荷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小马驮着这么重的负荷，走得很慢。", "target_word": "负荷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调的负荷太大，电表转得很快。", "target_word": "负荷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生让她减轻工作负荷，多休息。", "target_word": "负荷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生背着重书包，肩膀上的负荷不小。", "target_word": "负荷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电梯的最大负荷是八百公斤。", "target_word": "负荷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "負荷", "label": "繁体"}, {"form": "超负荷", "label": "复合"}, {"form": "负荷量", "label": "复合"}], "register": "书面", "sense_fingerprint": "人或机器要承受的重量或工作量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64941688-4f27-4463-91b9-e734e0578460') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26308, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "负荷", "is_correct": true, "explanation": "正确答案。负荷指机器或人所承受的重量或工作量。"}, {"text": "复刻", "is_correct": false, "explanation": "fù kè（第四声）与 fù hè 声母不同（k 与 h），意思是按原样重新制作。"}, {"text": "复课", "is_correct": false, "explanation": "fù kè 与 fù hè 声母不同（k 与 h），意思是恢复上课，与负荷不同。"}, {"text": "复测", "is_correct": false, "explanation": "fù cè 与 fù hè 声母不同（c 与 h），意思是重新测量。"}, {"text": "复合", "is_correct": false, "explanation": "fù hé（第二声）与 fù hè（第四声）末字声调不同，意思是由几部分组合而成。"}], "explanations": {"负荷": "正确答案。负荷指机器或人所承受的重量或工作量。", "复刻": "fù kè（第四声）与 fù hè 声母不同（k 与 h），意思是按原样重新制作。", "复课": "fù kè 与 fù hè 声母不同（k 与 h），意思是恢复上课，与负荷不同。", "复测": "fù cè 与 fù hè 声母不同（c 与 h），意思是重新测量。", "复合": "fù hé（第二声）与 fù hè（第四声）末字声调不同，意思是由几部分组合而成。"}, "sentence_index": null, "correct_answer": "负荷"}, "level_3": {"options": [{"text": "负荷", "is_correct": true, "explanation": "正确。“洗衣机的负荷”指洗衣机能承受的衣物重量，与“十公斤”搭配相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指存在的年数，与“十公斤”无法搭配，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”以货币单位计量，不用公斤计，不能和“十公斤”搭配。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能用重量单位计量，“颜色是十公斤”句意不通。"}], "explanations": {"负荷": "正确。“洗衣机的负荷”指洗衣机能承受的衣物重量，与“十公斤”搭配相合。", "年龄": "语义：“年龄”指存在的年数，与“十公斤”无法搭配，句意不通。", "价格": "搭配：“价格”以货币单位计量，不用公斤计，不能和“十公斤”搭配。", "颜色": "语义：“颜色”不能用重量单位计量，“颜色是十公斤”句意不通。"}, "sentence_index": 0, "correct_answer": "负荷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这笔学费全部由他的父母负荷。", "explanation": "这里应该用〈负担〉。负荷多指机器、结构或身体承受的重量和工作量，学费等经济开支要说负担。"}, {"text": "他对这次事故负有重要负荷。", "explanation": "这里应该用〈责任〉。“负有”后接的是责任，负荷不能表示应负的责任。"}, {"text": "孩子的负荷一年涨了八公斤。", "explanation": "这里应该用〈体重〉。负荷指所承受的重量或工作量，说孩子的身体变重要用体重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26308, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "负荷", "is_correct": true, "explanation": "正确答案。负荷指机器或人所承受的重量或工作量。"}, {"text": "符合", "is_correct": false, "explanation": "fú hé 与 fù hè 两个音节的声调都不同，意思是相符、吻合。"}, {"text": "复核", "is_correct": false, "explanation": "fù hé 与 fù hè 末字声调不同（第二声与第四声），意思是再次核对。"}, {"text": "富含", "is_correct": false, "explanation": "fù hán 与 fù hè 末字的韵母和声调都不同，意思是含有丰富的某种成分。"}], "explanations": {"负荷": "正确答案。负荷指机器或人所承受的重量或工作量。", "符合": "fú hé 与 fù hè 两个音节的声调都不同，意思是相符、吻合。", "复核": "fù hé 与 fù hè 末字声调不同（第二声与第四声），意思是再次核对。", "富含": "fù hán 与 fù hè 末字的韵母和声调都不同，意思是含有丰富的某种成分。"}, "sentence_index": null, "correct_answer": "负荷"}, "level_3": {"options": [{"text": "负荷", "is_correct": true, "explanation": "正确。“空调的负荷”指空调运行时承受的工作量与耗电量，与“太大”及“电表转得很快”相合。"}, {"text": "学历", "is_correct": false, "explanation": "语义：“学历”是人受教育的程度，不能用于空调，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的身体特征，不用来描述空调。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人的性情，空调没有性格，句意不通。"}], "explanations": {"负荷": "正确。“空调的负荷”指空调运行时承受的工作量与耗电量，与“太大”及“电表转得很快”相合。", "学历": "语义：“学历”是人受教育的程度，不能用于空调，句意不通。", "身高": "体貌：“身高”是人的身体特征，不用来描述空调。", "性格": "语义：“性格”指人的性情，空调没有性格，句意不通。"}, "sentence_index": 6, "correct_answer": "负荷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这面墙的负荷是浅蓝色的。", "explanation": "这里应该用〈颜色〉。负荷指所承受的重量或工作量，墙面的颜色要说颜色。"}, {"text": "上学的负荷要花一个小时。", "explanation": "这里应该用〈时间〉。负荷指所承受的重量或工作量，花费的时长要说时间。"}, {"text": "这座山的负荷朝北，坡很陡。", "explanation": "这里应该用〈方向〉。负荷指所承受的重量或工作量，山朝哪边要说方向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台起重机超过了额定地负荷，就会自动停机。", "corrected_sentence": "这台起重机超过了额定负荷，就会自动停机。", "error_description": "错误：“额定地负荷”；正确：“额定负荷”。“额定”是修饰“负荷”的定语，二者直接相连，中间不加“地”（“地”用于动词前作状语）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "空调开久了，负荷太多，电表转得很快。", "corrected_sentence": "空调开久了，负荷太大，电表转得很快。", "error_description": "错误：“负荷太多”；正确：“负荷太大”。“负荷”用“大、小、重”来形容，不用“多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
