INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26310, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一层又一层，很多层叠在一起。", "primary_collocate": null, "pronunciation": "céng céng", "ipa": "tsʰɤŋ˧˥ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "她把礼物用纸层层包着。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "层层树叶挡住了阳光。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶上飘着层层白云。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡上是层层梯田。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿着层层厚衣服，还是觉得冷。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "层层海浪拍向岸边。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把饼干用纸层层包好。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口围着层层人群。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨点落在层层屋顶上。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剥开洋葱，里面是层层薄皮。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "层", "label": "单字"}, {"form": "層層", "label": "繁体"}, {"form": "层层叠叠", "label": "复合"}], "register": "中性", "sense_fingerprint": "实物一层叠一层，如层层包装、层层梯田、层层海浪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64941688-4f27-4463-91b9-e734e0578460') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰冷", "is_correct": false, "explanation": "语义：“冰冷”描写温度或态度，不能说明把礼物用纸包着的方式。"}, {"text": "层层", "is_correct": true, "explanation": "正确：“层层包着”描述纸一层一层地裹在礼物上，只有“层层”符合。"}, {"text": "高高", "is_correct": false, "explanation": "语义：“高高”指位置很高，不能描述把礼物用纸包着的方式。"}, {"text": "空空", "is_correct": false, "explanation": "搭配：“空空”形容空的样子，不与“包着”搭配。"}], "explanations": {"冰冷": "语义：“冰冷”描写温度或态度，不能说明把礼物用纸包着的方式。", "层层": "正确：“层层包着”描述纸一层一层地裹在礼物上，只有“层层”符合。", "高高": "语义：“高高”指位置很高，不能描述把礼物用纸包着的方式。", "空空": "搭配：“空空”形容空的样子，不与“包着”搭配。"}, "sentence_index": 0, "correct_answer": "层层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "操场上铺着层层跑道。", "explanation": "这里应该用〈平铺〉。层层指一层叠一层的东西，跑道是平面，不能用“层层”。"}, {"text": "我们班有层层同学。", "explanation": "这里应该用〈很多〉。层层强调一层层叠在一起，描述同学人数多时不自然，应说“很多同学”。"}, {"text": "他把玩具层层扔掉了。", "explanation": "这里应该用〈一个一个〉。层层指层叠的样子，不用于一件件扔掉的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滚烫", "is_correct": false, "explanation": "语义：“滚烫”描写温度，饼干不会因此被用纸包好，句意不通。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能修饰“包好”的方式。"}, {"text": "层层", "is_correct": true, "explanation": "正确：“层层包好”描述纸一层一层地包裹饼干，只有“层层”符合。"}, {"text": "漆黑", "is_correct": false, "explanation": "语义：“漆黑”描写颜色，与“用纸包好”的动作不相关。"}], "explanations": {"滚烫": "语义：“滚烫”描写温度，饼干不会因此被用纸包好，句意不通。", "清脆": "搭配：“清脆”形容声音，不能修饰“包好”的方式。", "层层": "正确：“层层包好”描述纸一层一层地包裹饼干，只有“层层”符合。", "漆黑": "语义：“漆黑”描写颜色，与“用纸包好”的动作不相关。"}, "sentence_index": 6, "correct_answer": "层层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他层层吃了三个包子。", "explanation": "这里应该用〈接连〉。层层描述层叠的形态，不能用来修饰连续吃的动作。"}, {"text": "这块蛋糕有层层甜味。", "explanation": "这里应该用〈浓浓〉。层层描述层叠的形态，不能修饰“甜味”这种味道。"}, {"text": "他层层地笑了起来。", "explanation": "这里应该用〈哈哈〉。“层层”不能描述笑的声音或状态，应说“哈哈地笑了起来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷把红薯用布层裹好。", "corrected_sentence": "爷爷把红薯用布层层裹好。", "error_description": "“层层”是重叠形式，在动词前表示一层一层地，不能只用单个“层”，应说“层层裹好”，不能说“层裹好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在山坡上看见层梯田。", "corrected_sentence": "我们在山坡上看见层层梯田。", "error_description": "作定语修饰名词时要说“层层梯田”，不能只用单个“层”直接修饰“梯田”，“层梯田”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26312, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26312, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26312, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不要自己喜欢的东西了，把它扔开。", "primary_collocate": null, "pronunciation": "qì", "ipa": "tɕʰi˥˩", "syllable_count": 1, "sentences": [{"text": "孩子长大后，对旧玩具弃如敝屣。", "target_word": "弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他曾经最爱这把吉他，如今却弃之不顾。", "target_word": "弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书我看了多年，实在不忍弃之。", "target_word": "弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她再喜欢这条裙子，也只好弃了，因为破得没法穿。", "target_word": "弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他弃了心爱的画笔，去工厂做工。", "target_word": "弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只布娃娃陪了她多年，她始终不愿弃之。", "target_word": "弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了搬家，他把许多心爱的旧物弃在了路边。", "target_word": "弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一气之下，把心爱的模型弃于河中。", "target_word": "弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件旧毛衣她爱了多年，弃之可惜。", "target_word": "弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "曾经爱不释手的游戏机，他现在弃而不用。", "target_word": "弃", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "棄", "label": "繁体"}, {"form": "舍弃", "label": "复合"}, {"form": "丢弃", "label": "复合"}, {"form": "抛弃", "label": "复合"}], "register": "书面", "sense_fingerprint": "舍弃自己喜欢的东西、把它扔开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 屣 (Zipf 1.6)']::text[], '64941688-4f27-4463-91b9-e734e0578460') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26312, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "弃", "is_correct": true, "explanation": "弃（qì，第四声）：舍弃自己喜欢的东西、把它扔开，是本词。"}, {"text": "欺", "is_correct": false, "explanation": "qī（第一声）与 qì（第四声）声调不同，意思是欺负。"}, {"text": "骑", "is_correct": false, "explanation": "qí（第二声）与 qì（第四声）声调不同，意思是骑乘。"}, {"text": "细", "is_correct": false, "explanation": "xì 与 qì 声母不同（x 与 q），意思是细小。"}, {"text": "寄", "is_correct": false, "explanation": "jì 与 qì 声母不同（j 与 q），意思是寄送。"}, {"text": "乞", "is_correct": false, "explanation": "qǐ（第三声）与 qì（第四声）声调不同，意思是乞求。"}], "explanations": {"弃": "弃（qì，第四声）：舍弃自己喜欢的东西、把它扔开，是本词。", "欺": "qī（第一声）与 qì（第四声）声调不同，意思是欺负。", "骑": "qí（第二声）与 qì（第四声）声调不同，意思是骑乘。", "细": "xì 与 qì 声母不同（x 与 q），意思是细小。", "寄": "jì 与 qì 声母不同（j 与 q），意思是寄送。", "乞": "qǐ（第三声）与 qì（第四声）声调不同，意思是乞求。"}, "sentence_index": null, "correct_answer": "弃"}, "level_3": {"options": [{"text": "弃", "is_correct": true, "explanation": "弃：“弃如敝屣”指把东西看得像破鞋一样不值得要，是固定说法。"}, {"text": "珍", "is_correct": false, "explanation": "语义：“珍如敝屣”与“敝屣”的轻视之意相反。"}, {"text": "爱", "is_correct": false, "explanation": "语义：“爱如敝屣”与“敝屣”表示不值一顾的语义相矛盾。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿如敝屣”不符合“……如……”的评价结构，“穿”不能表示看待的态度。"}], "explanations": {"弃": "弃：“弃如敝屣”指把东西看得像破鞋一样不值得要，是固定说法。", "珍": "语义：“珍如敝屣”与“敝屣”的轻视之意相反。", "爱": "语义：“爱如敝屣”与“敝屣”表示不值一顾的语义相矛盾。", "穿": "搭配：“穿如敝屣”不符合“……如……”的评价结构，“穿”不能表示看待的态度。"}, "sentence_index": 0, "correct_answer": "弃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书我想弃给朋友看。", "explanation": "这里应该用〈送〉。“弃”表示舍去，不表示赠予他人，送人应说“送给”。"}, {"text": "这枚纪念币我弃了很多年，舍不得花。", "explanation": "这里应该用〈珍藏〉。“弃”表示舍去，不表示长期收存。"}, {"text": "每天下班后，他弃着孩子玩。", "explanation": "这里应该用〈陪〉。“弃”表示舍去，不表示陪伴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26312, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "弃", "is_correct": true, "explanation": "弃（qì，第四声）：舍弃、扔开的意思，是本词。"}, {"text": "七", "is_correct": false, "explanation": "qī（第一声）与 qì（第四声）声调不同，意思是数字“七”。"}, {"text": "其", "is_correct": false, "explanation": "qí（第二声）与 qì（第四声）声调不同，意思是“其他”。"}, {"text": "系", "is_correct": false, "explanation": "xì 与 qì 声母不同（x 与 q），意思是联系。"}, {"text": "记", "is_correct": false, "explanation": "jì 与 qì 声母不同（j 与 q），意思是记住。"}, {"text": "齐", "is_correct": false, "explanation": "qí（第二声）与 qì（第四声）声调不同，意思是整齐。"}], "explanations": {"弃": "弃（qì，第四声）：舍弃、扔开的意思，是本词。", "七": "qī（第一声）与 qì（第四声）声调不同，意思是数字“七”。", "其": "qí（第二声）与 qì（第四声）声调不同，意思是“其他”。", "系": "xì 与 qì 声母不同（x 与 q），意思是联系。", "记": "jì 与 qì 声母不同（j 与 q），意思是记住。", "齐": "qí（第二声）与 qì（第四声）声调不同，意思是整齐。"}, "sentence_index": null, "correct_answer": "弃"}, "level_3": {"options": [{"text": "弃", "is_correct": true, "explanation": "弃：“把……弃在了路边”表示舍去旧物，符合搬家时丢掉东西的语境。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”须带受赠者，不能只说“送在路边”。"}, {"text": "捐", "is_correct": false, "explanation": "搭配：“捐”须接捐赠对象，“捐在路边”不成立。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”需接擦拭的对象，“擦在路边”不成立。"}], "explanations": {"弃": "弃：“把……弃在了路边”表示舍去旧物，符合搬家时丢掉东西的语境。", "送": "配价：“送”须带受赠者，不能只说“送在路边”。", "捐": "搭配：“捐”须接捐赠对象，“捐在路边”不成立。", "擦": "搭配：“擦”需接擦拭的对象，“擦在路边”不成立。"}, "sentence_index": 6, "correct_answer": "弃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直弃着这只受伤的小狗，从不离开。", "explanation": "这里应该用〈护〉。弃表示舍去、扔开，与守护、照料的意思相反，且与“从不离开”矛盾。"}, {"text": "他把那件心爱的玩具紧紧弃在手里，舍不得放手。", "explanation": "这里应该用〈攥〉。弃表示舍去、扔开，与紧紧握住的意思相反，也与“舍不得放手”矛盾。"}, {"text": "他把画弃在墙上，很漂亮。", "explanation": "这里应该用〈挂〉。“弃”表示舍去，不表示悬挂，应说“挂在墙上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把旧木椅虽然破了，弃可惜。", "corrected_sentence": "这把旧木椅虽然破了，弃之可惜。", "error_description": "“弃可惜”缺少代词“之”。“弃之可惜”是固定格式，“之”指代前文的椅子，不能省略，应说“弃之可惜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那只旧玩偶弃了在路边。", "corrected_sentence": "他把那只旧玩偶弃在了路边。", "error_description": "“弃在路边”中“在路边”是补语，“了”应放在“弃在”之后，说“弃在了路边”，不能说“弃了在路边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
