INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26314, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把衣服穿在身上", "primary_collocate": null, "pronunciation": "chuān zhe", "ipa": "tʂʰwan˥ tʂə", "syllable_count": 2, "sentences": [{"text": "他穿着一件红色的外衣。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明穿着新鞋子去上学。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿着白裙子，站在门口等我。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面很冷，他却只穿着短袖。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子穿着睡衣在客厅看电视。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人穿着厚大衣，慢慢走在路上。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位警察穿着黑色的制服。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都穿着校服参加比赛。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿着拖鞋就跑出去了。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新娘穿着漂亮的婚纱走进教堂。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "穿了", "label": "体标"}, {"form": "穿过", "label": "体标"}], "register": "中性", "sense_fingerprint": "穿着：衣服正穿在身上的状态，动词“穿”加持续体标“着”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a346198f-e365-43d8-90e1-ea9dbd7f312a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26314, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穿着", "is_correct": true, "explanation": "“穿着”表示衣服正穿在身上，“他穿着一件红色的外衣”语义通顺。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能用于外衣，“吃一件外衣”不成立。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出声音，与“外衣”无关，句子不成立。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”不能用于外衣，搭配不当。"}], "explanations": {"穿着": "“穿着”表示衣服正穿在身上，“他穿着一件红色的外衣”语义通顺。", "吃": "搭配：“吃”不能用于外衣，“吃一件外衣”不成立。", "唱": "语义：“唱”指发出声音，与“外衣”无关，句子不成立。", "写": "搭配：“写”不能用于外衣，搭配不当。"}, "sentence_index": 0, "correct_answer": "穿着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他穿着一顶帽子出门。", "explanation": "这里应该用〈戴〉。帽子、眼镜等要用“戴”，不用“穿”。"}, {"text": "她穿着一个书包上学。", "explanation": "这里应该用〈背〉。书包要用“背”，不能用“穿”。"}, {"text": "他穿着一把伞出门。", "explanation": "这里应该用〈带〉。伞要用“带”，不能用“穿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿着", "is_correct": true, "explanation": "“穿着”表示衣服穿在身上，“那位警察穿着黑色的制服”语义通顺。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能用于制服，搭配不当。"}, {"text": "读", "is_correct": false, "explanation": "语义：“读”指看文字，与“制服”无关，句子不成立。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”不能用于衣服，“煮黑色的制服”不成立。"}], "explanations": {"穿着": "“穿着”表示衣服穿在身上，“那位警察穿着黑色的制服”语义通顺。", "喝": "搭配：“喝”不能用于制服，搭配不当。", "读": "语义：“读”指看文字，与“制服”无关，句子不成立。", "煮": "搭配：“煮”不能用于衣服，“煮黑色的制服”不成立。"}, "sentence_index": 6, "correct_answer": "穿着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈穿着一个孩子走进屋。", "explanation": "这里应该用〈抱〉。抱在怀里的人要用“抱”，不能用“穿”。"}, {"text": "她穿着一个箱子去车站。", "explanation": "这里应该用〈提〉。拎在手里的箱子要用“提”，不能用“穿”。"}, {"text": "他穿着一支笔在写字。", "explanation": "这里应该用〈拿〉。手里拿的东西要用“拿”，不能用“穿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
