INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26316, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "义务就是你应该做的事情，比如帮助别人。", "primary_collocate": null, "pronunciation": "yì wù", "ipa": "i˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "照顾老人是子女的义务。", "target_word": "义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公民有遵守法律的义务。", "target_word": "义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都有保护环境的义务。", "target_word": "义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得帮助同学是自己的义务。", "target_word": "义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母有照顾孩子的义务。", "target_word": "义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交税是每个公民的义务。", "target_word": "义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生有义务告诉病人真实情况。", "target_word": "义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不但有权利，也有义务。", "target_word": "义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不是你的义务，你可以不做。", "target_word": "义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生有义务遵守学校的规定。", "target_word": "义务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "义务教育", "label": "复合词"}, {"form": "義務", "label": "繁体"}], "register": "中性", "sense_fingerprint": "应当承担、应该做的责任", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87aa3fbb-5473-40d6-85f3-a36aa4409ac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26316, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "义务", "is_correct": true, "explanation": "义务 yìwù，指应当承担的责任，即正确答案。"}, {"text": "雨雾", "is_correct": false, "explanation": "雨雾 yǔwù 与 yìwù 韵母、声调不同，意思是雨和雾。"}, {"text": "遗物", "is_correct": false, "explanation": "遗物 yíwù 与 yìwù 声调不同（第二声与第四声），意思是死者留下的东西。"}, {"text": "衣物", "is_correct": false, "explanation": "衣物 yīwù 第一个音节为第一声，与 yìwù 声调不同，意思是衣服和日常用品。"}], "explanations": {"义务": "义务 yìwù，指应当承担的责任，即正确答案。", "雨雾": "雨雾 yǔwù 与 yìwù 韵母、声调不同，意思是雨和雾。", "遗物": "遗物 yíwù 与 yìwù 声调不同（第二声与第四声），意思是死者留下的东西。", "衣物": "衣物 yīwù 第一个音节为第一声，与 yìwù 声调不同，意思是衣服和日常用品。"}, "sentence_index": null, "correct_answer": "义务"}, "level_3": {"options": [{"text": "义务", "is_correct": true, "explanation": "义务指应当履行的责任，「照顾老人是子女的义务」意思通顺，正确。"}, {"text": "商品", "is_correct": false, "explanation": "语义：「商品」指可买卖的货物，照顾老人不是商品，「是……的商品」说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：「是……的脾气」不能用来指一件应做的事，「照顾老人」与「脾气」不搭配。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」指色彩，照顾老人不能是颜色，句意说不通。"}], "explanations": {"义务": "义务指应当履行的责任，「照顾老人是子女的义务」意思通顺，正确。", "商品": "语义：「商品」指可买卖的货物，照顾老人不是商品，「是……的商品」说不通。", "脾气": "搭配：「是……的脾气」不能用来指一件应做的事，「照顾老人」与「脾气」不搭配。", "颜色": "语义：「颜色」指色彩，照顾老人不能是颜色，句意说不通。"}, "sentence_index": 0, "correct_answer": "义务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这起事故的义务在他。", "explanation": "这里应该用〈责任〉。「义务」指应当履行的事，事故的过失或担责要说「责任」。"}, {"text": "妈妈给孩子买了义务。", "explanation": "这里应该用〈玩具〉。「义务」指应当做的事，不是可以购买的东西，此处用错了词义。"}, {"text": "他很喜欢义务。", "explanation": "这里应该用〈音乐〉。「义务」指应当做的事，不能用来表示喜爱的对象，此处用错了词义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26316, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "义务", "is_correct": true, "explanation": "义务指应当履行的责任，「医生有义务告诉病人真实情况」意思通顺，正确。"}, {"text": "河流", "is_correct": false, "explanation": "语义：「河流」不能告诉病人情况，「医生有河流告诉病人」说不通。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：「体重」描写身体特征，医生不能用它告诉病人真实情况。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，不能用来告诉病人真实情况，句意不通。"}], "explanations": {"义务": "义务指应当履行的责任，「医生有义务告诉病人真实情况」意思通顺，正确。", "河流": "语义：「河流」不能告诉病人情况，「医生有河流告诉病人」说不通。", "体重": "体貌：「体重」描写身体特征，医生不能用它告诉病人真实情况。", "厨房": "语义：厨房是房间，不能用来告诉病人真实情况，句意不通。"}, "sentence_index": 6, "correct_answer": "义务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的义务很好吃。", "explanation": "这里应该用〈菜〉。「义务」指应当做的事，不是食物，不能用来形容味道，此处用错了词义。"}, {"text": "妈妈的义务很好听。", "explanation": "这里应该用〈声音〉。「义务」指应尽的责任，不能用来形容声音好听，此处用错了词义。"}, {"text": "这篇文章的义务很有趣。", "explanation": "这里应该用〈内容〉。「义务」指应尽的责任，不能用来形容文章有趣，此处用错了词义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26316, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "保护环境是每个人的一只义务。", "corrected_sentence": "保护环境是每个人的一项义务。", "error_description": "错误：「一只义务」。正确：「一项义务」。「只」用于动物，「义务」要用量词「项」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26316, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父母有管教孩子义务。", "corrected_sentence": "父母有管教孩子的义务。", "error_description": "错误：「孩子义务」漏了「的」。正确：「管教孩子的义务」。动词短语修饰名词时要加「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26318, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ae974a3-c60f-47e3-a2f9-5004efbf8909') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
