INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26320, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很远的那一头。", "primary_collocate": null, "pronunciation": "yuǎn duān", "ipa": "ɥɛn˨˩˦ twan˥", "syllable_count": 2, "sentences": [{"text": "公园的远端有一座小山。", "target_word": "远端", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们沿着长长的河，走向河的远端。", "target_word": "远端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长桌的远端坐着一位陌生的客人。", "target_word": "远端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在房间的远端，有人正在弹钢琴。", "target_word": "远端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "停车场的远端还有几个空位。", "target_word": "远端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把杯子推到了桌子的远端。", "target_word": "远端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "操场的远端种着一排高高的树。", "target_word": "远端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙发的远端放着一个小枕头。", "target_word": "远端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑道的远端有人举着红旗等我们。", "target_word": "远端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从走廊的远端传来了一阵笑声。", "target_word": "远端", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "遠端", "label": "繁体"}], "register": "书面", "sense_fingerprint": "远端：名词，很远的那一头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0102e0d2-b138-4a6a-b645-d2d4ac74cec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26320, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "门票", "is_correct": false, "explanation": "语义：门票是一张票，不是地方，公园的门票上不可能有一座小山。"}, {"text": "远端", "is_correct": true, "explanation": "远端：很远的那一头，此处指公园里离入口最远的一端，可以有一座小山。"}, {"text": "售票处", "is_correct": false, "explanation": "语义：售票处是一间小屋，容不下一座小山，句子说的是公园的大片地方。"}, {"text": "票价", "is_correct": false, "explanation": "搭配：“票价”是钱数，“有一座小山”要求前面是地点，票价不能与之搭配。"}], "explanations": {"门票": "语义：门票是一张票，不是地方，公园的门票上不可能有一座小山。", "远端": "远端：很远的那一头，此处指公园里离入口最远的一端，可以有一座小山。", "售票处": "语义：售票处是一间小屋，容不下一座小山，句子说的是公园的大片地方。", "票价": "搭配：“票价”是钱数，“有一座小山”要求前面是地点，票价不能与之搭配。"}, "sentence_index": 0, "correct_answer": "远端"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我听到远端传来一阵鼓声。", "explanation": "这里应该用〈远处〉。远端指某样东西的远的那一头，句中没有说明是哪样东西的远端；泛指远方传来的声音要用远处。"}, {"text": "我有一个远端亲戚住在北方。", "explanation": "这里应该用〈远亲〉。远端只用于空间，指某物的远的那一头，不用来形容人与人的亲疏关系。"}, {"text": "我们对未来的远端很有信心。", "explanation": "这里应该用〈远景〉。远端只指空间上某物的远的那一头，不能指未来的前景或时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ae974a3-c60f-47e3-a2f9-5004efbf8909') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26320, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讲台", "is_correct": false, "explanation": "语义：讲台是教室里供老师讲课用的台子，操场上不会在讲台旁种树。"}, {"text": "远端", "is_correct": true, "explanation": "远端：很远的那一头，此处指操场最远的一端，可以种一排树。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板挂在墙上，不是能种树的地方，句中的“种着”说明是一片土地。"}, {"text": "课桌", "is_correct": false, "explanation": "搭配：“种”要求的处所是土地或花盆，课桌不能被“种着一排树”。"}], "explanations": {"讲台": "语义：讲台是教室里供老师讲课用的台子，操场上不会在讲台旁种树。", "远端": "远端：很远的那一头，此处指操场最远的一端，可以种一排树。", "黑板": "语义：黑板挂在墙上，不是能种树的地方，句中的“种着”说明是一片土地。", "课桌": "搭配：“种”要求的处所是土地或花盆，课桌不能被“种着一排树”。"}, "sentence_index": 6, "correct_answer": "远端"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直想去远端旅行。", "explanation": "这里应该用〈远方〉。远端必须指某样东西的远的那一头，泛指遥远的地方要说远方。"}, {"text": "我们制定了远端目标。", "explanation": "这里应该用〈远期〉。远期指时间上较久远的将来，远端只指空间上某物的远的那一头，不能用于时间或计划。"}, {"text": "远端的人类已经会用火了。", "explanation": "这里应该用〈远古〉。远古指很久以前的时代，远端只指空间上的远的那一头，不能指时间上的久远。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ae974a3-c60f-47e3-a2f9-5004efbf8909') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把球踢到了操场的远端的。", "corrected_sentence": "他把球踢到了操场的远端。", "error_description": "句末多了“的”：“远端”后面不需要“的”，应说“踢到了操场的远端”，不说“远端的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ae974a3-c60f-47e3-a2f9-5004efbf8909') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书架的远端的摆着几本旧书。", "corrected_sentence": "书架的远端摆着几本旧书。", "error_description": "错误形式为“远端的摆着”，正确形式为“远端摆着”。“远端”后面不应再加“的”，多出的“的”使“远端的摆着”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ae974a3-c60f-47e3-a2f9-5004efbf8909') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
