INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26322, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西上不好的地方。", "primary_collocate": null, "pronunciation": "quē xiàn", "ipa": "tɕʰɥe˥ ɕi̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这个杯子有一处小缺陷。", "target_word": "缺陷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在检查布料有没有缺陷。", "target_word": "缺陷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块玉很漂亮，只有一点小缺陷。", "target_word": "缺陷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机屏幕上的缺陷影响使用。", "target_word": "缺陷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "质检员发现桌子有明显的缺陷。", "target_word": "缺陷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为有缺陷，这批瓷器卖得便宜。", "target_word": "缺陷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的刹车有缺陷，必须修理。", "target_word": "缺陷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买衣服时，我会先看有没有缺陷。", "target_word": "缺陷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的缺陷用白漆盖住了。", "target_word": "缺陷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的缺陷是声音太大。", "target_word": "缺陷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一处缺陷", "label": "量词"}, {"form": "质量缺陷", "label": "复合"}, {"form": "小缺陷", "label": "复合"}], "register": "中性", "sense_fingerprint": "具体物品上的瑕疵、毛病、不好的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64941688-4f27-4463-91b9-e734e0578460') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26322, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "缺陷", "is_correct": true, "explanation": "正确答案：缺陷（quē xiàn），指东西上不好的地方。"}, {"text": "切线", "is_correct": false, "explanation": "qiē（第一声）与 quē（第一声）的介音不同（i 与 u），意思是几何学中的切线。"}, {"text": "区县", "is_correct": false, "explanation": "qū（第一声）与 quē（第一声）的韵母不同，意思是行政区划中的区和县。"}, {"text": "曲线", "is_correct": false, "explanation": "qū（第一声）与 quē（第一声）仅韵母不同（ū 与 üē），意思是弯曲的线。"}], "explanations": {"缺陷": "正确答案：缺陷（quē xiàn），指东西上不好的地方。", "切线": "qiē（第一声）与 quē（第一声）的介音不同（i 与 u），意思是几何学中的切线。", "区县": "qū（第一声）与 quē（第一声）的韵母不同，意思是行政区划中的区和县。", "曲线": "qū（第一声）与 quē（第一声）仅韵母不同（ū 与 üē），意思是弯曲的线。"}, "sentence_index": null, "correct_answer": "缺陷"}, "level_3": {"options": [{"text": "容量", "is_correct": false, "explanation": "语义：杯子的容量是正常属性，不是需要“一处小”指出的不足。"}, {"text": "缺陷", "is_correct": true, "explanation": "正确：“一处小”指出杯子上的不完美之处，只有“缺陷”符合。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“处”一般指具体的位置或部分，不说“一处小重量”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是杯子实物上的毛病，与“一处小”的描述不符。"}], "explanations": {"容量": "语义：杯子的容量是正常属性，不是需要“一处小”指出的不足。", "缺陷": "正确：“一处小”指出杯子上的不完美之处，只有“缺陷”符合。", "重量": "搭配：“处”一般指具体的位置或部分，不说“一处小重量”。", "价格": "语义：价格不是杯子实物上的毛病，与“一处小”的描述不符。"}, "sentence_index": 0, "correct_answer": "缺陷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块玉上有一把小缺陷，所以便宜。", "explanation": "这里应该用〈处〉。缺陷不用“把”，“把”多用于有柄或能握住的东西。"}, {"text": "这个杯子的缺陷是很结实，所以很贵。", "explanation": "这里应该用〈优点〉。缺陷指不好的地方，“很结实”是正面的，应说“优点”。"}, {"text": "我因为一时缺陷，把杯子摔坏了。", "explanation": "这里应该用〈疏忽〉。缺陷指东西本身不好的地方，不能用来指一时的疏忽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26322, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "缺陷", "is_correct": true, "explanation": "正确答案：缺陷（quē xiàn），指东西上不好的地方。"}, {"text": "曲线", "is_correct": false, "explanation": "qū（第一声）与 quē（第一声）仅韵母不同（ū 与 üē），意思是弯曲的线。"}, {"text": "缺项", "is_correct": false, "explanation": "xiàng 与 xiàn 的韵母不同（ang 与 an），意思是缺少的项目。"}, {"text": "缺件", "is_correct": false, "explanation": "jiàn 与 xiàn 的声母不同（j 与 x），意思是缺少的零件。"}], "explanations": {"缺陷": "正确答案：缺陷（quē xiàn），指东西上不好的地方。", "曲线": "qū（第一声）与 quē（第一声）仅韵母不同（ū 与 üē），意思是弯曲的线。", "缺项": "xiàng 与 xiàn 的韵母不同（ang 与 an），意思是缺少的项目。", "缺件": "jiàn 与 xiàn 的声母不同（j 与 x），意思是缺少的零件。"}, "sentence_index": null, "correct_answer": "缺陷"}, "level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：颜色本身不需要“必须修理”，与刹车的修理要求不符。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“刹车”一般不说“有速度”，此处不能作刹车的属性。"}, {"text": "缺陷", "is_correct": true, "explanation": "正确：“有……必须修理”指刹车存在不足，只有“缺陷”符合。"}, {"text": "价钱", "is_correct": false, "explanation": "语义：价钱不属于刹车的故障，不能说“价钱必须修理”。"}], "explanations": {"颜色": "语义：颜色本身不需要“必须修理”，与刹车的修理要求不符。", "速度": "搭配：“刹车”一般不说“有速度”，此处不能作刹车的属性。", "缺陷": "正确：“有……必须修理”指刹车存在不足，只有“缺陷”符合。", "价钱": "语义：价钱不属于刹车的故障，不能说“价钱必须修理”。"}, "sentence_index": 6, "correct_answer": "缺陷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器有一张很大的缺陷，声音很吵。", "explanation": "这里应该用〈个〉。缺陷不用“张”，“张”多用于平面的东西。"}, {"text": "这台机器的缺陷很好用，大家都喜欢它。", "explanation": "这里应该用〈长处〉。缺陷指不好的地方，“很好用”是好处，应说“长处”。"}, {"text": "我们把这台机器的缺陷喂饱了。", "explanation": "这里应该用〈修好〉。缺陷不能被“喂饱”，应该修好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张桌子的表面有一明显的缺陷。", "corrected_sentence": "这张桌子的表面有一处明显的缺陷。", "error_description": "数词“一”后须接量词，“一明显的缺陷”缺少量词，应为“一处明显的缺陷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件衣服上有一只小缺陷。", "corrected_sentence": "这件衣服上有一处小缺陷。", "error_description": "“缺陷”不用量词“只”，“只”多用于动物或成对东西中的一个；应说“一处小缺陷”或“一个小缺陷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
