INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26324, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "卖东西给别人的人或公司。", "primary_collocate": null, "pronunciation": "gōng yìng shāng", "ipa": "kʊŋ˥ iŋ˥˩ ʂɑŋ˥", "syllable_count": 3, "sentences": [{"text": "这家店的水果供应商是一位老农民。", "target_word": "供应商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的供应商明天会送菜过来。", "target_word": "供应商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王是这家超市的牛奶供应商。", "target_word": "供应商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板正在找新的大米供应商。", "target_word": "供应商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家供应商的东西便宜，也很新鲜。", "target_word": "供应商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡店从一家小供应商那里买豆子。", "target_word": "供应商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "供应商昨天把面包送到了店里。", "target_word": "供应商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位供应商每天早上六点送牛奶。", "target_word": "供应商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家供应商的价格比别人低一点。", "target_word": "供应商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭店换了供应商，菜变得更新鲜了。", "target_word": "供应商", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "供應商", "label": "繁体"}], "register": "通用", "sense_fingerprint": "卖东西给别人的人或公司", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0102e0d2-b138-4a6a-b645-d2d4ac74cec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26324, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "搭配：“是一位老农民”要求主语是人，“价格”不能作为人的身份主语。"}, {"text": "供应商", "is_correct": true, "explanation": "供应商：卖东西给别人的人或公司，此处指这家店的水果供货者，是一位老农民。"}, {"text": "包装", "is_correct": false, "explanation": "语义：包装是盒子或袋子，不是人，不能是一位老农民。"}, {"text": "冷柜", "is_correct": false, "explanation": "语义：冷柜是存放食物的设备，不是人，也不能是一位老农民。"}], "explanations": {"价格": "搭配：“是一位老农民”要求主语是人，“价格”不能作为人的身份主语。", "供应商": "供应商：卖东西给别人的人或公司，此处指这家店的水果供货者，是一位老农民。", "包装": "语义：包装是盒子或袋子，不是人，不能是一位老农民。", "冷柜": "语义：冷柜是存放食物的设备，不是人，也不能是一位老农民。"}, "sentence_index": 0, "correct_answer": "供应商"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的供应商每天都摆在货架上卖。", "explanation": "这里应该用〈商品〉。供应商指卖东西的人或公司，不是摆在货架上卖的东西；货架上陈列的是商品。"}, {"text": "周末我们常去供应商逛街。", "explanation": "这里应该用〈商场〉。供应商指卖东西的人或公司，不是可以去逛的地方；逛街要去商场。"}, {"text": "我们店里有一台供应商，每天都来送货。", "explanation": "这里应该用〈家〉。供应商指人或公司，量词用家；台是用于机器的量词，不能数供应商。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ae974a3-c60f-47e3-a2f9-5004efbf8909') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26324, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "菜单", "is_correct": false, "explanation": "语义：菜单是写着菜名的纸，不是人或公司，不能把面包送到店里。"}, {"text": "供应商", "is_correct": true, "explanation": "供应商：卖东西给别人的人或公司，此处指把面包送到店里的一方。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是坐车的人，不会把面包送到店里。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“送到了店里”的主语须是人或运输方，冰箱不能主动送货。"}], "explanations": {"菜单": "语义：菜单是写着菜名的纸，不是人或公司，不能把面包送到店里。", "供应商": "供应商：卖东西给别人的人或公司，此处指把面包送到店里的一方。", "乘客": "语义：乘客是坐车的人，不会把面包送到店里。", "冰箱": "搭配：“送到了店里”的主语须是人或运输方，冰箱不能主动送货。"}, "sentence_index": 6, "correct_answer": "供应商"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "供应商明天要参加高考。", "explanation": "这里应该用〈学生〉。供应商指卖东西的人或公司，明天参加高考的是学生。"}, {"text": "供应商每天早上都要打卡上班。", "explanation": "这里应该用〈员工〉。供应商是卖东西给别人的一方，每天打卡上班的是员工。"}, {"text": "我们店里来了一条供应商。", "explanation": "这里应该用〈家〉。供应商指人或公司，量词用家；条用于细长的东西，不能数供应商。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ae974a3-c60f-47e3-a2f9-5004efbf8909') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只供应商每天早上都送鸡蛋来。", "corrected_sentence": "这家供应商每天早上都送鸡蛋来。", "error_description": "错误形式为“这只供应商”，正确形式为“这家供应商”。“供应商”指人或公司，量词应用“家”；“只”用于动物等，这里量词错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ae974a3-c60f-47e3-a2f9-5004efbf8909') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "饭店刚换了一张新的供应商。", "corrected_sentence": "饭店刚换了一家新的供应商。", "error_description": "错误形式为“一张新的供应商”，正确形式为“一家新的供应商”。“供应商”指人或公司，量词应用“家”；“张”用于纸、桌子等平面的东西，这里量词错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ae974a3-c60f-47e3-a2f9-5004efbf8909') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
