INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26330, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "困局是很难摆脱的困难局面，就像被关在笼子里出不来。", "primary_collocate": null, "pronunciation": "kùn jú", "ipa": "kʰwən˥˩ tɕy˧˥", "syllable_count": 2, "sentences": [{"text": "球队连输五场，陷入了困局。", "target_word": "困局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生活陷入困局，不知怎么办。", "target_word": "困局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个困局让大家很着急。", "target_word": "困局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，只有耐心才能走出困局。", "target_word": "困局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们必须想办法摆脱眼前的困局。", "target_word": "困局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的困局是客人越来越少。", "target_word": "困局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪让整个城市陷入了困局。", "target_word": "困局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次遇到这样的困局。", "target_word": "困局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们帮爸爸解决了家里的困局。", "target_word": "困局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对工作上的困局，他去问了老师。", "target_word": "困局", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个困局", "label": "量词"}], "register": "书面", "sense_fingerprint": "很难摆脱的困难局面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '598c31df-7b1e-444b-ae49-80c36c027b68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26330, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "困局", "is_correct": true, "explanation": "“陷入困局”是常见搭配，指陷入难以摆脱的困难局面，符合句意。"}, {"text": "战绩", "is_correct": false, "explanation": "搭配：“陷入”后接处境、泥潭等，不能接“战绩”。"}, {"text": "天平", "is_correct": false, "explanation": "搭配：“陷入”不能接天平这类器物。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”是景观，球队连输不会陷入花园。"}], "explanations": {"困局": "“陷入困局”是常见搭配，指陷入难以摆脱的困难局面，符合句意。", "战绩": "搭配：“陷入”后接处境、泥潭等，不能接“战绩”。", "天平": "搭配：“陷入”不能接天平这类器物。", "花园": "语义：“花园”是景观，球队连输不会陷入花园。"}, "sentence_index": 0, "correct_answer": "困局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们研究出了一个困局。", "explanation": "这里应该用〈理论〉。“研究出”的对象是理论、方法等，“困局”是难以摆脱的处境，不能被研究出来。"}, {"text": "他们在比赛中踢了一个困局。", "explanation": "这里应该用〈球〉。“踢”的对象是球，“困局”是僵局，不能被踢。"}, {"text": "他的困局很好，大家都为他高兴。", "explanation": "这里应该用〈处境〉。“处境”可以好也可以坏，“困局”只指难以摆脱的困难局面，不能说很好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26330, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "困局", "is_correct": true, "explanation": "“陷入困局”指陷入难以摆脱的困难局面，与“大雪让整个城市”连用，句意通顺。"}, {"text": "节日", "is_correct": false, "explanation": "语义：“节日”是欢庆的日子，与大雪带来的困扰不符。"}, {"text": "歌谣", "is_correct": false, "explanation": "搭配：“陷入”后接处境，不能接“歌谣”这类作品。"}, {"text": "皮鞋", "is_correct": false, "explanation": "搭配：“陷入”后接处境，不能接“皮鞋”这类物品。"}], "explanations": {"困局": "“陷入困局”指陷入难以摆脱的困难局面，与“大雪让整个城市”连用，句意通顺。", "节日": "语义：“节日”是欢庆的日子，与大雪带来的困扰不符。", "歌谣": "搭配：“陷入”后接处境，不能接“歌谣”这类作品。", "皮鞋": "搭配：“陷入”后接处境，不能接“皮鞋”这类物品。"}, "sentence_index": 6, "correct_answer": "困局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于找到了困局。", "explanation": "这里应该用〈出路〉。“出路”指摆脱困境的办法，“困局”指困难的处境，不能被找到。"}, {"text": "他终于完成了困局。", "explanation": "这里应该用〈任务〉。“完成”用于任务、工作等，“困局”是僵局，不能被完成。"}, {"text": "侦探找到了关键困局。", "explanation": "这里应该用〈线索〉。“线索”指可以帮助破案的信息，“困局”不能作为侦探找到的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们又陷入了一只困局。", "corrected_sentence": "我们又陷入了一个困局。", "error_description": "量词错误：“只”用于动物等，“困局”应用“个”。正确应为“又陷入了一个困局”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只生活困局让他很苦恼。", "corrected_sentence": "这种生活困局让他很苦恼。", "error_description": "量词错误：“只”用于动物等单个的东西，“生活困局”应用量词“种”。正确应为“这种生活困局”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
