INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26338, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "没有水。", "primary_collocate": null, "pronunciation": "wú shuǐ", "ipa": "u˧˥ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个村子长期无水，村民每天走很远去打水。", "target_word": "无水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上无水，我们要自己带水。", "target_word": "无水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里无水，船开不过去了。", "target_word": "无水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水管坏了，家里无水可用。", "target_word": "无水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠中无水，人很难活下去。", "target_word": "无水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天停水，全楼无水。", "target_word": "无水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "井里无水，农民很着急。", "target_word": "无水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路上无水无电，旅行要小心。", "target_word": "无水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花盆里无水，花很快就死了。", "target_word": "无水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一整天无水，大家没法洗澡。", "target_word": "无水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "某处没有水可用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7e5a7ef-e0a6-4733-bdef-e9d65403888e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26338, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无水", "is_correct": true, "explanation": "正确：wú shuǐ，意思是某处没有水可用。"}, {"text": "污水", "is_correct": false, "explanation": "wū（第一声）与 wú（第二声）声调不同，意思是污水。"}, {"text": "雾水", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是雾水。"}, {"text": "无税", "is_correct": false, "explanation": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是无税。"}], "explanations": {"无水": "正确：wú shuǐ，意思是某处没有水可用。", "污水": "wū（第一声）与 wú（第二声）声调不同，意思是污水。", "雾水": "wù（第四声）与 wú（第二声）声调不同，意思是雾水。", "无税": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是无税。"}, "sentence_index": null, "correct_answer": "无水"}, "level_3": {"options": [{"text": "无水", "is_correct": true, "explanation": "正确：“无水”作动词，指某处没有水，与“村民每天走很远去打水”相符。"}, {"text": "有水", "is_correct": false, "explanation": "语义：“有水”与“每天走很远去打水”的情况矛盾。"}, {"text": "通水", "is_correct": false, "explanation": "搭配：“通水”多指管道或线路畅通，放在“长期…村子”中搭配不当，也与去打水矛盾。"}, {"text": "送水", "is_correct": false, "explanation": "语义：“送水”指把水送到家中，与“走很远去打水”的情况相反。"}], "explanations": {"无水": "正确：“无水”作动词，指某处没有水，与“村民每天走很远去打水”相符。", "有水": "语义：“有水”与“每天走很远去打水”的情况矛盾。", "通水": "搭配：“通水”多指管道或线路畅通，放在“长期…村子”中搭配不当，也与去打水矛盾。", "送水": "语义：“送水”指把水送到家中，与“走很远去打水”的情况相反。"}, "sentence_index": 0, "correct_answer": "无水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只小猫无水，身体很虚弱。", "explanation": "这里应该用〈缺水〉。“无水”多指地方或设施没有水可用，描述动物缺水要说“缺水”。"}, {"text": "这台电脑无水，不能正常开机。", "explanation": "这里应该用〈没电〉。“无水”只说地方或设施没有水可用，不能用来形容电脑。"}, {"text": "他是个无水的人，每天都要喝很多水。", "explanation": "这里应该用〈口渴〉。“无水”只说地方或设施没有水可用，不能形容人；人缺水应说口渴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无水", "is_correct": true, "explanation": "正确：井里无水，农民着急，语义通顺。"}, {"text": "灌溉", "is_correct": false, "explanation": "语义：“灌溉”指把水引到田地，不是井里的状态，与农民着急的语境不符。"}, {"text": "装满", "is_correct": false, "explanation": "语义：井里装满水不会让农民着急，与句意矛盾。"}, {"text": "清洗", "is_correct": false, "explanation": "搭配：“清洗”的对象应是物品，“井里清洗”搭配不当。"}], "explanations": {"无水": "正确：井里无水，农民着急，语义通顺。", "灌溉": "语义：“灌溉”指把水引到田地，不是井里的状态，与农民着急的语境不符。", "装满": "语义：井里装满水不会让农民着急，与句意矛盾。", "清洗": "搭配：“清洗”的对象应是物品，“井里清洗”搭配不当。"}, "sentence_index": 6, "correct_answer": "无水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书写得很无水，读起来没意思。", "explanation": "这里应该用〈乏味〉。“无水”只说地方或设施没有水可用，不能形容书的内容。"}, {"text": "他的喉咙无水，说话都困难。", "explanation": "这里应该用〈干涩〉。“无水”指地方或设施没有水可用，喉咙等器官干要说干涩。"}, {"text": "他的书包很无水，背起来很轻松。", "explanation": "这里应该用〈轻〉。“无水”只说地方或设施没有水可用，不能用来形容书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这口井长期很无水，村民很着急。", "corrected_sentence": "这口井长期无水，村民很着急。", "error_description": "程度副词错误：错误形式为“很无水”，正确形式为“无水”。“无水”是动词，表示某处没有水，不能受“很”修饰；要说程度，可用“很缺水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一整天都被无水了，大家没法洗澡。", "corrected_sentence": "这一整天都无水了，大家没法洗澡。", "error_description": "被字句错误：错误形式为“被无水”，正确形式为“无水”。“无水”是表示状态的动词，不能用于被动句，不能与“被”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
