INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26344, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "意思是指每一个单独的事物。", "primary_collocate": null, "pronunciation": "měi yí jiàn", "ipa": "mei̯ i tɕjɛn", "syllable_count": 3, "sentences": [{"text": "每一件事我都记在本子上。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把每一件衬衫都洗得很干净。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里每一件商品都有价格。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢她送的每一件东西。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你看看每一件外套的颜色。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问了病人每一件小事。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家的每一件作品都很有名。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认真地做好每一件工作。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的每一件玩具都放在箱子里。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览会上的每一件产品都能试用。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每一件：指每一个单独的事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '598c31df-7b1e-444b-ae49-80c36c027b68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26344, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "每一件", "is_correct": true, "explanation": "正确答案，指每一个单独的事物。"}, {"text": "没一件", "is_correct": false, "explanation": "没 méi（第二声）与 每 měi（第三声）声调不同，「没一件」意思是「没有一件」。"}, {"text": "每一间", "is_correct": false, "explanation": "间 jiān（第一声）与 件 jiàn（第四声）声调不同，「每一间」指每个房间。"}, {"text": "每一届", "is_correct": false, "explanation": "届 jiè 与 件 jiàn 声调相同，但韵母不同（ie 与 ian），「每一届」指每一期或每一次。"}], "explanations": {"每一件": "正确答案，指每一个单独的事物。", "没一件": "没 méi（第二声）与 每 měi（第三声）声调不同，「没一件」意思是「没有一件」。", "每一间": "间 jiān（第一声）与 件 jiàn（第四声）声调不同，「每一间」指每个房间。", "每一届": "届 jiè 与 件 jiàn 声调相同，但韵母不同（ie 与 ian），「每一届」指每一期或每一次。"}, "sentence_index": null, "correct_answer": "每一件"}, "level_3": {"options": [{"text": "每一件", "is_correct": true, "explanation": "代词，指我记下的每一件事，强调逐个而无例外。"}, {"text": "每一座", "is_correct": false, "explanation": "搭配：「座」用于山、楼房等大型固定之物，不能修饰「事」。"}, {"text": "每一株", "is_correct": false, "explanation": "搭配：“株”用于植物，不能用于“事”。"}, {"text": "每一辈", "is_correct": false, "explanation": "语义：“辈”指世代或辈分，与“记在本子上”的句意不合。"}], "explanations": {"每一件": "代词，指我记下的每一件事，强调逐个而无例外。", "每一座": "搭配：「座」用于山、楼房等大型固定之物，不能修饰「事」。", "每一株": "搭配：“株”用于植物，不能用于“事”。", "每一辈": "语义：“辈”指世代或辈分，与“记在本子上”的句意不合。"}, "sentence_index": 0, "correct_answer": "每一件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我喜欢她送的每一条东西。", "explanation": "这里应该用〈件〉。「条」用于细长的物品，「东西」要用「件」。"}, {"text": "我喜欢她每一件朋友。", "explanation": "这里应该用〈个〉。「件」用于物品，指人要用「个」。"}, {"text": "我喜欢她说的每一张话。", "explanation": "这里应该用〈句〉。「张」用于平面的物件，「话」要用「句」计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每一件", "is_correct": true, "explanation": "代词，指这位画家的每一件作品，强调没有例外，与“很有名”相符。"}, {"text": "每一颗", "is_correct": false, "explanation": "搭配：“颗”用于粒状的小东西，不用于画作。"}, {"text": "每一顿", "is_correct": false, "explanation": "语义：“顿”指一餐，与画家的作品无关，句子不成立。"}, {"text": "每一趟", "is_correct": false, "explanation": "语义：“趟”指往返一次的行程，与“很有名”的作品无关。"}], "explanations": {"每一件": "代词，指这位画家的每一件作品，强调没有例外，与“很有名”相符。", "每一颗": "搭配：“颗”用于粒状的小东西，不用于画作。", "每一顿": "语义：“顿”指一餐，与画家的作品无关，句子不成立。", "每一趟": "语义：“趟”指往返一次的行程，与“很有名”的作品无关。"}, "sentence_index": 6, "correct_answer": "每一件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "展览会上的每一场产品都能试用。", "explanation": "这里应该用〈件〉。「场」用于活动或演出，产品要用「件」。"}, {"text": "展览会上的每一头产品都能试用。", "explanation": "这里应该用〈件〉。「头」用于牲畜，产品要用「件」。"}, {"text": "展览会上的每一本产品都能试用。", "explanation": "这里应该用〈件〉。「本」用于书籍，产品要用「件」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每一件衬衫们都要熨烫平整。", "corrected_sentence": "每一件衬衫都要熨烫平整。", "error_description": "错误在于目标词「每一件」的数量语义：「每一件」指单个个体，不能再跟表复数的「们」。应说「每一件衬衫都要熨烫平整」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每一件玩具们都要收好。", "corrected_sentence": "每一件玩具都要收好。", "error_description": "错误在于目标词「每一件」的数量语义：「每一件」指单个个体，不能再跟表复数的「们」。应说「每一件玩具都要收好」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
