INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26350, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情开始之前必须有的条件。", "primary_collocate": null, "pronunciation": "qián tí", "ipa": "tɕʰjɛn˧˥ tʰi˧˥", "syllable_count": 2, "sentences": [{"text": "努力学习是考上大学的前提。", "target_word": "前提", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在安全的前提下，我们可以试试。", "target_word": "前提", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "健康是做好工作的前提。", "target_word": "前提", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他同意帮忙，前提是我先做完作业。", "target_word": "前提", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了这个前提，我们才能开始谈。", "target_word": "前提", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信任是朋友之间的重要前提。", "target_word": "前提", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有这个前提，计划就不能进行。", "target_word": "前提", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在不迟到的前提下，你可以多睡一会儿。", "target_word": "前提", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，了解问题是解决问题的前提。", "target_word": "前提", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子的前提是先有一笔钱。", "target_word": "前提", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前提条件", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情成立或进行所必须先有的条件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f9422c-71d5-4159-b92d-1d18b93b36af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26350, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "副作用", "is_correct": false, "explanation": "语义：“副作用”指不利的附带影响，与“努力学习是……的前提”的关系不符。"}, {"text": "前提", "is_correct": true, "explanation": "正确。“前提”指事情开始前必须具备的条件，与“努力学习是考上大学的……”相符。"}, {"text": "后果", "is_correct": false, "explanation": "语义：“后果”指做事之后的结果，与“努力学习”作为前提的关系相反。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“数量”指多少，不能与“是……的”构成“必须具备的条件”的说法。"}], "explanations": {"副作用": "语义：“副作用”指不利的附带影响，与“努力学习是……的前提”的关系不符。", "前提": "正确。“前提”指事情开始前必须具备的条件，与“努力学习是考上大学的……”相符。", "后果": "语义：“后果”指做事之后的结果，与“努力学习”作为前提的关系相反。", "数量": "搭配：“数量”指多少，不能与“是……的”构成“必须具备的条件”的说法。"}, "sentence_index": 0, "correct_answer": "前提"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套房子的前提很好，离地铁很近。", "explanation": "这里应该用〈条件〉。“前提”指事情开始前必须具备的条件，不用来描述房子本身的好坏。"}, {"text": "他的英语前提很好，学起来不难。", "explanation": "这里应该用〈基础〉。“基础”指已经有的根基，“前提”不指学习者已有的水平。"}, {"text": "会议的前提已经公布了，下午三点开始。", "explanation": "这里应该用〈时间〉。“前提”指事情开始前必须具备的条件，会议的开始时刻要用“时间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26350, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与计划能否进行没有逻辑联系，句子读不通。"}, {"text": "前提", "is_correct": true, "explanation": "正确。“前提”指计划能否进行所依赖的必要条件，与句意相符。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”指东西的样子，与计划能否进行没有关系，句子读不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”与计划能否进行没有关系，句子读不通。"}], "explanations": {"颜色": "语义：“颜色”与计划能否进行没有逻辑联系，句子读不通。", "前提": "正确。“前提”指计划能否进行所依赖的必要条件，与句意相符。", "形状": "语义：“形状”指东西的样子，与计划能否进行没有关系，句子读不通。", "味道": "语义：“味道”与计划能否进行没有关系，句子读不通。"}, "sentence_index": 6, "correct_answer": "前提"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事有一张前提，大家都要遵守。", "explanation": "这里应该用〈一个〉或〈一项〉。量词“张”用于纸张、桌子等平面的东西，“前提”不用“张”。"}, {"text": "这次合作有一颗前提，需要双方努力。", "explanation": "这里应该用〈一个〉或〈一项〉。量词“颗”用于粒状或圆形的东西，“前提”不用“颗”。"}, {"text": "他有一把前提，就可以开始了。", "explanation": "这里应该用〈一个〉或〈一项〉。量词“把”用于有柄、能握住的东西，“前提”不用“把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在双方同意的前提上，我们可以合作。", "corrected_sentence": "在双方同意的前提下，我们可以合作。", "error_description": "固定搭配错误：“在……前提下”是固定说法，“下”不能写成“上”。写成“前提上”不地道。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "把安全为前提，我们可以去郊游。", "corrected_sentence": "以安全为前提，我们可以去郊游。", "error_description": "介词错误：“以……为前提”是固定框架，应用介词“以”。此句用“把”后接“为前提”不成立；若要用“把”，须写成“把安全作为前提”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
