INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26352, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做东西的方法和本领。", "primary_collocate": null, "pronunciation": "gōng yì", "ipa": "kʊŋ˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "他的木雕工艺非常精细。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师傅的工艺在村里最有名。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她学会了一门做银器的工艺。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件花瓶的工艺很细致。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷的竹编工艺是向父亲学的。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些漂亮的灯笼体现了他高超的工艺。", "target_word": "工艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "景德镇的瓷器以精美的工艺闻名。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人愿意学习传统工艺。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家小店的刺绣工艺让我很喜欢。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把椅子的工艺很好，用了二十年。", "target_word": "工艺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "门", "label": "量词"}, {"form": "工艺品", "label": "复合"}, {"form": "工藝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "手工制作东西的技艺和本领", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7e5a7ef-e0a6-4733-bdef-e9d65403888e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26352, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工艺", "is_correct": true, "explanation": "“他的木雕工艺非常精细”说的是木雕技艺精细，语义吻合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气与木雕的技艺无关，“木雕天气”说不通。"}, {"text": "工钱", "is_correct": false, "explanation": "语义：工钱是报酬，不能用“精细”来描述，与木雕技艺的语境不符。"}, {"text": "嗓音", "is_correct": false, "explanation": "搭配：“精细”不能用来修饰嗓音，“嗓音非常精细”搭配不当。"}], "explanations": {"工艺": "“他的木雕工艺非常精细”说的是木雕技艺精细，语义吻合。", "天气": "语义：天气与木雕的技艺无关，“木雕天气”说不通。", "工钱": "语义：工钱是报酬，不能用“精细”来描述，与木雕技艺的语境不符。", "嗓音": "搭配：“精细”不能用来修饰嗓音，“嗓音非常精细”搭配不当。"}, "sentence_index": 0, "correct_answer": "工艺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件花瓶的工艺很鲜艳。", "explanation": "这里应该用〈颜色〉。工艺指做东西的本领，不能用来形容色彩是否鲜艳。"}, {"text": "她学会了一只做银器的工艺。", "explanation": "这里应该用〈门〉。工艺作为技艺，量词用“门”；“只”多用于动物，不能用于工艺。"}, {"text": "这位工艺的手很巧。", "explanation": "这里应该用〈工匠〉。工艺指技艺本身，不能指做工艺的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26352, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工艺", "is_correct": true, "explanation": "“以精美的工艺闻名”指瓷器的制作技艺精美，语义吻合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“精美”修饰的是技艺或作品，不能修饰“价格”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体貌特征，不能用来描述瓷器的特色。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄与瓷器以何闻名无关，“以精美的年龄闻名”说不通。"}], "explanations": {"工艺": "“以精美的工艺闻名”指瓷器的制作技艺精美，语义吻合。", "价格": "搭配：“精美”修饰的是技艺或作品，不能修饰“价格”。", "身高": "体貌：身高是人的体貌特征，不能用来描述瓷器的特色。", "年龄": "语义：年龄与瓷器以何闻名无关，“以精美的年龄闻名”说不通。"}, "sentence_index": 6, "correct_answer": "工艺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子的工艺只有五公斤。", "explanation": "这里应该用〈重量〉。工艺指做东西的本领，不能用来表示重量。"}, {"text": "这位老师傅吃掉了很多工艺。", "explanation": "这里应该用〈饭〉。工艺是技艺，不能被吃，“吃”的对象应是食物。"}, {"text": "这家工艺每天营业十小时。", "explanation": "这里应该用〈店铺〉。工艺指做东西的本领，不能指店铺，也不能营业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他学了两块竹编工艺。", "corrected_sentence": "他学了两门竹编工艺。", "error_description": "量词错误：“工艺”作为技艺，应用量词“门”；“块”多用于片状物，不能用于工艺，应说“两门竹编工艺”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想学这门精美地工艺。", "corrected_sentence": "他想学这门精美的工艺。", "error_description": "结构助词错误：“精美”修饰名词“工艺”时应用“的”，说“精美的工艺”；“地”只用于修饰动词、形容词，不能用于名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26354, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26354, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26354, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "concrete", "definition": "（东西）旧了、不能再用的。", "primary_collocate": null, "pronunciation": "fèi jiù", "ipa": "feɪ˥˩ tɕjoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "老人每天出门收废旧东西。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "lǎo rén měi tiān chū mén shōu fèi jiù dōng xi.", "sentence_source": "generated"}, {"text": "院子里堆满了废旧东西。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "yuàn zi lǐ duī mǎn le fèi jiù dōng xi.", "sentence_source": "generated"}, {"text": "他靠卖废旧家电赚了一点钱。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "tā kào mài fèi jiù jiā diàn zhuàn le yì diǎn qián.", "sentence_source": "generated"}, {"text": "请把家里的废旧物品送到回收点。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "qǐng bǎ jiā lǐ de fèi jiù wù pǐn sòng dào huí shōu diǎn.", "sentence_source": "generated"}, {"text": "这个社区每周回收一次废旧电器。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "zhè ge shè qū měi zhōu huí shōu yí cì fèi jiù diàn qì.", "sentence_source": "generated"}, {"text": "小李用废旧材料做了很多玩具。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "xiǎo lǐ yòng fèi jiù cái liào zuò le hěn duō wán jù.", "sentence_source": "generated"}, {"text": "车库里的废旧物品要尽快清理。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "chē kù lǐ de fèi jiù wù pǐn yào jǐn kuài qīng lǐ.", "sentence_source": "generated"}, {"text": "那些废旧东西堆在墙角，很占地方。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "nà xiē fèi jiù dōng xi duī zài qiáng jiǎo, hěn zhàn dì fang.", "sentence_source": "generated"}, {"text": "废旧物品不要乱扔，要分类放好。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "fèi jiù wù pǐn bú yào luàn rēng, yào fēn lèi fàng hǎo.", "sentence_source": "generated"}, {"text": "他的小店专门买卖废旧家电。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "tā de xiǎo diàn zhuān mén mǎi mài fèi jiù jiā diàn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "废旧物资", "label": "复合"}, {"form": "废旧物品", "label": "复合"}, {"form": "廢舊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "修饰名词，表示旧了不能再用的（如废旧物品、废旧家电）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7e5a7ef-e0a6-4733-bdef-e9d65403888e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26354, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "废旧", "is_correct": true, "explanation": "废旧：不再有用的旧东西，修饰“东西”，符合“收”的语境。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：“冰冷”描述温度或感觉，与“收废旧东西”的语境不合。"}, {"text": "魁梧", "is_correct": false, "explanation": "体貌：“魁梧”形容人的身材，不能用来修饰“东西”。"}, {"text": "有趣", "is_correct": false, "explanation": "语义：“有趣”形容事情或人，与“收废旧东西”的语境不合。"}], "explanations": {"废旧": "废旧：不再有用的旧东西，修饰“东西”，符合“收”的语境。", "冰冷": "语义：“冰冷”描述温度或感觉，与“收废旧东西”的语境不合。", "魁梧": "体貌：“魁梧”形容人的身材，不能用来修饰“东西”。", "有趣": "语义：“有趣”形容事情或人，与“收废旧东西”的语境不合。"}, "sentence_index": 0, "correct_answer": "废旧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件老物件是一堆废旧东西，很有价值。", "explanation": "这里应该用〈文物〉。废旧东西指不再有用的旧物，有价值的老物件应称文物，不能说“废旧东西”。"}, {"text": "我很爱我的小猫，它是家里最重要的废旧东西。", "explanation": "这里应该用〈宝贝〉。废旧东西指不再有用的旧物，不能用来形容心爱的小猫。"}, {"text": "他的想法很废旧，早就该淘汰了。", "explanation": "这里应该用〈过时〉。废旧东西指不再有用的旧物，用于形容想法已落后时应说〈过时〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26354, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "废旧", "is_correct": true, "explanation": "废旧：不再有用的旧物品，修饰“物品”，符合“清理”的语境。"}, {"text": "珍贵", "is_correct": false, "explanation": "语义：“珍贵”的物品应妥善保存，与“尽快清理”的语境相反。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”的物品无需清理，与“尽快清理”的语境矛盾。"}, {"text": "精致", "is_correct": false, "explanation": "体貌：“精致”形容外形的细巧，与“尽快清理”的语境不合。"}], "explanations": {"废旧": "废旧：不再有用的旧物品，修饰“物品”，符合“清理”的语境。", "珍贵": "语义：“珍贵”的物品应妥善保存，与“尽快清理”的语境相反。", "干净": "语义：“干净”的物品无需清理，与“尽快清理”的语境矛盾。", "精致": "体貌：“精致”形容外形的细巧，与“尽快清理”的语境不合。"}, "sentence_index": 6, "correct_answer": "废旧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些废旧东西都是新买的，还没用过。", "explanation": "这里应该用〈崭新〉。废旧东西指不再有用的旧物，新买未用的东西不能称为废旧东西。"}, {"text": "这些废旧东西煮一煮就能当饭吃。", "explanation": "这里应该用〈食物〉。废旧东西是不再有用的旧物，不能煮来当饭吃。"}, {"text": "他的婚纱是废旧东西，穿起来特别漂亮。", "explanation": "这里应该用〈礼服〉。废旧东西指不再有用的旧物，精心制作的婚纱不能这样称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把攒下的一张废旧东西都卖了。", "corrected_sentence": "她把攒下的一堆废旧东西都卖了。", "error_description": "错误形式：一张废旧东西；正确形式：一堆废旧东西。“张”用于纸张、桌子等平面的东西，成堆的杂物应用“堆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26354, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些东西还能用，没是废旧东西。", "corrected_sentence": "这些东西还能用，不是废旧东西。", "error_description": "错误形式：没是；正确形式：不是。判断句的否定要用“不是”，“没”不能用来否定“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
