INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26358, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "纤维是像线一样细的东西，可以做衣服或绳子。", "primary_collocate": null, "pronunciation": "xiān wéi", "ipa": "ɕjɛn˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这件衣服是用植物纤维做的。", "target_word": "纤维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "椰子壳里有很多纤维，可以做绳子。", "target_word": "纤维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根纤维又细又长。", "target_word": "纤维", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "奶奶用麻的纤维编了一条绳子。", "target_word": "纤维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "毛衣里的纤维很软，穿着很舒服。", "target_word": "纤维", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种绳子的纤维非常结实。", "target_word": "纤维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "竹子的纤维也能做成衣服。", "target_word": "纤维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "衣服上掉下来几根纤维。", "target_word": "纤维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条毛巾的纤维很细，吸水很好。", "target_word": "纤维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用香蕉树的纤维做了一顶帽子。", "target_word": "纤维", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "植物纤维", "label": "复合"}, {"form": "纖維", "label": "繁体"}], "register": "中性", "sense_fingerprint": "像线一样细、可用来做衣服或绳子的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7e5a7ef-e0a6-4733-bdef-e9d65403888e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26358, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "纤维", "is_correct": true, "explanation": "纤维：像线一样细的东西，读音 xiān wéi 与听到的音一致，是正确答案。"}, {"text": "鲜味", "is_correct": false, "explanation": "xiān wèi（鲜味）与 xiān wéi 只有第二音节声调不同（第四声与第二声），意思是鲜美的味道。"}, {"text": "现为", "is_correct": false, "explanation": "xiàn wéi（现为）与 xiān wéi 只有第一音节声调不同（第四声与第一声），意思是“现在是”。"}, {"text": "相违", "is_correct": false, "explanation": "xiāng wéi（相违）与 xiān wéi 的韵尾不同（ng 与 n），意思是相违背。"}], "explanations": {"纤维": "纤维：像线一样细的东西，读音 xiān wéi 与听到的音一致，是正确答案。", "鲜味": "xiān wèi（鲜味）与 xiān wéi 只有第二音节声调不同（第四声与第二声），意思是鲜美的味道。", "现为": "xiàn wéi（现为）与 xiān wéi 只有第一音节声调不同（第四声与第一声），意思是“现在是”。", "相违": "xiāng wéi（相违）与 xiān wéi 的韵尾不同（ng 与 n），意思是相违背。"}, "sentence_index": null, "correct_answer": "纤维"}, "level_3": {"options": [{"text": "纤维", "is_correct": true, "explanation": "纤维：植物纤维是做衣服的天然原料，符合句意。"}, {"text": "矿物", "is_correct": false, "explanation": "语义：“矿物”与“植物”相矛盾，衣服不能用矿物直接做成。"}, {"text": "钢材", "is_correct": false, "explanation": "搭配：“植物”不能修饰“钢材”，两者搭配不当。"}, {"text": "石油", "is_correct": false, "explanation": "语义：石油不是植物，与“植物”的限定相矛盾。"}], "explanations": {"纤维": "纤维：植物纤维是做衣服的天然原料，符合句意。", "矿物": "语义：“矿物”与“植物”相矛盾，衣服不能用矿物直接做成。", "钢材": "搭配：“植物”不能修饰“钢材”，两者搭配不当。", "石油": "语义：石油不是植物，与“植物”的限定相矛盾。"}, "sentence_index": 0, "correct_answer": "纤维"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈往汤里放了一点纤维，汤变得更咸了。", "explanation": "这里应该用〈盐〉。纤维是像线一样细的东西，不是调味品，不能让汤变咸。"}, {"text": "他用一根纤维拧紧了木箱上的螺丝。", "explanation": "这里应该用〈螺丝刀〉。纤维是细丝状的原料，不能用来拧螺丝，应用螺丝刀。"}, {"text": "他很有纤维，每天能跑十公里。", "explanation": "这里应该用〈耐力〉。纤维指像线一样细的原料，不能用来形容人的体力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26358, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "纤维", "is_correct": true, "explanation": "纤维：像线一样细的东西，读音 xiān wéi 与听到的音一致，是正确答案。"}, {"text": "咸味", "is_correct": false, "explanation": "xián wèi（咸味）与 xiān wéi 两个音节的声调都不同，意思是咸的味道。"}, {"text": "显微", "is_correct": false, "explanation": "xiǎn wēi（显微）与 xiān wéi 两个音节的声调都不同，意思是极小、需显微镜才能看清。"}, {"text": "县委", "is_correct": false, "explanation": "xiàn wěi（县委）与 xiān wéi 两个音节的声调都不同，意思是县一级的党委。"}], "explanations": {"纤维": "纤维：像线一样细的东西，读音 xiān wéi 与听到的音一致，是正确答案。", "咸味": "xián wèi（咸味）与 xiān wéi 两个音节的声调都不同，意思是咸的味道。", "显微": "xiǎn wēi（显微）与 xiān wéi 两个音节的声调都不同，意思是极小、需显微镜才能看清。", "县委": "xiàn wěi（县委）与 xiān wéi 两个音节的声调都不同，意思是县一级的党委。"}, "sentence_index": null, "correct_answer": "纤维"}, "level_3": {"options": [{"text": "纤维", "is_correct": true, "explanation": "纤维：竹子的纤维可以加工成衣服，符合句意。"}, {"text": "竹笋", "is_correct": false, "explanation": "语义：竹笋是食材，不能做成衣服，与句意矛盾。"}, {"text": "竹节", "is_correct": false, "explanation": "语义：竹节坚硬，不是可以纺织的纤维材料。"}, {"text": "竹竿", "is_correct": false, "explanation": "语义：竹竿是整根的竹杆，质地坚硬，不能做成衣服，与句意矛盾。"}], "explanations": {"纤维": "纤维：竹子的纤维可以加工成衣服，符合句意。", "竹笋": "语义：竹笋是食材，不能做成衣服，与句意矛盾。", "竹节": "语义：竹节坚硬，不是可以纺织的纤维材料。", "竹竿": "语义：竹竿是整根的竹杆，质地坚硬，不能做成衣服，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "纤维"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们把香蕉树的纤维倒进杯子里喝了。", "explanation": "这里应该用〈果汁〉。纤维是细丝状的固体，不能倒进杯子里喝。"}, {"text": "这顶帽子的纤维唱歌很好听。", "explanation": "这里应该用〈主人〉。纤维是做帽子的细丝材料，不会唱歌。"}, {"text": "今天的纤维很好，我们去公园玩吧。", "explanation": "这里应该用〈天气〉。纤维指像线一样细的东西，不能用来说天气好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她从衣服上拽下一只纤维。", "corrected_sentence": "她从衣服上拽下一根纤维。", "error_description": "错误形式：一只纤维；正确形式：一根纤维。“只”多用于动物或成对器物中的单个，细长的纤维应用“根”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把竹子的纤维拧很紧。", "corrected_sentence": "他们把竹子的纤维拧得很紧。", "error_description": "错误形式：拧很紧；正确形式：拧得很紧。程度补语要用“得”引出，结构是“动词+得+补语”，漏掉“得”即是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26360, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "健步如飞", "is_correct": true, "explanation": "“健步如飞”形容走路轻快，与“举步维艰”的行走困难形成反义。"}, {"text": "一望无际", "is_correct": false, "explanation": "“一望无际”形容视野开阔，与“举步维艰”无反义关系。"}, {"text": "大义凛然", "is_correct": false, "explanation": "“大义凛然”形容正气、庄严，与“举步维艰”无反义关系。"}, {"text": "光明磊落", "is_correct": false, "explanation": "“光明磊落”形容为人坦荡，与“举步维艰”的行走义无关。"}], "correct_answer": "健步如飞", "explanations": {"健步如飞": "“健步如飞”形容走路轻快，与“举步维艰”的行走困难形成反义。", "一望无际": "“一望无际”形容视野开阔，与“举步维艰”无反义关系。", "大义凛然": "“大义凛然”形容正气、庄严，与“举步维艰”无反义关系。", "光明磊落": "“光明磊落”形容为人坦荡，与“举步维艰”的行走义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26360, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "健步如飞", "is_correct": true, "explanation": "“健步如飞”形容走路轻快，与“举步维艰”的行走困难形成反义。"}, {"text": "循规蹈矩", "is_correct": false, "explanation": "“循规蹈矩”指按规矩办事，与“举步维艰”的行走义无反义关系。"}, {"text": "五彩缤纷", "is_correct": false, "explanation": "“五彩缤纷”形容颜色丰富，与“举步维艰”无反义关系。"}, {"text": "从容不迫", "is_correct": false, "explanation": "“从容不迫”指不慌不忙，与“举步维艰”的困难义无反义关系。"}], "correct_answer": "健步如飞", "explanations": {"健步如飞": "“健步如飞”形容走路轻快，与“举步维艰”的行走困难形成反义。", "循规蹈矩": "“循规蹈矩”指按规矩办事，与“举步维艰”的行走义无反义关系。", "五彩缤纷": "“五彩缤纷”形容颜色丰富，与“举步维艰”无反义关系。", "从容不迫": "“从容不迫”指不慌不忙，与“举步维艰”的困难义无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26360, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "走路很困难，做事情很难。", "primary_collocate": null, "pronunciation": "jǔ bù wéi jiān", "ipa": "tɕy˨˩˦ pu˥˩ weɪ˧˥ tɕjɛn˥˥", "syllable_count": 4, "sentences": [{"text": "他的腿受伤了，走起路来举步维艰。", "target_word": "举步维艰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪封山，我们在雪地里举步维艰。", "target_word": "举步维艰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有钱，他的小店开得举步维艰。", "target_word": "举步维艰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水很深，孩子们过河时举步维艰。", "target_word": "举步维艰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爬了一天山，她累得举步维艰。", "target_word": "举步维艰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司没有新客人，生意举步维艰。", "target_word": "举步维艰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人腿疼，下楼时举步维艰。", "target_word": "举步维艰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人帮忙，这件事举步维艰。", "target_word": "举步维艰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上全是泥，大家走得举步维艰。", "target_word": "举步维艰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚学做生意，开始时举步维艰。", "target_word": "举步维艰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "成语，走路很难或做事很难", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc02ac77-f897-4891-b52f-1733019e3215') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26360, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "举步维艰", "is_correct": true, "explanation": "腿受伤后走路困难，与“走起路来”的语境相符。"}, {"text": "健步如飞", "is_correct": false, "explanation": "语义：腿已经受伤，不可能“健步如飞”，与句中的伤情矛盾。"}, {"text": "一帆风顺", "is_correct": false, "explanation": "搭配：“一帆风顺”说事情进展顺利，不用于描写走路。"}, {"text": "蒸蒸日上", "is_correct": false, "explanation": "搭配：“蒸蒸日上”形容事业或形势兴旺，不用于描写走路。"}], "explanations": {"举步维艰": "腿受伤后走路困难，与“走起路来”的语境相符。", "健步如飞": "语义：腿已经受伤，不可能“健步如飞”，与句中的伤情矛盾。", "一帆风顺": "搭配：“一帆风顺”说事情进展顺利，不用于描写走路。", "蒸蒸日上": "搭配：“蒸蒸日上”形容事业或形势兴旺，不用于描写走路。"}, "sentence_index": 0, "correct_answer": "举步维艰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的封面颜色很漂亮，看起来举步维艰。", "explanation": "语义：“举步维艰”形容人走路或做事困难，不能用来描写物品的外观。"}, {"text": "这次比赛他一路领先，跑得举步维艰。", "explanation": "语义：“举步维艰”形容行走困难，此处误用为“轻快迅速”的意思，与语境颠倒。"}, {"text": "这次考试他轻松作答，顺利完成了全部题目，答题时举步维艰。", "explanation": "语义：“举步维艰”表示做事困难，此处误用为“从容顺手”的意思，与前文的完成情况相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26360, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "举步维艰", "is_correct": true, "explanation": "老人腿疼，下楼时行动困难，与句意吻合。"}, {"text": "轻而易举", "is_correct": false, "explanation": "语义：老人腿疼，下楼不可能“轻而易举”，与句中的伤痛矛盾。"}, {"text": "一往无前", "is_correct": false, "explanation": "语义：腿疼时不可能“一往无前”地下楼，与句中的身体状况矛盾。"}, {"text": "游刃有余", "is_correct": false, "explanation": "搭配：“游刃有余”多用于处理事务，不用于描写下楼。"}], "explanations": {"举步维艰": "老人腿疼，下楼时行动困难，与句意吻合。", "轻而易举": "语义：老人腿疼，下楼不可能“轻而易举”，与句中的伤痛矛盾。", "一往无前": "语义：腿疼时不可能“一往无前”地下楼，与句中的身体状况矛盾。", "游刃有余": "搭配：“游刃有余”多用于处理事务，不用于描写下楼。"}, "sentence_index": 6, "correct_answer": "举步维艰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他身体灵活，三步并作两步，走起路来举步维艰。", "explanation": "语义：“三步并作两步”形容走得快，与“举步维艰”的行走困难义相反。"}, {"text": "这座新建的大桥很平稳，车辆行驶得举步维艰。", "explanation": "语义：“举步维艰”形容行走困难，此处误用为“畅通无阻”的意思，与语境颠倒。"}, {"text": "孩子身体灵活，跑起来却举步维艰。", "explanation": "语义：“举步维艰”形容行走困难，此处误用为“轻快敏捷”的意思，与语境颠倒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他崴了脚，上台阶时走地举步维艰。", "corrected_sentence": "他崴了脚，上台阶时走得举步维艰。", "error_description": "错误：“走地举步维艰”。正确：“走得举步维艰”。“举步维艰”作“走”的补语，补语前应用“得”，“地”用于状语，不能用于此处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪大路滑，我们走举步维艰。", "corrected_sentence": "雪大路滑，我们走得举步维艰。", "error_description": "错误：“走举步维艰”。正确：“走得举步维艰”。补语前须用“得”，漏掉“得”则不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
