INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26362, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不买某个东西，或者不去做某件事。", "primary_collocate": null, "pronunciation": "dǐ zhì", "ipa": "ti˨˩˦ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "我们抵制这个品牌，不再买它的鞋。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多网友抵制那部电影，没有人去看。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顾客抵制涨价的饮料，一瓶也不买。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们抵制新规定，拒绝加班。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们抵制这家店，因为东西太贵。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家抵制过那家商店的假货。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "居民抵制这家工厂，因为它污染河水。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民抵制这场比赛，没人买票。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多家长抵制这款游戏，不让孩子玩。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消费者抵制着这种产品，商店卖不出去。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抵制了", "label": "体标"}, {"form": "抵制着", "label": "体标"}, {"form": "抵制过", "label": "体标"}], "register": "中性", "sense_fingerprint": "不买某物或不做某事，以示反对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc02ac77-f897-4891-b52f-1733019e3215') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26362, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抵制", "is_correct": true, "explanation": "本词，读作 dǐ zhì，表示不买某物或不做某事，以示反对。"}, {"text": "地质", "is_correct": false, "explanation": "dì（第四声）与 dǐ（第三声）声调不同，意思是地质。"}, {"text": "体制", "is_correct": false, "explanation": "tǐ 与 dǐ 声母不同（t 与 d），意思是体制。"}, {"text": "地支", "is_correct": false, "explanation": "dì 与 dǐ 声调不同，zhī 与 zhì 声调也不同，意思是地支。"}], "explanations": {"抵制": "本词，读作 dǐ zhì，表示不买某物或不做某事，以示反对。", "地质": "dì（第四声）与 dǐ（第三声）声调不同，意思是地质。", "体制": "tǐ 与 dǐ 声母不同（t 与 d），意思是体制。", "地支": "dì 与 dǐ 声调不同，zhī 与 zhì 声调也不同，意思是地支。"}, "sentence_index": null, "correct_answer": "抵制"}, "level_3": {"options": [{"text": "抵制", "is_correct": true, "explanation": "原句中的词，表示不再买这个品牌的东西，以示反对。"}, {"text": "支持", "is_correct": false, "explanation": "语义：“支持”与“不再买它的鞋”矛盾。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”与“不再买”矛盾。"}, {"text": "拥护", "is_correct": false, "explanation": "语域：“拥护”偏书面，与句子的口语语境不协调，且与“不再买”矛盾。"}], "explanations": {"抵制": "原句中的词，表示不再买这个品牌的东西，以示反对。", "支持": "语义：“支持”与“不再买它的鞋”矛盾。", "享受": "语义：“享受”与“不再买”矛盾。", "拥护": "语域：“拥护”偏书面，与句子的口语语境不协调，且与“不再买”矛盾。"}, "sentence_index": 0, "correct_answer": "抵制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把伞能抵制雨水，很好用。", "explanation": "这里应该用〈抵挡〉。“抵制”指不买、不做以示反对，雨水这类自然力量应说“抵挡”。"}, {"text": "为了安全，我们要抵制火灾。", "explanation": "这里应该用〈防止〉。“抵制”指不买、不做以示反对，火灾这类事故应说“防止”。"}, {"text": "这家店的新品很受欢迎，大家都抵制它，天天排队去买。", "explanation": "这里应该用〈光顾〉。“抵制”指不买、不做以示反对，此处写成排队购买，与本义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26362, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "抵制", "is_correct": true, "explanation": "本词，读作 dǐ zhì，表示不买某物或不做某事，以示反对。"}, {"text": "地址", "is_correct": false, "explanation": "dì（第四声）与 dǐ（第三声）声调不同，zhǐ 与 zhì 声调也不同，意思是地址。"}, {"text": "体质", "is_correct": false, "explanation": "tǐ 与 dǐ 声母不同（t 与 d），意思是人的身体素质，即体质。"}, {"text": "低值", "is_correct": false, "explanation": "dī 与 dǐ 声调不同，zhí 与 zhì 声调也不同，意思是价值低，即低值。"}], "explanations": {"抵制": "本词，读作 dǐ zhì，表示不买某物或不做某事，以示反对。", "地址": "dì（第四声）与 dǐ（第三声）声调不同，zhǐ 与 zhì 声调也不同，意思是地址。", "体质": "tǐ 与 dǐ 声母不同（t 与 d），意思是人的身体素质，即体质。", "低值": "dī 与 dǐ 声调不同，zhí 与 zhì 声调也不同，意思是价值低，即低值。"}, "sentence_index": null, "correct_answer": "抵制"}, "level_3": {"options": [{"text": "抵制", "is_correct": true, "explanation": "正确。工厂污染河水，居民用不支持、不合作的方式表示反对。"}, {"text": "支持", "is_correct": false, "explanation": "语义：工厂污染河水，居民不会因此“支持”它，与原因矛盾。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：污染河水不是值得“感谢”的理由，与句意矛盾。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：污染河水不会得到“表扬”，与句意矛盾。"}], "explanations": {"抵制": "正确。工厂污染河水，居民用不支持、不合作的方式表示反对。", "支持": "语义：工厂污染河水，居民不会因此“支持”它，与原因矛盾。", "感谢": "语义：污染河水不是值得“感谢”的理由，与句意矛盾。", "表扬": "语义：污染河水不会得到“表扬”，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "抵制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影很精彩，大家都抵制它，纷纷去电影院看。", "explanation": "这里误把“抵制”当成了“支持、追捧”的意思，但它表示不买、不去做以示反对，与“纷纷去电影院看”相反。"}, {"text": "这种药可以抵制感冒的发作。", "explanation": "这里应该用〈预防〉。“抵制”指不买、不做以示反对，疾病的发作应说“预防”。"}, {"text": "老师要求我们抵制困难，勇敢向前。", "explanation": "这里应该用〈克服〉。“抵制”指不买、不做以示反对，困难要说“克服”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们抵制于这家店的假货，不去买东西。", "corrected_sentence": "我们抵制这家店的假货，不去买东西。", "error_description": "错误形式：多加介词“于”。正确形式：“抵制”直接接宾语，不说“抵制于……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "观众抵制得那家剧场，没有人去看演出。", "corrected_sentence": "观众抵制了那家剧场，没有人去看演出。", "error_description": "错误形式：“得”。正确形式：“了”。“得”后面要接补语，如“抵制得很厉害”；这里表示动作已完成，应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
