INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26364, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让小东西长大，比如种花或教小孩。", "primary_collocate": null, "pronunciation": "péi yù", "ipa": "pʰeɪ˧˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈在阳台上培育了很多花。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷培育的小树已经长高了。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用心培育着家里的几盆兰花。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，我想培育一些青菜。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸妈妈辛苦培育孩子长大。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶把种子放进土里，慢慢培育它们。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在小花园里培育玫瑰。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师耐心培育每一个小朋友。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我培育的小花终于开了。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在温室里培育小苗，天暖了再种到地里。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "培育了", "label": "体标"}, {"form": "培育过", "label": "体标"}, {"form": "培育着", "label": "体标"}], "register": "中性", "sense_fingerprint": "照顾花草小苗或孩子，让他们慢慢长大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc02ac77-f897-4891-b52f-1733019e3215') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "培育", "is_correct": true, "explanation": "妈妈在阳台上照料花草，使其生长，“培育”与句意吻合。"}, {"text": "摧毁", "is_correct": false, "explanation": "语义：“摧毁”与“阳台上养花”的照料之意相反。"}, {"text": "挖掘", "is_correct": false, "explanation": "搭配：“挖掘”多用于地下资源、文物或潜力，与阳台上养花的语境不合。"}, {"text": "消失", "is_correct": false, "explanation": "配价：“消失”是不及物动词，不能带“花”作宾语。"}], "explanations": {"培育": "妈妈在阳台上照料花草，使其生长，“培育”与句意吻合。", "摧毁": "语义：“摧毁”与“阳台上养花”的照料之意相反。", "挖掘": "搭配：“挖掘”多用于地下资源、文物或潜力，与阳台上养花的语境不合。", "消失": "配价：“消失”是不及物动词，不能带“花”作宾语。"}, "sentence_index": 0, "correct_answer": "培育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在工地上培育了一座大桥。", "explanation": "这里应该用〈修建〉。培育指让小东西长大，大桥不会生长，不能这样用。"}, {"text": "他在阳台上培育了一张桌子。", "explanation": "语义：“培育”指让小东西长大，此处误用为“制作、摆放”的意思，家具不会生长，不能这样用。"}, {"text": "我的书包培育得很好。", "explanation": "语义：“培育”指让小东西长大，此处误用为“照料、保管”的意思，物品不会生长，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "培育", "is_correct": true, "explanation": "在小花园里照料玫瑰使其生长，“培育”与句意吻合。"}, {"text": "熨烫", "is_correct": false, "explanation": "搭配：“熨烫”用于衣物、布料，不能用于玫瑰。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：“驱赶”的对象不能是植物，句中玫瑰无法被驱赶。"}, {"text": "扑灭", "is_correct": false, "explanation": "搭配：“扑灭”多用于火、疫情，不说扑灭“玫瑰”。"}], "explanations": {"培育": "在小花园里照料玫瑰使其生长，“培育”与句意吻合。", "熨烫": "搭配：“熨烫”用于衣物、布料，不能用于玫瑰。", "驱赶": "语义：“驱赶”的对象不能是植物，句中玫瑰无法被驱赶。", "扑灭": "搭配：“扑灭”多用于火、疫情，不说扑灭“玫瑰”。"}, "sentence_index": 6, "correct_answer": "培育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把旧衣服都培育了。", "explanation": "语义：“培育”指让小东西长大，此处误用为“处理、丢弃”的意思，织物不会生长，不能这样用。"}, {"text": "他在厨房里培育了一锅汤。", "explanation": "语义：“培育”指让小东西长大，此处误用为“熬煮、烹制”的意思，烹饪成品不会生长。"}, {"text": "这个工厂培育了很多钢材。", "explanation": "语义：此处误用为“生产、加工”的意思，“培育”只用于让小东西长大，不能用于金属。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶在窗台上培育着了几盆兰花。", "corrected_sentence": "奶奶在窗台上培育了几盆兰花。", "error_description": "错误：“培育着了”。正确：“培育了”。“着”表示持续，“了”表示完成，二者叠用于“培育”这类动作动词不通，此处只保留“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们用了一个冬天培育了出一批小苗。", "corrected_sentence": "我们用了一个冬天培育出一批小苗。", "error_description": "错误：“培育了出”。正确：“培育出”。“出”作结果补语应直接接在动词之后，“培育了出”的说法不规范，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
