INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26368, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26368, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "意思是“才”或“才能”，表示有了某个条件后，才能做另一件事。", "primary_collocate": null, "pronunciation": "fāng néng", "ipa": "fɑŋ˥ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "必须先买票，方能进入公园。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了十八岁，方能参加这个比赛。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设备通过安全检测后，方能投入使用。", "target_word": "方能", "complexity_tier": "T3", "furigana": "shè bèi tōng guò ān quán jiǎn cè hòu, fāng néng tóu rù shǐ yòng.", "sentence_source": "generated"}, {"text": "申请材料全部提交后，方能进入审核流程。", "target_word": "方能", "complexity_tier": "T3", "furigana": "shēn qǐng cái liào quán bù tí jiāo hòu, fāng néng jìn rù shěn hé liú chéng.", "sentence_source": "generated"}, {"text": "要有耐心，方能做好这件事。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验器材彻底消毒后，方能用于样本检测。", "target_word": "方能", "complexity_tier": "T3", "furigana": "shí yàn qì cái chè dǐ xiāo dú hòu, fāng néng yòng yú yàng běn jiǎn cè.", "sentence_source": "generated"}, {"text": "天气暖和了，花儿方能盛开。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了钥匙，方能打开这扇门。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过老师同意，方能离开教室。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站得高，方能看得远。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "书面副词，相当于“才”“才能”，强调先有条件、后做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fc57a-06de-4b32-86c6-7fa8c22896d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26368, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方能", "is_correct": true, "explanation": "正确：「方能」表示只有先买票这一条件满足，才能进入公园。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：「竟然」表示出乎意料，与「必须先买票」这种规定语境不合。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：「已经」表示已经发生，与「必须先……」这种尚未发生的前提不搭配。"}, {"text": "却", "is_correct": false, "explanation": "语义：「却」表示转折，而此句前后是顺承的条件关系，没有转折。"}], "explanations": {"方能": "正确：「方能」表示只有先买票这一条件满足，才能进入公园。", "竟然": "语义：「竟然」表示出乎意料，与「必须先买票」这种规定语境不合。", "已经": "搭配：「已经」表示已经发生，与「必须先……」这种尚未发生的前提不搭配。", "却": "语义：「却」表示转折，而此句前后是顺承的条件关系，没有转折。"}, "sentence_index": 0, "correct_answer": "方能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题他一看就方能明白。", "explanation": "这里应删去〈方能〉，直接说「一看就明白」。「一……就……」表示紧接着发生，与「方能」表示的条件关系冲突。"}, {"text": "她听到这个消息，马上方能哭了起来。", "explanation": "这里应删去〈方能〉。“马上……”表示立刻发生，不需要任何条件，而「方能」表示满足条件后才能做，语义冲突。"}, {"text": "他方能准时到达。", "explanation": "这里应该用〈一定〉。「方能」表示只有满足条件才能实现结果，句中没有条件，表示确定会发生应当用「一定」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26368, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方能", "is_correct": true, "explanation": "正确：「方能」表示天气暖和这一条件满足后，花儿才能盛开。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：「偏偏」表示有意与常理相反，与「天气暖和了」这种顺理成章的原因不合。"}, {"text": "必须", "is_correct": false, "explanation": "语义：「必须」表示事理上的要求，花儿不能被要求盛开，句意不通。"}, {"text": "却", "is_correct": false, "explanation": "语义：「却」表示转折，而此句前后是因果关系，没有转折。"}], "explanations": {"方能": "正确：「方能」表示天气暖和这一条件满足后，花儿才能盛开。", "偏偏": "语义：「偏偏」表示有意与常理相反，与「天气暖和了」这种顺理成章的原因不合。", "必须": "语义：「必须」表示事理上的要求，花儿不能被要求盛开，句意不通。", "却": "语义：「却」表示转折，而此句前后是因果关系，没有转折。"}, "sentence_index": 6, "correct_answer": "方能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没复习，方能考好。", "explanation": "这里应该用〈却〉。「方能」要求先满足某个条件才能实现结果，此句条件并未满足，表示转折应用「却」。"}, {"text": "她每天方能喝茶。", "explanation": "这里应该用〈总是〉。「方能」表示只有满足条件才能实现结果，不能表示经常性的习惯。"}, {"text": "这种做法方能失败。", "explanation": "这里应该用〈必然〉。「方能」表示条件，不能表示必然会发生的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26368, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "必须先签字，才方能办理手续。", "corrected_sentence": "必须先签字，方能办理手续。", "error_description": "错误：「方能」前又加了「才」，两者都表示“只有……才……”，叠用多余。正确：「必须先签字，方能办理手续。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26368, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "早睡早起，方能能身体健康。", "corrected_sentence": "早睡早起，方能身体健康。", "error_description": "错误：「方能」本身已含“能”的意思，后面不能再加「能」，「方能能」重复。正确：「早睡早起，方能身体健康。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
