INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26372, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使某物（如图片背景、图层）变得透明，能透过它看到后面的内容。", "primary_collocate": null, "pronunciation": "tòu míng huà", "ipa": "tʰoʊ˥˩ miŋ˧˥ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "我把照片的背景透明化了。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}, {"text": "设计师先把图层透明化，再放到图片上。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}, {"text": "修图时，先把白色底色透明化。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}, {"text": "这张图标的背景可以透明化。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}, {"text": "这张图片的边框已经透明化了。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}, {"text": "他用软件把水印透明化了。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}, {"text": "这个素材的背景透明化后，可以放在任何图片上。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}, {"text": "经过透明化处理，这张图片的背景看不见了。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}, {"text": "把图片的背景透明化后，文字看得更清楚。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}, {"text": "老师教我们怎样把图层透明化。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "让物体变得透明，能看清里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '598c31df-7b1e-444b-ae49-80c36c027b68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26372, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "透明化", "is_correct": true, "explanation": "动词，表示使照片背景变得透明，与“我把……了”的结构相符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能用来处理照片背景。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，与修图无关，句子不成立。"}, {"text": "发酵", "is_correct": false, "explanation": "配价：“发酵”是不及物动词，不能带“把”字宾语。"}], "explanations": {"透明化": "动词，表示使照片背景变得透明，与“我把……了”的结构相符。", "煮": "搭配：“煮”的对象是食物，不能用来处理照片背景。", "唱": "语义：“唱”指发声演唱，与修图无关，句子不成立。", "发酵": "配价：“发酵”是不及物动词，不能带“把”字宾语。"}, "sentence_index": 0, "correct_answer": "透明化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这首歌透明化了。", "explanation": "这里应该用〈删除〉。「删除」指去掉某项内容；「透明化」只用于图像或图层的显示效果，不能用于歌曲。"}, {"text": "摄影师把这张照片透明化成了方形。", "explanation": "这里应该用〈裁剪〉。「裁剪」指去掉图片的多余部分、改变形状；「透明化」只改变透明效果，不能改变形状。"}, {"text": "他把这杯牛奶透明化了。", "explanation": "这里应该用〈加热〉。「加热」指升高温度；「透明化」只用于图像或图层的显示效果，不能用于液体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "透明化", "is_correct": true, "explanation": "动词，表示使素材背景透明，之后可以叠放在其他图片上，句意通顺。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：背景是图像元素，不能被冷冻，句子不成立。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”指破坏实物，与素材背景的处理无关，后文也无法接续。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”的对象是农作物，不能用于图像背景。"}], "explanations": {"透明化": "动词，表示使素材背景透明，之后可以叠放在其他图片上，句意通顺。", "冷冻": "语义：背景是图像元素，不能被冷冻，句子不成立。", "打碎": "语义：“打碎”指破坏实物，与素材背景的处理无关，后文也无法接续。", "收割": "搭配：“收割”的对象是农作物，不能用于图像背景。"}, "sentence_index": 6, "correct_answer": "透明化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师教我们怎样透明化鸡蛋。", "explanation": "这里应该用〈煮〉。「煮」指用水加热食物；「透明化」只用于图像或图层的显示效果，不能用于食物。"}, {"text": "老师教我们怎样透明化电脑的密码。", "explanation": "这里应该用〈修改〉。「修改」指改动内容，如更换密码；「透明化」只用于图像或图层的显示效果，不能用于密码。"}, {"text": "老师教我们怎样透明化打印的文档。", "explanation": "这里应该用〈复印〉。「复印」指把文档复制一份；「透明化」只用于图像或图层的显示效果，不能用于纸质文档。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把图标的背景把透明化了。", "corrected_sentence": "他把图标的背景透明化了。", "error_description": "“把”字重复：一个“把”字句只能用一次“把”，“把图标的背景”后不应再加“把”。应说“他把图标的背景透明化了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把这个图层很透明化。", "corrected_sentence": "请把这个图层透明化。", "error_description": "错误在于“很”：“很”是程度副词，不能直接修饰动词“透明化”。删去“很”，应说“请把这个图层透明化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
