INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26382, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26382, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变成符号或样子。", "primary_collocate": null, "pronunciation": "fú hào huà", "ipa": "fu˧˥ xɑʊ˥˩ xuɑ˥˩", "syllable_count": 3, "sentences": [{"text": "设计师把公司的名字符号化，做成了小图标。", "target_word": "符号化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把天气符号化，用图画表示。", "target_word": "符号化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师把太阳符号化，画成一个圆和几条线。", "target_word": "符号化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们把动物符号化，画成简单的图形。", "target_word": "符号化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家把月亮符号化，变成一个白圈。", "target_word": "符号化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把心情符号化，写成几个字母。", "target_word": "符号化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图把山符号化，用三角形表示。", "target_word": "符号化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学课上，我们学着把问题符号化。", "target_word": "符号化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师把声音符号化，写成一串数字。", "target_word": "符号化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把每个房间符号化，在地图上画成小方块。", "target_word": "符号化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "符号化了", "label": "体标"}, {"form": "符號化", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把事物变成符号或简单图形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc02ac77-f897-4891-b52f-1733019e3215') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "符号化", "is_correct": true, "explanation": "正确。“把公司的名字符号化，做成小图标”，动词“符号化”表示把名字变成符号。"}, {"text": "配音", "is_correct": false, "explanation": "搭配：“配音”用于声音或影视作品，不能用于“名字”。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：“烘干”指去除水分，与“做成小图标”的语境无关。"}, {"text": "煮", "is_correct": false, "explanation": "配价：“煮”要求食物类宾语，“公司的名字”不能被煮。"}], "explanations": {"符号化": "正确。“把公司的名字符号化，做成小图标”，动词“符号化”表示把名字变成符号。", "配音": "搭配：“配音”用于声音或影视作品，不能用于“名字”。", "烘干": "语义：“烘干”指去除水分，与“做成小图标”的语境无关。", "煮": "配价：“煮”要求食物类宾语，“公司的名字”不能被煮。"}, "sentence_index": 0, "correct_answer": "符号化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把小猫符号化，喂饱了它。", "explanation": "这里应该用〈喂养〉。符号化指把事物变成符号或样子，不指喂养动物。"}, {"text": "我把这篇文章符号化了，只留下几段。", "explanation": "这里应该用〈缩短〉。符号化指把事物变成符号或样子，不指压缩文章的篇幅。"}, {"text": "他把这首诗符号化成了法语。", "explanation": "这里应该用〈翻译〉。符号化指把事物变成符号或样子，不指把一种语言转换成另一种语言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "符号化", "is_correct": true, "explanation": "正确。“地图把山符号化，用三角形表示”，动词“符号化”表示把山变成符号。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指用火加热，与“用三角形表示”的语境无关。"}, {"text": "出售", "is_correct": false, "explanation": "配价：“出售”需要可交易的物品作宾语，“地图把山出售”不符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不与“山”搭配，“把山唱”不成说法。"}], "explanations": {"符号化": "正确。“地图把山符号化，用三角形表示”，动词“符号化”表示把山变成符号。", "烧": "语义：“烧”指用火加热，与“用三角形表示”的语境无关。", "出售": "配价：“出售”需要可交易的物品作宾语，“地图把山出售”不符合句意。", "唱": "搭配：“唱”不与“山”搭配，“把山唱”不成说法。"}, "sentence_index": 6, "correct_answer": "符号化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人把这座塔符号化成了公园。", "explanation": "这里应该用〈修建〉。符号化指把事物变成符号或样子，不指把塔改造成公园。"}, {"text": "人们用水符号化了这座塔。", "explanation": "这里应该用〈清洗〉。符号化指把事物变成符号或样子，不指用水去洗涤。"}, {"text": "工人用水泥符号化了塔上的裂缝。", "explanation": "这里应该用〈掩盖〉。符号化指把事物变成符号或样子，不指用水泥遮住裂缝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "设计师了这个标志符号化了，做成了小图标。", "corrected_sentence": "设计师把这个标志符号化了，做成了小图标。", "error_description": "介词错误：把字句中的介词“把”被误写为“了”，应写成“设计师把这个标志符号化了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地图山符号化了，用三角形表示。", "corrected_sentence": "地图把山符号化了，用三角形表示。", "error_description": "句式错误：“地图”与“山”之间缺少“把”字（或改用“被”字句），直接说“地图山符号化了”不成句，应写成“地图把山符号化了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
