INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26384, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "命脉就像身体的血管，是让事物活起来的最重要的东西。", "primary_collocate": null, "pronunciation": "mìng mài", "ipa": "miŋ˥˩ mai˥˩", "syllable_count": 2, "sentences": [{"text": "对小店来说，客人就是命脉。", "target_word": "命脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街的命脉是夜市。", "target_word": "命脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的命脉是好老师。", "target_word": "命脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读者是报纸的命脉。", "target_word": "命脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有电，这座工厂就失去了命脉。", "target_word": "命脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水路是这个小镇的命脉。", "target_word": "命脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "创新是公司的命脉。", "target_word": "命脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家老店的命脉是一碗好面。", "target_word": "命脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民说，土地就是他们的命脉。", "target_word": "命脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络成了现代生活的命脉。", "target_word": "命脉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "经济命脉", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，比作血管，指让店铺、学校、公司等活下去的最重要的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fc57a-06de-4b32-86c6-7fa8c22896d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "命脉", "is_correct": true, "explanation": "正确：“客人就是命脉”说明客人是小店存续的关键，与语境吻合。"}, {"text": "门槛", "is_correct": false, "explanation": "语义：“门槛”是门下的横木，不能表达客人对小店存续的重要性。"}, {"text": "窗台", "is_correct": false, "explanation": "语义：“窗台”是窗下的台面，与小店生存的关键作用无关。"}, {"text": "书架", "is_correct": false, "explanation": "搭配：“书架”是家具，不能与“就是”构成对客人作用的判断。"}], "explanations": {"命脉": "正确：“客人就是命脉”说明客人是小店存续的关键，与语境吻合。", "门槛": "语义：“门槛”是门下的横木，不能表达客人对小店存续的重要性。", "窗台": "语义：“窗台”是窗下的台面，与小店生存的关键作用无关。", "书架": "搭配：“书架”是家具，不能与“就是”构成对客人作用的判断。"}, "sentence_index": 0, "correct_answer": "命脉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对历史的命脉很浓厚。", "explanation": "这里应该用〈兴趣〉。命脉指关键部分，不用来形容人的爱好。"}, {"text": "这盏灯的命脉很长。", "explanation": "这里应该用〈寿命〉。命脉指关键部分，不指使用的年限。"}, {"text": "这家店的命脉今年涨价了。", "explanation": "这里应该用〈价格〉。命脉指事物存续的关键，不用来说价格的涨跌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "命脉", "is_correct": true, "explanation": "正确：“创新是公司的命脉”说明创新是公司存续的关键，与语境吻合。"}, {"text": "烟囱", "is_correct": false, "explanation": "语义：“烟囱”是排烟的建筑构件，不能表示创新对公司存续的作用。"}, {"text": "鞋垫", "is_correct": false, "explanation": "语义：“鞋垫”是垫在鞋里的日用品，不能表示创新对公司存续的作用。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：“地毯”是铺在地上的织物，与“创新是公司的”这一判断无关。"}], "explanations": {"命脉": "正确：“创新是公司的命脉”说明创新是公司存续的关键，与语境吻合。", "烟囱": "语义：“烟囱”是排烟的建筑构件，不能表示创新对公司存续的作用。", "鞋垫": "语义：“鞋垫”是垫在鞋里的日用品，不能表示创新对公司存续的作用。", "地毯": "语义：“地毯”是铺在地上的织物，与“创新是公司的”这一判断无关。"}, "sentence_index": 6, "correct_answer": "命脉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对明天的命脉充满信心。", "explanation": "这里应该用〈前景〉。命脉指事物存续的关键，不用来指未来的发展状况。"}, {"text": "他的命脉已经六十岁了。", "explanation": "这里应该用〈年龄〉。命脉指事物存续的关键，不用来说人的岁数。"}, {"text": "这所学校的命脉有三层楼高。", "explanation": "这里应该用〈高度〉。命脉指事物存续的关键，不用来说事物的高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家饭馆的一双命脉是老顾客。", "corrected_sentence": "这家饭馆的一条命脉是老顾客。", "error_description": "量词错误：“命脉”的正确量词是〈条〉，〈双〉用于成对的东西。应改为“一条命脉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "网络是现代生活的一只命脉。", "corrected_sentence": "网络是现代生活的一条命脉。", "error_description": "量词错误：“命脉”的正确量词是〈条〉，〈只〉用于动物或成对物品之一。应改为“一条命脉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
