INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26386, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以省水的。", "primary_collocate": null, "pronunciation": "jié shuǐ xíng", "ipa": "tɕjɛ˧˥ ʂweɪ˨˩ ɕiŋ˧˥", "syllable_count": 3, "sentences": [{"text": "这是一台节水型洗衣机。", "target_word": "节水型", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想买节水型的马桶。", "target_word": "节水型", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校换上了节水型水龙头。", "target_word": "节水型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "节水型花洒洗澡不用很多水。", "target_word": "节水型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们家用的全是节水型设备。", "target_word": "节水型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种节水型喷头能省一半水。", "target_word": "节水型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天缺水，大家都用节水型产品。", "target_word": "节水型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里的节水型灌溉系统很先进。", "target_word": "节水型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请选节水型的，这样水费会少一点。", "target_word": "节水型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场用上了节水型喷灌方法。", "target_word": "节水型", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "用起来可以省水的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09b47580-90f5-4a9a-ab97-6f640ec498d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26386, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "节水型", "is_correct": true, "explanation": "正确。节水型指能省水的，修饰洗衣机，与句意相合。"}, {"text": "防晒型", "is_correct": false, "explanation": "搭配：“防晒”多指人或皮肤，不能修饰洗衣机。"}, {"text": "食用型", "is_correct": false, "explanation": "语义：食用指可以吃，洗衣机不能食用，句意不通。"}, {"text": "耐旱型", "is_correct": false, "explanation": "搭配：“耐旱”多用于植物或作物，不修饰洗衣机。"}], "explanations": {"节水型": "正确。节水型指能省水的，修饰洗衣机，与句意相合。", "防晒型": "搭配：“防晒”多指人或皮肤，不能修饰洗衣机。", "食用型": "语义：食用指可以吃，洗衣机不能食用，句意不通。", "耐旱型": "搭配：“耐旱”多用于植物或作物，不修饰洗衣机。"}, "sentence_index": 0, "correct_answer": "节水型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台节水型台灯会根据光线自动调节亮度。", "explanation": "这里应该用〈智能型〉。节水型说的是省水，说能按光线自动调节要用〈智能型〉。"}, {"text": "这只节水型行李箱用了十年还很结实。", "explanation": "这里应该用〈耐用型〉。节水型强调省水，说行李箱经久结实要用〈耐用型〉。"}, {"text": "这款节水型面霜适合敏感肌。", "explanation": "这里应该用〈温和型〉。节水型说的是省水，说产品对皮肤刺激小要用〈温和型〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "节水型", "is_correct": true, "explanation": "正确。节水型指能省水的，修饰产品，与“夏天缺水”的语境相合。"}, {"text": "耗水型", "is_correct": false, "explanation": "语义：耗水型指耗水多，夏天缺水时大家不会选用，与语境相反。"}, {"text": "防冻型", "is_correct": false, "explanation": "语义：防冻是为了冬季低温，夏天缺水的语境下不需要防冻。"}, {"text": "耐寒型", "is_correct": false, "explanation": "搭配：“耐寒”多用于人、动植物，一般不说“耐寒型产品”。"}], "explanations": {"节水型": "正确。节水型指能省水的，修饰产品，与“夏天缺水”的语境相合。", "耗水型": "语义：耗水型指耗水多，夏天缺水时大家不会选用，与语境相反。", "防冻型": "语义：防冻是为了冬季低温，夏天缺水的语境下不需要防冻。", "耐寒型": "搭配：“耐寒”多用于人、动植物，一般不说“耐寒型产品”。"}, "sentence_index": 6, "correct_answer": "节水型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台节水型吸尘器吸得很干净。", "explanation": "这里应该用〈高效型〉。节水型说的是节约用水，说吸尘效果要用〈高效型〉。"}, {"text": "这台节水型冰箱运行时几乎没有声音。", "explanation": "这里应该用〈静音型〉。节水型不说噪音，描述运行安静要用〈静音型〉。"}, {"text": "这台节水型电动车很轻便。", "explanation": "这里应该用〈轻便型〉。节水型不说携带或行驶是否方便，要用〈轻便型〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台很节水型洗衣机真省水。", "corrected_sentence": "这台节水型洗衣机真省水。", "error_description": "错误形式：“很节水型洗衣机”；正确形式：“节水型洗衣机”。“节水型”作定语修饰名词，前面不能加程度副词“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家的马桶很节水型的，冲一次水只用一点点。", "corrected_sentence": "我家的马桶是节水型的，冲一次水只用一点点。", "error_description": "错误形式：“很节水型的”；正确形式：“是节水型的”。“节水型”是区别词，不能直接受程度副词“很”修饰，作谓语时要用“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26388, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "研究", "is_correct": false, "explanation": "“研究”指深入探讨，与“改进旧事物”并不构成对立，不是反义词。"}, {"text": "守旧", "is_correct": true, "explanation": "“守旧”指拘守旧的做法、不肯改变，与“革新”主张正相反，是反义词。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”指共同议论问题，与“革新”没有对立关系。"}, {"text": "播放", "is_correct": false, "explanation": "“播放”指通过设备放送声音或影像，与“革新”没有对立关系。"}], "correct_answer": "守旧", "explanations": {"研究": "“研究”指深入探讨，与“改进旧事物”并不构成对立，不是反义词。", "守旧": "“守旧”指拘守旧的做法、不肯改变，与“革新”主张正相反，是反义词。", "讨论": "“讨论”指共同议论问题，与“革新”没有对立关系。", "播放": "“播放”指通过设备放送声音或影像，与“革新”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26388, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "跳舞", "is_correct": false, "explanation": "“跳舞”指随音乐舞动身体，与“革新”没有对立关系，不是反义词。"}, {"text": "守旧", "is_correct": true, "explanation": "“守旧”指拘守旧的做法、不肯改变，与“革新”主张正相反，是反义词。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指随意走动以放松，与“革新”没有对立关系，不是反义词。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”指入睡休息，与“革新”没有对立关系，不是反义词。"}], "correct_answer": "守旧", "explanations": {"跳舞": "“跳舞”指随音乐舞动身体，与“革新”没有对立关系，不是反义词。", "守旧": "“守旧”指拘守旧的做法、不肯改变，与“革新”主张正相反，是反义词。", "散步": "“散步”指随意走动以放松，与“革新”没有对立关系，不是反义词。", "睡觉": "“睡觉”指入睡休息，与“革新”没有对立关系，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26388, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把旧的东西变得更好。", "primary_collocate": null, "pronunciation": "gé xīn", "ipa": "kɤ˧˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "工程师想革新这台旧机器。", "target_word": "革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们决定革新学校的教学方法。", "target_word": "革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板打算革新店里的旧设备。", "target_word": "革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们革新了生产的老办法。", "target_word": "革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师一直在革新自己的课堂。", "target_word": "革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要革新落后的管理制度。", "target_word": "革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把旧工艺革新了一遍。", "target_word": "革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民革新种地的方法，粮食多了。", "target_word": "革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家企业计划革新多年未变的生产流程。", "target_word": "革新", "complexity_tier": "T3", "furigana": "zhè jiā qǐyè jìhuà gé xīn duō nián wèi biàn de shēngchǎn liúchéng", "sentence_source": "generated"}, {"text": "厂里正在革新老式的机器。", "target_word": "革新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "革新者", "label": "派生"}], "register": "书面语", "sense_fingerprint": "改进旧的设备、方法或制度，使之更好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fc57a-06de-4b32-86c6-7fa8c22896d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26388, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喂", "is_correct": false, "explanation": "配价：“喂”的对象须是有生命的动物或人，不能带“机器”作宾语。"}, {"text": "革新", "is_correct": true, "explanation": "“革新”指把旧机器改进得更好，与“工程师”“旧机器”的语境相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，机器不能被吃，句子无法表达合理的意思。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：“欺骗”要求有意识的对象，机器不能被欺骗，与“工程师想……”的意图不通。"}], "explanations": {"喂": "配价：“喂”的对象须是有生命的动物或人，不能带“机器”作宾语。", "革新": "“革新”指把旧机器改进得更好，与“工程师”“旧机器”的语境相合。", "吃": "语义：“吃”指进食，机器不能被吃，句子无法表达合理的意思。", "欺骗": "语义：“欺骗”要求有意识的对象，机器不能被欺骗，与“工程师想……”的意图不通。"}, "sentence_index": 0, "correct_answer": "革新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们革新了那个走丢的孩子。", "explanation": "这里应该用〈找回〉。“革新”指把旧的设备、方法、制度变得更好，不用于人。"}, {"text": "这家厂革新了一套新的生产线。", "explanation": "这里应该用〈组装〉。“革新”指把旧的东西变得更好，不能用于制造新的生产线。"}, {"text": "一场大火革新了那座古老的木桥。", "explanation": "这里应该用〈破坏〉。“革新”是人主动把旧东西变得更好，不能指火灾造成的损坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26388, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拼写", "is_correct": false, "explanation": "语义：“拼写”指按字母写出词语，与“旧工艺”不搭，句意不通。"}, {"text": "煎", "is_correct": false, "explanation": "语义：“煎”指用油加热食物，旧工艺不能被煎，句意荒谬。"}, {"text": "革新", "is_correct": true, "explanation": "“革新”指把旧工艺改进一遍，正是这里要表达的意思。"}, {"text": "忽悠", "is_correct": false, "explanation": "语域：“忽悠”属口语，含欺骗义，且不能指对工艺作改进，与书面语境不符。"}], "explanations": {"拼写": "语义：“拼写”指按字母写出词语，与“旧工艺”不搭，句意不通。", "煎": "语义：“煎”指用油加热食物，旧工艺不能被煎，句意荒谬。", "革新": "“革新”指把旧工艺改进一遍，正是这里要表达的意思。", "忽悠": "语域：“忽悠”属口语，含欺骗义，且不能指对工艺作改进，与书面语境不符。"}, "sentence_index": 6, "correct_answer": "革新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厂里正在革新老式的天气。", "explanation": "这里应该用〈改变〉。“革新”只用于把旧设备、方法、制度变得更好，不能用来改造天气。"}, {"text": "厂里正在革新老式的朋友。", "explanation": "这里应该用〈培养〉。“革新”只用于把旧设备、方法、制度变得更好，不用于培养或改造人。"}, {"text": "厂里正在革新老式的天空。", "explanation": "这里应该用〈清理〉。“革新”只用于把旧设备、方法、制度变得更好，不能用于清理天空这样的自然环境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工程师不想把革新这台旧机器。", "corrected_sentence": "工程师不想革新这台旧机器。", "error_description": "结构错误：“革新”是及物动词，可直接带宾语“这台旧机器”，不需要“把”；“把革新这台旧机器”语序不通，应说“不想革新这台旧机器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厂里把老式机器革新。", "corrected_sentence": "厂里把老式机器革新了一遍。", "error_description": "补语缺失：“把”字句中动词后要带补语或“了”，应为“革新了一遍”。单用“革新”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
