INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26390, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变得不干净", "primary_collocate": null, "pronunciation": "shòu wū", "ipa": "ʂou˥˩ u˥", "syllable_count": 2, "sentences": [{"text": "白衬衫一碰到泥水就受污了。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块白布放在路边，很快就受污了。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受污的墙面需要重新刷一遍。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌面上洒了油，很快就受污了。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白色的鞋子很容易受污。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白色的床单几天不洗，就受污发黄了。", "target_word": "受污", "complexity_tier": "T3", "furigana": "báisè de chuángdān jǐ tiān bù xǐ, jiù shòuwū fāhuáng le.", "sentence_source": "generated"}, {"text": "那件受污的外套该洗了。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白手套摸了煤，马上就受污了。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服受污以后，他马上拿去洗。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白雪受污后变成了灰色。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "物体表面变脏，变得不干净", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fc57a-06de-4b32-86c6-7fa8c22896d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26390, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受污", "is_correct": true, "explanation": "正确：“白衬衫一碰到泥水就受污了”指衣物表面变脏，与语境吻合。"}, {"text": "晾干", "is_correct": false, "explanation": "语义：“晾干”指变干，与“碰到泥水”后的变脏结果相反。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：“烘干”指弄干，不能表示碰到泥水后的变脏。"}, {"text": "洗净", "is_correct": false, "explanation": "搭配：“洗净”是清洁的结果，不能接在“碰到泥水就”之后表示变脏。"}], "explanations": {"受污": "正确：“白衬衫一碰到泥水就受污了”指衣物表面变脏，与语境吻合。", "晾干": "语义：“晾干”指变干，与“碰到泥水”后的变脏结果相反。", "烘干": "语义：“烘干”指弄干，不能表示碰到泥水后的变脏。", "洗净": "搭配：“洗净”是清洁的结果，不能接在“碰到泥水就”之后表示变脏。"}, "sentence_index": 0, "correct_answer": "受污"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他唱了一天歌，嗓子都受污了。", "explanation": "这里应该用〈沙哑〉。受污指物体变得不干净，不用来说嗓子的变化。"}, {"text": "他看到成绩后，脸色受污了。", "explanation": "这里应该用〈发白〉或〈难看〉。受污指变得不干净，不用来说脸色的变化。"}, {"text": "这门课的学分很快就受污了。", "explanation": "这里应该用〈增减〉。受污指物体变得不干净，不用来说学分的增减。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26390, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受污", "is_correct": true, "explanation": "正确：“那件受污的外套该洗了”指外套变脏，与“该洗了”的语境吻合。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”是人身体发热的症状，不能修饰外套，句意不通。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：“甜蜜”形容滋味或感情，不能修饰外套，句意不通。"}, {"text": "打折", "is_correct": false, "explanation": "语义：“打折”是买卖中的降价，不能修饰外套，句子无法成立。"}], "explanations": {"受污": "正确：“那件受污的外套该洗了”指外套变脏，与“该洗了”的语境吻合。", "发烧": "语义：“发烧”是人身体发热的症状，不能修饰外套，句意不通。", "甜蜜": "语义：“甜蜜”形容滋味或感情，不能修饰外套，句意不通。", "打折": "语义：“打折”是买卖中的降价，不能修饰外套，句子无法成立。"}, "sentence_index": 6, "correct_answer": "受污"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个学生的成绩受污了。", "explanation": "这里应该用〈下降〉。受污指变得不干净，不用来说成绩的变化。"}, {"text": "这道题的答案很快就受污了。", "explanation": "这里应该用〈出错〉。受污指变得不干净，不用来说答案的对错。"}, {"text": "这台机器用了十年，性能已经受污了。", "explanation": "这里应该用〈衰退〉。受污指变得不干净，不用来说性能的衰退。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26390, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这双白鞋子一下雨就受污着。", "corrected_sentence": "这双白鞋子一下雨就受污了。", "error_description": "体标错误：“受污”指变脏这一已经发生的结果，应说“受污了”，不能用“着”表示持续。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26390, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件浅色外套穿了几天就把受污了。", "corrected_sentence": "这件浅色外套穿了几天就受污了。", "error_description": "结构错误：“受污”是不带宾语的变化动词，不能放在“把”字之后；应说“就受污了”，不说“就把受污了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26392, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减少", "is_correct": true, "explanation": "减少与增长相反，指数量或规模变小。"}, {"text": "思考", "is_correct": false, "explanation": "与增长没有反义关系，思考指用脑子考虑问题。"}, {"text": "散步", "is_correct": false, "explanation": "与增长没有反义关系，散步指随意地走一走。"}, {"text": "研究", "is_correct": false, "explanation": "与增长没有反义关系，研究指深入探讨问题。"}], "correct_answer": "减少", "explanations": {"减少": "减少与增长相反，指数量或规模变小。", "思考": "与增长没有反义关系，思考指用脑子考虑问题。", "散步": "与增长没有反义关系，散步指随意地走一走。", "研究": "与增长没有反义关系，研究指深入探讨问题。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26392, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减少", "is_correct": true, "explanation": "减少与增长相反，指数量或规模变小。"}, {"text": "唱歌", "is_correct": false, "explanation": "与增长没有反义关系，唱歌指用声音表达乐曲。"}, {"text": "跳舞", "is_correct": false, "explanation": "与增长没有反义关系，跳舞指随着音乐做动作。"}, {"text": "写作", "is_correct": false, "explanation": "与增长没有反义关系，写作指用文字表达思想。"}], "correct_answer": "减少", "explanations": {"减少": "减少与增长相反，指数量或规模变小。", "唱歌": "与增长没有反义关系，唱歌指用声音表达乐曲。", "跳舞": "与增长没有反义关系，跳舞指随着音乐做动作。", "写作": "与增长没有反义关系，写作指用文字表达思想。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26392, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西变多或变大。", "primary_collocate": null, "pronunciation": "zēng zhǎng", "ipa": "tsəŋ˥ ʈʂaŋ˨˩", "syllable_count": 2, "sentences": [{"text": "今年公司的收入增长了很多。", "target_word": "增长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市的人口每年都在增长。", "target_word": "增长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，中国的经济增长很快。", "target_word": "增长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读了很多书，知识不断增长。", "target_word": "增长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买车的人越来越多，汽车数量快速增长。", "target_word": "增长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变热，冷饮的销量增长了一倍。", "target_word": "增长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的年龄在增长，也越来越懂事。", "target_word": "增长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作几年后，他的经验增长了不少。", "target_word": "增长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的出口增长了百分之十。", "target_word": "增长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人口增长太快，会带来很多问题。", "target_word": "增长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "增长了", "label": "体标（了）"}, {"form": "增长着", "label": "体标（着）"}, {"form": "增长率", "label": "复合"}], "register": "中性", "sense_fingerprint": "数量、规模逐渐变大变多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd4466d2-ac6f-4a40-a8e9-8cb0ae81f61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26392, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缩短", "is_correct": false, "explanation": "搭配：“缩短”多用于时间、距离，不用于描述收入。"}, {"text": "增长", "is_correct": true, "explanation": "增长指数量或规模变大，与收入增加很多的语境相符。"}, {"text": "变轻", "is_correct": false, "explanation": "语义：变轻说的是重量，与收入的变化无关。"}, {"text": "降温", "is_correct": false, "explanation": "语义：降温说的是温度下降，不能用来形容收入。"}], "explanations": {"缩短": "搭配：“缩短”多用于时间、距离，不用于描述收入。", "增长": "增长指数量或规模变大，与收入增加很多的语境相符。", "变轻": "语义：变轻说的是重量，与收入的变化无关。", "降温": "语义：降温说的是温度下降，不能用来形容收入。"}, "sentence_index": 0, "correct_answer": "增长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小树在山坡上增长。", "explanation": "这里应该用〈生长〉。植物、生物的长大要用〈生长〉，增长多用于数量和规模。"}, {"text": "我用胶水把桌腿增长了。", "explanation": "这里应该用〈加长〉。人为使物体变长要用〈加长〉，「增长」指数量或规模的扩大，不用于桌腿。"}, {"text": "班里增长了两名新同学。", "explanation": "这里应该用〈增加〉。具体人数变多要用〈增加〉，增长多用于比率或规模。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降低", "is_correct": false, "explanation": "搭配：“降低”多用于价格、温度、水平，一般不用来说年龄。"}, {"text": "增长", "is_correct": true, "explanation": "增长指年龄逐渐变大，与越来越懂事的语境相符。"}, {"text": "缩小", "is_correct": false, "explanation": "语义：缩小表示变少，与“越来越懂事”的语境相矛盾。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：冷却说的是温度下降，不能用来形容年龄。"}], "explanations": {"降低": "搭配：“降低”多用于价格、温度、水平，一般不用来说年龄。", "增长": "增长指年龄逐渐变大，与越来越懂事的语境相符。", "缩小": "语义：缩小表示变少，与“越来越懂事”的语境相矛盾。", "冷却": "语义：冷却说的是温度下降，不能用来形容年龄。"}, "sentence_index": 6, "correct_answer": "增长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校增长了安全教育。", "explanation": "这里应该用〈加强〉。安全教育的力度要说〈加强〉，「增长」多指数量或规模的扩大。"}, {"text": "他一口气就增长了半碗饭。", "explanation": "这里应该用〈吃〉。吃下食物要用〈吃〉，「增长」指数量或规模的变大，不能说“增长了半碗饭”。"}, {"text": "屋里增长了暖意。", "explanation": "这里应该用〈增添〉。抽象的感受如暖意、乐趣要用〈增添〉，增长一般用于数量和规模。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂的产量增长了一个倍。", "corrected_sentence": "这家工厂的产量增长了一倍。", "error_description": "量词错误：“倍”本身就是量词，前面不能再加“个”。错误形式“增长了一个倍”，正确形式“增长了一倍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个地区的人口增长的很快。", "corrected_sentence": "这个地区的人口增长得很快。", "error_description": "补语标记错误：程度补语应用“得”，不能用“的”。错误形式“增长的很快”，正确形式“增长得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
