INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26394, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "水没有了，河底都露出来了。", "primary_collocate": null, "pronunciation": "gān hé", "ipa": "kan˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "河干涸，底下全是石头。", "target_word": "干涸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好几个月没下雨，大河干涸了。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖水干涸后，湖底裂成了一块一块。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在干涸的河床上捡石头。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水干涸，船只好停在河底的泥里。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水库干涸了，河底的老桥露了出来。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说那条河以前干涸过，现在水很多。", "target_word": "干涸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太干，小溪很快就干涸了，只剩石头。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看，那条河干涸了，连小鱼都看不见。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河干涸以后，人们可以走到河对面。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "干涸了", "label": "体标（了）"}, {"form": "干涸过", "label": "体标（过）"}, {"form": "乾涸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "河湖的水没有了，河底、湖底露了出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e30e707f-e868-41d3-92c0-29d881cfc989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26394, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干涸", "is_correct": true, "explanation": "正确：「底下全是石头」说明水没有了，河底露出来，干涸最合适。"}, {"text": "燃烧", "is_correct": false, "explanation": "语义：“燃烧”指物体着火，“河燃烧”不通，与河底露出石头无关。"}, {"text": "冒烟", "is_correct": false, "explanation": "语义：“冒烟”指冒出烟雾，“河冒烟”不成立，与河底露出石头无关。"}, {"text": "漂浮", "is_correct": false, "explanation": "搭配：「漂浮」多用于物体浮在水面上，不用来说河「漂浮」。"}], "explanations": {"干涸": "正确：「底下全是石头」说明水没有了，河底露出来，干涸最合适。", "燃烧": "语义：“燃烧”指物体着火，“河燃烧”不通，与河底露出石头无关。", "冒烟": "语义：“冒烟”指冒出烟雾，“河冒烟”不成立，与河底露出石头无关。", "漂浮": "搭配：「漂浮」多用于物体浮在水面上，不用来说河「漂浮」。"}, "sentence_index": 0, "correct_answer": "干涸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几天空气很干涸，嘴唇都裂了。", "explanation": "这里应该用〈干燥〉。干燥说空气、物体缺少水分；干涸只说河湖、水井等水体没有水。"}, {"text": "他的笑容干涸了，大家都觉得不对劲。", "explanation": "这里应该用〈消失〉。笑容等表情不说干涸；干涸只指水分完全消失。"}, {"text": "这棵树的叶子干涸了，风一吹就掉。", "explanation": "这里应该用〈干枯〉。草木失去水分用干枯；干涸只说水体没有水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26394, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干涸", "is_correct": true, "explanation": "正确：「以前」与「现在水很多」形成对比，说明那条河以前没有水，干涸最合适。"}, {"text": "沸腾", "is_correct": false, "explanation": "搭配：「沸腾」指液体受热翻滚，不用来形容河流「以前沸腾过」。"}, {"text": "着火", "is_correct": false, "explanation": "语义：“着火”指物体燃烧，“那条河以前着火过”不通，与“现在水很多”的对比也无关。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：「凝固」指液体变成固体，与「现在水很多」的对比不符，河流不能凝固。"}], "explanations": {"干涸": "正确：「以前」与「现在水很多」形成对比，说明那条河以前没有水，干涸最合适。", "沸腾": "搭配：「沸腾」指液体受热翻滚，不用来形容河流「以前沸腾过」。", "着火": "语义：“着火”指物体燃烧，“那条河以前着火过”不通，与“现在水很多”的对比也无关。", "凝固": "语义：「凝固」指液体变成固体，与「现在水很多」的对比不符，河流不能凝固。"}, "sentence_index": 6, "correct_answer": "干涸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场大雨下了一夜，早上终于干涸了。", "explanation": "这里应该用〈停〉。雨停说降水结束；干涸只用于河、湖、水井等水体没有水，不用于雨。"}, {"text": "汽车的燃料已经干涸了，只能停在路边。", "explanation": "这里应该用〈耗尽〉。燃料、体力等消耗完用耗尽；干涸只用于水体。"}, {"text": "这位老人的视力干涸了，看报纸很吃力。", "explanation": "这里应该用〈减退〉。视力等能力逐渐变弱用减退；干涸只说水分完全消失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26394, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几天没下雨，那条小沟很快就把干涸了。", "corrected_sentence": "这几天没下雨，那条小沟很快就干涸了。", "error_description": "错误在于多用了「把」。干涸是不及物动词，不能带「把」字结构，应说「很快就干涸了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26394, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条老井去年就干涸了。", "corrected_sentence": "这口老井去年就干涸了。", "error_description": "量词错误：「井」应搭配量词「口」，不能用「条」。正确说法是「这口老井」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26396, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "肮脏", "is_correct": true, "explanation": "反义：清洁指干净，肮脏指脏，二者意思相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮说外貌好看，与“清洁”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮说光线或颜色，与“清洁”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静说声音或环境，与“清洁”没有反义关系。"}], "correct_answer": "肮脏", "explanations": {"肮脏": "反义：清洁指干净，肮脏指脏，二者意思相反。", "漂亮": "漂亮说外貌好看，与“清洁”没有反义关系。", "明亮": "明亮说光线或颜色，与“清洁”没有反义关系。", "安静": "安静说声音或环境，与“清洁”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26396, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脏", "is_correct": true, "explanation": "反义：清洁指干净，脏指有污垢，二者意思相反。"}, {"text": "宽敞", "is_correct": false, "explanation": "宽敞说空间大，与“清洁”没有反义关系。"}, {"text": "寂静", "is_correct": false, "explanation": "寂静说没有声音，与“清洁”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹说人多声杂，与“清洁”没有反义关系。"}], "correct_answer": "脏", "explanations": {"脏": "反义：清洁指干净，脏指有污垢，二者意思相反。", "宽敞": "宽敞说空间大，与“清洁”没有反义关系。", "寂静": "寂静说没有声音，与“清洁”没有反义关系。", "热闹": "热闹说人多声杂，与“清洁”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26396, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很干净，没有脏东西。", "primary_collocate": null, "pronunciation": "qīng jié", "ipa": "tɕʰiŋ˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "这家饭馆的厨房很清洁。", "target_word": "清洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的房间必须保持清洁。", "target_word": "清洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里的环境非常清洁。", "target_word": "清洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店的房间很清洁，住着很舒服。", "target_word": "清洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭前，手要保持清洁。", "target_word": "清洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的衣服总是很清洁。", "target_word": "清洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的街道又宽又清洁。", "target_word": "清洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套厨具很清洁，可以用了。", "target_word": "清洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的教室明亮而清洁。", "target_word": "清洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子不太清洁，请换一个。", "target_word": "清洁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "清洁工", "label": "复合"}, {"form": "清洁剂", "label": "复合"}, {"form": "清潔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "干净没有脏东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e685e353-0b99-4f1c-ae5d-499665025313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "清洁", "is_correct": true, "explanation": "清洁：很干净，没有脏东西，适合形容饭馆的厨房。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，不用来形容厨房，这句话说不通。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”多用于刀剑等，不用来形容厨房。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”修饰声音，不修饰厨房。"}], "explanations": {"清洁": "清洁：很干净，没有脏东西，适合形容饭馆的厨房。", "甜": "语义：“甜”说味道，不用来形容厨房，这句话说不通。", "锋利": "搭配：“锋利”多用于刀剑等，不用来形容厨房。", "响亮": "搭配：“响亮”修饰声音，不修饰厨房。"}, "sentence_index": 0, "correct_answer": "清洁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的解释很清洁，我完全听懂了。", "explanation": "这里应该用〈清楚〉。清洁指干净、没有脏东西，说解释明白要用清楚。"}, {"text": "鸟儿的叫声很清洁。", "explanation": "这里应该用〈清脆〉。清洁只指干净，形容声音清脆要用清脆。"}, {"text": "他喝了咖啡，头脑很清洁。", "explanation": "这里应该用〈清醒〉。清洁不用来形容头脑，头脑清楚要用清醒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "清洁", "is_correct": true, "explanation": "清洁：很干净，没有脏东西，适合形容街道。"}, {"text": "脆", "is_correct": false, "explanation": "语义：“脆”说食物的口感，不用来形容街道。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”说味道，不用来形容街道。"}, {"text": "嘹亮", "is_correct": false, "explanation": "搭配：“嘹亮”形容声音，不修饰街道。"}], "explanations": {"清洁": "清洁：很干净，没有脏东西，适合形容街道。", "脆": "语义：“脆”说食物的口感，不用来形容街道。", "辣": "语义：“辣”说味道，不用来形容街道。", "嘹亮": "搭配：“嘹亮”形容声音，不修饰街道。"}, "sentence_index": 6, "correct_answer": "清洁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个播音员的声音很清洁。", "explanation": "这里应该用〈清晰〉。清洁只说物体干净，不指声音清楚。"}, {"text": "这个孩子的歌声很清洁。", "explanation": "这里应该用〈清亮〉。清洁不形容声音，歌声明亮要用清亮。"}, {"text": "这道菜的口味很清洁。", "explanation": "这里应该用〈清淡〉。清洁不形容口味，口味淡要用清淡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们喜欢清洁地厨房。", "corrected_sentence": "我们喜欢清洁的厨房。", "error_description": "“清洁”作定语修饰名词，应用“的”，不用“地”（“地”用于动词前）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厨房很清洁地，大家都喜欢。", "corrected_sentence": "厨房很清洁，大家都喜欢。", "error_description": "“清洁”作谓语时后面不能加“地”；“地”只用在动词前作状语，应删去“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
