INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26400, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示“是不是、有没有”的疑问，多用于从句，相当于英语的 whether。", "primary_collocate": null, "pronunciation": "shì fǒu", "ipa": "ʂɻ̩˥˩ fou̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "请告诉我你明天是否有时间。", "target_word": "是否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不知道他是否已经到家了。", "target_word": "是否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问大家是否都做完了作业。", "target_word": "是否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你是否喜欢这个城市？", "target_word": "是否", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生要检查你是否发烧了。", "target_word": "是否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不确定这个办法是否可行。", "target_word": "是否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想知道这家店是否开门。", "target_word": "是否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你看一下，窗户是否关好了。", "target_word": "是否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事是否重要，要看你怎么想。", "target_word": "是否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都在讨论明天是否会下雨。", "target_word": "是否", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "表示「是不是、有没有」的疑问，常用于从句，相当于「whether」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c41e43-d819-4200-99d8-f4259434702f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26400, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "是否", "is_correct": true, "explanation": "正确。“是否”用于间接问句，表示“是不是、有没有”。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已完成，与“明天”的将来时间矛盾。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去的经历，与“明天”冲突。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作进行中，不能修饰“有时间”，与“明天”也不合。"}], "explanations": {"是否": "正确。“是否”用于间接问句，表示“是不是、有没有”。", "已经": "语义：“已经”表示已完成，与“明天”的将来时间矛盾。", "曾经": "语义：“曾经”指过去的经历，与“明天”冲突。", "正在": "搭配：“正在”表示动作进行中，不能修饰“有时间”，与“明天”也不合。"}, "sentence_index": 0, "correct_answer": "是否"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请你是否坐下。", "explanation": "这里不能用〈是否〉表示请求，应说“请你坐下”。“是否”只用于询问是非，不用于请求或命令。"}, {"text": "我是否很清楚这件事。", "explanation": "这里应该用〈确实〉。陈述自己确定的情况要说“确实”或直接说“很清楚”，“是否”表示不确定或提问。"}, {"text": "A：你去吗？B：是否，我去。", "explanation": "这里应该用〈是〉。回答是非问题要说“是”，“是否”是提问用的词，不能用来回答。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26400, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "是否", "is_correct": true, "explanation": "正确。“是否”引出间接问句，与“想知道”相符。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，与“想知道”的疑问语境不符。"}, {"text": "偏偏", "is_correct": false, "explanation": "搭配：“偏偏”表示故意或与预期相反，不能用来引出“想知道”的内容。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示催促快做，与“想知道这家店……开门”不符。"}], "explanations": {"是否": "正确。“是否”引出间接问句，与“想知道”相符。", "竟然": "语义：“竟然”表示出乎意料，与“想知道”的疑问语境不符。", "偏偏": "搭配：“偏偏”表示故意或与预期相反，不能用来引出“想知道”的内容。", "赶紧": "语义：“赶紧”表示催促快做，与“想知道这家店……开门”不符。"}, "sentence_index": 6, "correct_answer": "是否"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你是否真漂亮啊！", "explanation": "这里应该用〈真〉。感叹句不用“是否”，要说“你真漂亮啊”。"}, {"text": "你是否什么时候来？", "explanation": "这里应该用〈什么时候〉。句中已有疑问词“什么时候”，不能再加“是否”，直接说“你什么时候来？”。"}, {"text": "我们明天去，是否？", "explanation": "这里应该用〈对吧〉。附加问句用“对吧”或“是不是”，不用“是否”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不清楚他是否愿意参加比赛吗。", "corrected_sentence": "我不清楚他是否愿意参加比赛。", "error_description": "「是否」引出的间接问句中不能再用“吗”，“吗”只用于直接问句。应说“我不清楚他是否愿意参加比赛”，不能再加“吗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个方案很是否可行，我们还要再讨论。", "corrected_sentence": "这个方案是否可行，我们还要再讨论。", "error_description": "「是否」前面不能用程度副词“很”修饰。应说“这个方案是否可行”，不能说“这个方案很是否可行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
