INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26410, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "感受和判断美丽的东西。", "primary_collocate": null, "pronunciation": "shěn měi", "ipa": "ʂən˨˩ meɪ˨˩", "syllable_count": 2, "sentences": [{"text": "孩子也会审美，他们喜欢漂亮的颜色。", "target_word": "审美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在博物馆里，我们可以慢慢学会审美。", "target_word": "审美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都有自己审美的方式。", "target_word": "审美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们不能只用一个标准去审美。", "target_word": "审美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位画家教我们怎么审美。", "target_word": "审美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去看画展，是学习审美的好机会。", "target_word": "审美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行的时候，我们也可以学习审美。", "target_word": "审美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让学生看着图片审美，再说说感受。", "target_word": "审美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就爱审美，常常一个人看花看云。", "target_word": "审美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家用不同的眼光审美，看法自然不同。", "target_word": "审美", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "审美疲劳", "label": "复合"}], "register": "通用", "sense_fingerprint": "感受并判断事物是否美", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09b47580-90f5-4a9a-ab97-6f640ec498d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26410, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "审美", "is_correct": true, "explanation": "正确：“会审美”指能感受并判断事物美不美，与后文“喜欢漂亮的颜色”相呼应。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业”指丢掉工作，与“孩子”的语境不符，句子说不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”是成年人的事，与“孩子也会”的语境相矛盾。"}, {"text": "签订", "is_correct": false, "explanation": "搭配：“签订”要与合同、协议搭配，不能用于“孩子也会……”。"}], "explanations": {"审美": "正确：“会审美”指能感受并判断事物美不美，与后文“喜欢漂亮的颜色”相呼应。", "失业": "语义：“失业”指丢掉工作，与“孩子”的语境不符，句子说不通。", "结婚": "语义：“结婚”是成年人的事，与“孩子也会”的语境相矛盾。", "签订": "搭配：“签订”要与合同、协议搭配，不能用于“孩子也会……”。"}, "sentence_index": 0, "correct_answer": "审美"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份合同需要律师仔细审美。", "explanation": "这里应该用〈审查〉。审美指感受和判断美，不用于法律上的审查。"}, {"text": "工人仔细地审美了房间的尺寸。", "explanation": "这里应该用〈测量〉。审美指感受和判断美，不用于量房间的尺寸。"}, {"text": "法官要公正地审美是非。", "explanation": "这里应该用〈判断〉。审美针对美丑，不用于判断是非对错。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "审美", "is_correct": true, "explanation": "正确：“学习审美”指旅行时学着感受和判断风景等美的事物，与语境吻合。"}, {"text": "上班", "is_correct": false, "explanation": "语义：“上班”与“旅行的时候”的场景相矛盾，句子说不通。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”与旅行的语境不合，不能这样说。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业”是丢掉工作，不能“学习失业”，与旅行语境不符。"}], "explanations": {"审美": "正确：“学习审美”指旅行时学着感受和判断风景等美的事物，与语境吻合。", "上班": "语义：“上班”与“旅行的时候”的场景相矛盾，句子说不通。", "考试": "语义：“考试”与旅行的语境不合，不能这样说。", "失业": "语义：“失业”是丢掉工作，不能“学习失业”，与旅行语境不符。"}, "sentence_index": 6, "correct_answer": "审美"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司要仔细审美员工的资料。", "explanation": "这里应该用〈审核〉。审美是感受和判断美，不用于审核资料。"}, {"text": "这位医生要尽快审美病人的病情。", "explanation": "这里应该用〈诊断〉。审美针对美的事物，不用于判断病情。"}, {"text": "专家仔细审美这幅画的真假。", "explanation": "这里应该用〈鉴定〉。审美判断的是美丑，不用于判断真假。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子很审美。", "corrected_sentence": "孩子很会审美。", "error_description": "审美是动词，不能直接受程度副词“很”修饰，应说“很会审美”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她刚才在审美了一会儿。", "corrected_sentence": "她刚才审美了一会儿。", "error_description": "“在”表示进行，与表示完成的“了”不能同时用，应说“审美了一会儿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
