INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26412, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放起来，不让别人看到。", "primary_collocate": null, "pronunciation": "cáng", "ipa": "tsʰɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "他把手机藏在包里。", "target_word": "藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我藏了一块糖。", "target_word": "藏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫把球藏在沙发下面。", "target_word": "藏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你把书藏哪儿了？", "target_word": "藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥藏着一个小盒子，不让我看。", "target_word": "藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想藏好礼物，让妈妈找不到。", "target_word": "藏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子把饼干藏在枕头下面。", "target_word": "藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小松鼠把吃的东西藏在树洞里。", "target_word": "藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到有人来，他马上把信藏到门后。", "target_word": "藏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些旧照片，奶奶藏了很多年。", "target_word": "藏", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "藏了", "label": "体标"}, {"form": "藏着", "label": "体标"}, {"form": "藏过", "label": "体标"}, {"form": "躲藏", "label": "复合"}, {"form": "隐藏", "label": "复合"}], "register": "中性", "sense_fingerprint": "藏：把东西放在别人看不到的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88438421-1dc5-4dd6-abb9-54560972ac87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26412, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "藏", "is_correct": true, "explanation": "正确：藏（cáng）表示把东西放在别人看不到的地方，与句意一致。"}, {"text": "苍", "is_correct": false, "explanation": "cāng（第一声）与 cáng 声调不同，意思是青灰色、深绿色。"}, {"text": "舱", "is_correct": false, "explanation": "cāng（第一声）与 cáng 只差声调，意思是船舱。"}, {"text": "沧", "is_correct": false, "explanation": "cāng（第一声）与 cáng 只差声调，常见于“沧海”，意思是大海。"}], "explanations": {"藏": "正确：藏（cáng）表示把东西放在别人看不到的地方，与句意一致。", "苍": "cāng（第一声）与 cáng 声调不同，意思是青灰色、深绿色。", "舱": "cāng（第一声）与 cáng 只差声调，意思是船舱。", "沧": "cāng（第一声）与 cáng 只差声调，常见于“沧海”，意思是大海。"}, "sentence_index": null, "correct_answer": "藏"}, "level_3": {"options": [{"text": "藏", "is_correct": true, "explanation": "正确：“藏在包里”表示把东西放在别人看不到的地方。"}, {"text": "吃", "is_correct": false, "explanation": "语义：手机不能被“吃”，句意不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“手机”作宾语再接“在包里”。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写，手机不能被写进包里。"}], "explanations": {"藏": "正确：“藏在包里”表示把东西放在别人看不到的地方。", "吃": "语义：手机不能被“吃”，句意不通。", "唱": "搭配：“唱”不能带“手机”作宾语再接“在包里”。", "写": "语义：“写”指书写，手机不能被写进包里。"}, "sentence_index": 0, "correct_answer": "藏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用手藏住了风。", "explanation": "这里应该用〈挡住〉。藏是隐蔽、不让人发现；风不能被藏起来，用手遮挡风要说“挡住”。"}, {"text": "这棵老树藏得很快。", "explanation": "这里应该用〈长〉。藏表示隐蔽或收存，不能用来形容树的生长；树长得快要说“长得很快”。"}, {"text": "他藏出了笑脸。", "explanation": "这里应该用〈露出〉。藏表示隐蔽，不能用来说表情显露出来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee6f3f6-09ef-4ab8-a313-672a51aeb997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26412, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "藏", "is_correct": true, "explanation": "正确：藏（cáng）表示把东西放在别人看不到的地方，与句意一致。"}, {"text": "仓", "is_correct": false, "explanation": "cāng（第一声）与 cáng 声调不同，意思是仓库。"}, {"text": "长", "is_correct": false, "explanation": "cháng（第二声）与 cáng 同调，只差声母（ch 对 c），意思是长短的长。"}, {"text": "糖", "is_correct": false, "explanation": "táng（第二声）与 cáng 同调，只差声母（t 对 c），意思是糖果。"}, {"text": "旁", "is_correct": false, "explanation": "páng（第二声）与 cáng 同调，只差声母（p 对 c），意思是旁边。"}], "explanations": {"藏": "正确：藏（cáng）表示把东西放在别人看不到的地方，与句意一致。", "仓": "cāng（第一声）与 cáng 声调不同，意思是仓库。", "长": "cháng（第二声）与 cáng 同调，只差声母（ch 对 c），意思是长短的长。", "糖": "táng（第二声）与 cáng 同调，只差声母（t 对 c），意思是糖果。", "旁": "páng（第二声）与 cáng 同调，只差声母（p 对 c），意思是旁边。"}, "sentence_index": null, "correct_answer": "藏"}, "level_3": {"options": [{"text": "藏", "is_correct": true, "explanation": "正确：“藏在枕头下面”表示把东西放在别人看不到的地方。"}, {"text": "跑", "is_correct": false, "explanation": "语义：饼干不会“跑”到枕头下面，句意不通。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿，不能用来表示放置饼干。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送”后接“到”或“给”，不说“送在枕头下面”。"}], "explanations": {"藏": "正确：“藏在枕头下面”表示把东西放在别人看不到的地方。", "跑": "语义：饼干不会“跑”到枕头下面，句意不通。", "咬": "语义：“咬”指用牙齿，不能用来表示放置饼干。", "送": "搭配：“送”后接“到”或“给”，不说“送在枕头下面”。"}, "sentence_index": 6, "correct_answer": "藏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把书藏给了我。", "explanation": "这里应该用〈送〉。藏表示隐蔽，不能用来表示把东西交给别人。"}, {"text": "他藏上了窗户。", "explanation": "这里应该用〈关上〉。藏表示隐蔽，不能用来表示关门窗。"}, {"text": "班长藏了一次班会。", "explanation": "这里应该用〈召开〉。班会要举行，不能被藏起来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee6f3f6-09ef-4ab8-a313-672a51aeb997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把信好藏了。", "corrected_sentence": "我把信藏好了。", "error_description": "补语位置错误：结果补语“好”应放在动词后面，说“藏好了”，不说“好藏了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee6f3f6-09ef-4ab8-a313-672a51aeb997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶藏了着一封旧信。", "corrected_sentence": "奶奶藏着一封旧信。", "error_description": "体标错误：“了”和“着”不能同时使用；表示持续状态只用“着”，应说“藏着”，不说“藏了着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee6f3f6-09ef-4ab8-a313-672a51aeb997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
