INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26414, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "别人尊重你，因为你很重要。", "primary_collocate": null, "pronunciation": "zūn yán", "ipa": "tsuən˥ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "大家都很尊重他，因为他活得有尊严。", "target_word": "尊严", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别人尊重你，你才能活得有尊严。", "target_word": "尊严", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子也要得到尊重，他们也有尊严。", "target_word": "尊严", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她工作很努力，大家都给她应有的尊严。", "target_word": "尊严", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师当着大家的面批评他，伤害了他的尊严。", "target_word": "尊严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说，人要先尊重自己，才有尊严。", "target_word": "尊严", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病人也有尊严，医生要尊重他们。", "target_word": "尊严", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不求别人帮忙，是为了保持自己的尊严。", "target_word": "尊严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "穷人也有尊严，我们不能看不起他们。", "target_word": "尊严", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人坚持自己付钱，因为这样觉得有尊严。", "target_word": "尊严", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人格尊严", "label": "复合"}, {"form": "尊嚴", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人因被他人尊重而拥有的体面与价值感", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09b47580-90f5-4a9a-ab97-6f640ec498d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26414, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尊严", "is_correct": true, "explanation": "正确。“活得有尊严”指因被尊重而拥有的体面与价值感，与句意相合。"}, {"text": "电压", "is_correct": false, "explanation": "语义：电压是电学概念，与人被尊重的感受无关。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重说的是身体重量，与“活得有”的价值感无关。"}, {"text": "产量", "is_correct": false, "explanation": "搭配：产量只说生产数量，不与“活得有”搭配。"}], "explanations": {"尊严": "正确。“活得有尊严”指因被尊重而拥有的体面与价值感，与句意相合。", "电压": "语义：电压是电学概念，与人被尊重的感受无关。", "体重": "语义：体重说的是身体重量，与“活得有”的价值感无关。", "产量": "搭配：产量只说生产数量，不与“活得有”搭配。"}, "sentence_index": 0, "correct_answer": "尊严"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都要走很远的尊严去上班。", "explanation": "这里应该用〈路〉。尊严指被他人尊重的价值，不能用来说路程，说“走很远的路”要用〈路〉。"}, {"text": "这张桌子的尊严很结实。", "explanation": "这里应该用〈质地〉。尊严指被他人尊重的价值，不能说物品的材质，说桌子结实要用〈质地〉。"}, {"text": "今天的尊严很好，适合出去玩。", "explanation": "这里应该用〈天气〉。尊严指被尊重的价值，不能用来描述天气，说今天的天气要用〈天气〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尊严", "is_correct": true, "explanation": "正确。“病人也有尊严”指病人同样值得尊重的体面，与“医生要尊重他们”相合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“病人也有价格”不成立，价格不与“有”的人身价值搭配。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄与病人是否值得尊重无关，句意不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是生理指标，与“医生要尊重他们”的语境不符。"}], "explanations": {"尊严": "正确。“病人也有尊严”指病人同样值得尊重的体面，与“医生要尊重他们”相合。", "价格": "搭配：“病人也有价格”不成立，价格不与“有”的人身价值搭配。", "年龄": "语义：年龄与病人是否值得尊重无关，句意不通。", "体温": "语义：体温是生理指标，与“医生要尊重他们”的语境不符。"}, "sentence_index": 6, "correct_answer": "尊严"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的尊严已经三十岁了。", "explanation": "这里应该用〈年龄〉。尊严指被他人尊重的价值，不能用来计算岁数，说年纪要用〈年龄〉。"}, {"text": "这件衣服是尊严的。", "explanation": "这里应该用〈颜色〉。尊严不能用来说颜色，描述衣服是什么颜色要用〈颜色〉。"}, {"text": "这道菜的尊严很咸。", "explanation": "这里应该用〈口味〉。尊严不能用来形容味道，说菜咸淡要用〈口味〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她很尊严，大家都愿意帮她。", "corrected_sentence": "她很有尊严，大家都愿意帮她。", "error_description": "错误形式：“很尊严”；正确形式：“很有尊严”。尊严是名词，不能直接受“很”修饰，需要加动词“有”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不求别人帮忙，是为了维护一个尊严。", "corrected_sentence": "他不求别人帮忙，是为了维护自己的尊严。", "error_description": "错误形式：“一个尊严”；正确形式：“自己的尊严”。尊严是抽象名词，不宜用个体量词“个”计量，应说“自己的尊严”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
