INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26418, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把树苗放进土里，让它长大。", "primary_collocate": null, "pronunciation": "zhòng shù", "ipa": "tʂʊŋ˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "春天，我们去山上种树。", "target_word": "种树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每年都在院子里种树。", "target_word": "种树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带学生去公园种树。", "target_word": "种树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种树要先挖一个大坑。", "target_word": "种树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢种树，也喜欢种花。", "target_word": "种树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们为什么要种树？因为树能让空气更好。", "target_word": "种树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我和家人一起去种树。", "target_word": "种树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气虽然很热，他还是坚持种树。", "target_word": "种树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢在河边种树吗？", "target_word": "种树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在河边种树，大家都很高兴。", "target_word": "种树", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种过树", "label": "体标"}, {"form": "种了树", "label": "体标"}], "register": "中性", "sense_fingerprint": "把树苗栽进土里，让它生长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76649259-ba21-4681-8829-56e282963d15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26418, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "种树", "is_correct": true, "explanation": "正确答案。句中「去山上」表示到山上栽树，「种树」符合语境。"}, {"text": "出海", "is_correct": false, "explanation": "语义：「出海」指到海上去，山上没有海，与「山上」矛盾。"}, {"text": "进城", "is_correct": false, "explanation": "语义：「进城」指到城里去，与「去山上」的方向相矛盾。"}, {"text": "收玉米", "is_correct": false, "explanation": "搭配：「收」要接已经成熟的庄稼，春天的山上还没有玉米可收。"}], "explanations": {"种树": "正确答案。句中「去山上」表示到山上栽树，「种树」符合语境。", "出海": "语义：「出海」指到海上去，山上没有海，与「山上」矛盾。", "进城": "语义：「进城」指到城里去，与「去山上」的方向相矛盾。", "收玉米": "搭配：「收」要接已经成熟的庄稼，春天的山上还没有玉米可收。"}, "sentence_index": 0, "correct_answer": "种树"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在教室里种树一首诗。", "explanation": "这里应该用〈写〉。种树的对象是树苗，诗要用写。"}, {"text": "工人们正在种树一座大桥。", "explanation": "这里应该用〈建造〉。种树的对象是树苗，大桥要用建造。"}, {"text": "渔民在海上种树，等着收获。", "explanation": "这里应该用〈捕鱼〉。种树指在土里栽树苗，在海上要用捕鱼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26418, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "种树", "is_correct": true, "explanation": "正确答案。句中「家人一起去」之后应是栽树的活动，「种树」符合语境。"}, {"text": "下雨", "is_correct": false, "explanation": "搭配：「下雨」是天气现象，主语不能是人，不能说「我和家人一起去下雨」。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病不是人能计划着「去」做的事，「一起去生病」说不通。"}, {"text": "出生", "is_correct": false, "explanation": "语义：人只能出生一次，不能周末和家人「一起去出生」。"}], "explanations": {"种树": "正确答案。句中「家人一起去」之后应是栽树的活动，「种树」符合语境。", "下雨": "搭配：「下雨」是天气现象，主语不能是人，不能说「我和家人一起去下雨」。", "生病": "语义：生病不是人能计划着「去」做的事，「一起去生病」说不通。", "出生": "语义：人只能出生一次，不能周末和家人「一起去出生」。"}, "sentence_index": 6, "correct_answer": "种树"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里种树，忙着准备晚饭。", "explanation": "这里应该用〈做饭〉。种树指在土里栽树苗，厨房里做饭要用做饭。"}, {"text": "我妹妹正在种树这台电脑。", "explanation": "这里应该用〈修理〉。种树的对象是树苗，电脑要用修理。"}, {"text": "他们在种树房子，准备下个月搬进去。", "explanation": "这里应该用〈装修〉。种树不能用于房子，房子要用装修。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在山坡上种树，一共种了三只树。", "corrected_sentence": "他们在山坡上种树，一共种了三棵树。", "error_description": "错误：「三只树」。正确：「三棵树」。「树」应用量词「棵」，「只」用于动物等，不能用来计量树。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在河边种树过。", "corrected_sentence": "他在河边种树了。", "error_description": "错误：「种树过」。正确：「种树了」。「过」表示经历，应紧跟动词「种」（如「种过树」）；此处是已完成的动作，应用「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
