INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26420, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "保护我们住的地方，比如森林、河流和空气。", "primary_collocate": null, "pronunciation": "huán jìng bǎo hù", "ipa": "xuan˧˥ tɕiŋ˥˩ pɑʊ˨˩˦ xu˥˩", "syllable_count": 4, "sentences": [{"text": "环境保护对大家都很重要。", "target_word": "环境保护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学校常有环境保护活动。", "target_word": "环境保护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小就关心环境保护。", "target_word": "环境保护", "complexity_tier": "T3", "furigana": "huán jìng bǎo hù", "sentence_source": "generated"}, {"text": "做好环境保护，空气会更好。", "target_word": "环境保护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "环境保护要从小事做起。", "target_word": "环境保护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在一家环境保护公司工作。", "target_word": "环境保护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们上了环境保护课。", "target_word": "环境保护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府很重视环境保护。", "target_word": "环境保护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "少开车也是环境保护的好办法。", "target_word": "环境保护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想为环境保护做点事。", "target_word": "环境保护", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "環境保護", "label": "繁体"}], "register": "中性", "sense_fingerprint": "保护森林、河流、空气等生活环境的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ac6ae9e-65f2-4cd8-afbe-fbecadfb9dc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环境保护", "is_correct": true, "explanation": "正确：环境保护作主语，指保护环境这件事，与句子相符。"}, {"text": "灰尘", "is_correct": false, "explanation": "语义：灰尘没有重要性，不能说“对大家都很重要”。"}, {"text": "空房", "is_correct": false, "explanation": "搭配：“空房”指没人住的房子，不能和“对大家都很重要”搭配。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：噪音是有害的声音，不能说“对大家都很重要”。"}], "explanations": {"环境保护": "正确：环境保护作主语，指保护环境这件事，与句子相符。", "灰尘": "语义：灰尘没有重要性，不能说“对大家都很重要”。", "空房": "搭配：“空房”指没人住的房子，不能和“对大家都很重要”搭配。", "噪音": "语义：噪音是有害的声音，不能说“对大家都很重要”。"}, "sentence_index": 0, "correct_answer": "环境保护"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一个很好的环境保护。", "explanation": "这里应该用〈环境保护者〉。环境保护指事业，指人要说“环境保护者”。"}, {"text": "我们要爱护环境保护。", "explanation": "这里应该用〈关心〉。“爱护”的对象是具体的人或物，“环境保护”是事业，应说“关心环境保护”。"}, {"text": "环境保护每天打扫街道。", "explanation": "这里应该用〈环卫工〉。环境保护是事业，不能作为打扫街道的施事者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环境保护", "is_correct": true, "explanation": "正确：环境保护是一门课的内容，与“老师给我们上了环境保护课”相符。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜是水果，不能作为课程的内容。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是矿物，不能作为课程的内容。"}, {"text": "方向盘", "is_correct": false, "explanation": "搭配：“课”要说具体的学科或主题，不说“方向盘课”。"}], "explanations": {"环境保护": "正确：环境保护是一门课的内容，与“老师给我们上了环境保护课”相符。", "西瓜": "语义：西瓜是水果，不能作为课程的内容。", "石头": "语义：石头是矿物，不能作为课程的内容。", "方向盘": "搭配：“课”要说具体的学科或主题，不说“方向盘课”。"}, "sentence_index": 6, "correct_answer": "环境保护"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在超市买了一斤环境保护。", "explanation": "这里应该用〈水果〉。环境保护是一项事业，不能论斤买卖。"}, {"text": "工厂的环境保护很严重。", "explanation": "这里应该用〈污染〉。环境保护是保护行为，不能用来形容问题的严重程度。"}, {"text": "他家里养了环境保护。", "explanation": "这里应该用〈宠物〉。环境保护是事业，不能被饲养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很环境保护。", "corrected_sentence": "他很关心环境保护。", "error_description": "词性错误：“环境保护”是名词，不能直接受副词“很”修饰。正确说法是“他很关心环境保护”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该环境保护放在第一位。", "corrected_sentence": "我们应该把环境保护放在第一位。", "error_description": "漏词：“把”字句的宾语“环境保护”前面缺少“把”。正确说法是“我们应该把环境保护放在第一位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
