INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26424, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小鸟是一种会飞的动物，身体小小的，有羽毛和翅膀。", "primary_collocate": null, "pronunciation": "xiǎo niǎo", "ipa": "ɕiau˨˩˦ niau˨˩˦", "syllable_count": 2, "sentences": [{"text": "树上有一只小鸟在唱歌。", "target_word": "小鸟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟用翅膀飞到了高高的树上。", "target_word": "小鸟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，小鸟都回来了。", "target_word": "小鸟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟住在树上的小窝里。", "target_word": "小鸟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟吃虫子，也吃小种子。", "target_word": "小鸟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家窗外有两只小鸟。", "target_word": "小鸟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟妈妈在给孩子找吃的。", "target_word": "小鸟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把受伤的小鸟带回了家。", "target_word": "小鸟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟看见猫，马上飞走了。", "target_word": "小鸟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上，小鸟的叫声把我叫醒了。", "target_word": "小鸟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "小鸟儿", "label": "儿化"}], "register": "中性", "sense_fingerprint": "身体小、会飞、有羽毛和翅膀的鸟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7870b6f4-2759-41c0-b1b7-31d9f7ccd8bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26424, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小鸟", "is_correct": true, "explanation": "符合语境：小鸟会唱歌，树上唱歌的应是小鸟。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不会在树上唱歌，句子意思不通。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不会唱歌，这里说的是树上的动物在唱歌。"}, {"text": "小猪", "is_correct": false, "explanation": "语义：小猪不会在树上唱歌，句子意思不通。"}], "explanations": {"小鸟": "符合语境：小鸟会唱歌，树上唱歌的应是小鸟。", "小猫": "语义：小猫不会在树上唱歌，句子意思不通。", "小狗": "语义：小狗不会唱歌，这里说的是树上的动物在唱歌。", "小猪": "语义：小猪不会在树上唱歌，句子意思不通。"}, "sentence_index": 0, "correct_answer": "小鸟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天骑着小鸟去上学。", "explanation": "这里应该用〈自行车〉。小鸟是小动物，不能骑，骑着上学的是自行车。"}, {"text": "我家的小鸟每天都在院子里汪汪叫。", "explanation": "这里应该用〈小狗〉。小鸟不会汪汪叫，这是狗的叫声。"}, {"text": "田边的小鸟在耕地。", "explanation": "这里应该用〈老牛〉。小鸟不会耕地，耕地要用牛这类役畜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb06fdd9-08b5-4670-be89-e1f673d9f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小鸟", "is_correct": true, "explanation": "符合语境：“小鸟妈妈”指小鸟的母亲，正在给孩子找食物。"}, {"text": "小树", "is_correct": false, "explanation": "语义：树不会找吃的，“小树妈妈”不符合语境。"}, {"text": "小汽车", "is_correct": false, "explanation": "语义：汽车不吃东西，不能给孩子找吃的。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“X妈妈”一般用于动物，“石头妈妈”不是可以说的搭配。"}], "explanations": {"小鸟": "符合语境：“小鸟妈妈”指小鸟的母亲，正在给孩子找食物。", "小树": "语义：树不会找吃的，“小树妈妈”不符合语境。", "小汽车": "语义：汽车不吃东西，不能给孩子找吃的。", "石头": "搭配：“X妈妈”一般用于动物，“石头妈妈”不是可以说的搭配。"}, "sentence_index": 6, "correct_answer": "小鸟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小鸟在墙角里追着老鼠跑。", "explanation": "这里应该用〈狐狸〉。小鸟不会追赶老鼠，“追着老鼠跑”是狐狸一类动物的行为。"}, {"text": "小鸟在湖底吐泡泡。", "explanation": "这里应该用〈鱼儿〉。小鸟不生活在水底，“吐泡泡”是鱼在水中的行为。"}, {"text": "小鸟在草地上喝牛奶。", "explanation": "这里应该用〈小猫〉。小鸟不喝牛奶，喝牛奶的是猫这类哺乳动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb06fdd9-08b5-4670-be89-e1f673d9f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里飞来一条小鸟。", "corrected_sentence": "院子里飞来一只小鸟。", "error_description": "错误形式是“一条小鸟”，正确形式是“一只小鸟”。“小鸟”是动物，量词应用“只”；“条”用于细长的东西，不能用来数小鸟。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb06fdd9-08b5-4670-be89-e1f673d9f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "树上有一头小鸟。", "corrected_sentence": "树上有一只小鸟。", "error_description": "错误形式是“一头小鸟”，正确形式是“一只小鸟”。“头”用于牛、猪等大的动物，小鸟要用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb06fdd9-08b5-4670-be89-e1f673d9f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
