INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26428, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "住得很近的那些人。", "primary_collocate": null, "pronunciation": "lín jū men", "ipa": "lin˧˥ tɕy˥ mən", "syllable_count": 3, "sentences": [{"text": "邻居们都很喜欢我家的小狗。", "target_word": "邻居们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，邻居们一起吃饭。", "target_word": "邻居们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们在门口聊天。", "target_word": "邻居们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天邻居们帮我搬了家。", "target_word": "邻居们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和邻居们住在同一栋楼里。", "target_word": "邻居们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们听到声音，都跑出来了。", "target_word": "邻居们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的人给邻居们送了水果。", "target_word": "邻居们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们说这条路太黑了。", "target_word": "邻居们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末，邻居们在院子里种花。", "target_word": "邻居们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这儿的邻居们都很友好。", "target_word": "邻居们", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "邻居", "label": "单数"}, {"form": "鄰居們", "label": "繁体"}], "register": "中性", "sense_fingerprint": "住在附近的许多人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '810ac7fa-1260-4d9e-be13-37017ce45fe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26428, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "邻居们", "is_correct": true, "explanation": "“邻居们”指住得近的多个人，能够“喜欢”小狗，且与“都”搭配。"}, {"text": "图书", "is_correct": false, "explanation": "语义：书籍是物品，没有喜欢小狗的感情。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”是不可数名词，不能说“空气们”，也不能喜欢小狗。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能有喜欢的感情，与“我家的小狗”的语境不合。"}], "explanations": {"邻居们": "“邻居们”指住得近的多个人，能够“喜欢”小狗，且与“都”搭配。", "图书": "语义：书籍是物品，没有喜欢小狗的感情。", "空气": "搭配：“空气”是不可数名词，不能说“空气们”，也不能喜欢小狗。", "汽车": "语义：汽车不能有喜欢的感情，与“我家的小狗”的语境不合。"}, "sentence_index": 0, "correct_answer": "邻居们"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "表哥结婚那天，邻居们从外地赶来了。", "explanation": "这里应该用〈亲戚〉。从外地赶来参加婚礼的是亲戚，“邻居”指住得近的人，不指远道而来的家人。"}, {"text": "下班后邻居们都在办公室里收拾东西。", "explanation": "这里应该用〈同事〉。下班后在办公室收拾东西的是同事，“邻居”指住得近的人。"}, {"text": "放学后邻居们都在教室里写作业。", "explanation": "这里应该用〈同学〉。放学后在教室里写作业的是同学，“邻居”指住得近的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26428, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "邻居们", "is_correct": true, "explanation": "“邻居们”是能接收礼物的人，与“新来的人给……送了水果”相合。"}, {"text": "围墙", "is_correct": false, "explanation": "语义：围墙是建筑物，不能接收水果。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不能成为送水果的对象。"}, {"text": "泥土", "is_correct": false, "explanation": "搭配：“泥土”是不可数名词，不能说“泥土们”，且它不能接收水果。"}], "explanations": {"邻居们": "“邻居们”是能接收礼物的人，与“新来的人给……送了水果”相合。", "围墙": "语义：围墙是建筑物，不能接收水果。", "电脑": "语义：电脑是机器，不能成为送水果的对象。", "泥土": "搭配：“泥土”是不可数名词，不能说“泥土们”，且它不能接收水果。"}, "sentence_index": 6, "correct_answer": "邻居们"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议上邻居们都在讨论新技术。", "explanation": "这里应该用〈同行〉。开会讨论新技术的是同行，“邻居”指住得近的人。"}, {"text": "当兵的时候，邻居们从各地被调到同一个连队。", "explanation": "这里应该用〈战友〉。从各地调到同一连队的是战友，“邻居”指原本住得近的人，此处不合。"}, {"text": "老板要求邻居们周一早上八点到公司上班。", "explanation": "这里应该用〈员工〉。老板要求按时到公司上班的是员工，“邻居们”指住得近的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26428, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这栋楼里住着三只邻居。", "corrected_sentence": "这栋楼里住着三位邻居。", "error_description": "错误在于“邻居”的量词。“邻居”指人，量词应用“位”或“个”，不能用“只”，“只”用于动物或小物件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26428, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新搬来地邻居们都很热情。", "corrected_sentence": "新搬来的邻居们都很热情。", "error_description": "“新搬来”修饰“邻居们”时要用结构助词“的”，不用“地”（“地”用于状语）；应说“新搬来的邻居们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26430, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "填土", "is_correct": true, "explanation": "正确：“填土”是把土填回去，与“挖土”的动作相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "无反义关系：唱歌与挖土的动作没有相反关系。"}, {"text": "跑步", "is_correct": false, "explanation": "无反义关系：跑步与挖土不构成相反的动作。"}, {"text": "睡觉", "is_correct": false, "explanation": "无反义关系：睡觉与挖土不是相对的动作。"}], "correct_answer": "填土", "explanations": {"填土": "正确：“填土”是把土填回去，与“挖土”的动作相反。", "唱歌": "无反义关系：唱歌与挖土的动作没有相反关系。", "跑步": "无反义关系：跑步与挖土不构成相反的动作。", "睡觉": "无反义关系：睡觉与挖土不是相对的动作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26430, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "填土", "is_correct": true, "explanation": "正确：“填土”是把土填回去，与“挖土”的动作相反。"}, {"text": "上课", "is_correct": false, "explanation": "无反义关系：上课与挖土没有相反的对应关系。"}, {"text": "爬山", "is_correct": false, "explanation": "无反义关系：爬山与挖土不是相对的动作。"}, {"text": "洗澡", "is_correct": false, "explanation": "无反义关系：洗澡与挖土不构成反义。"}], "correct_answer": "填土", "explanations": {"填土": "正确：“填土”是把土填回去，与“挖土”的动作相反。", "上课": "无反义关系：上课与挖土没有相反的对应关系。", "爬山": "无反义关系：爬山与挖土不是相对的动作。", "洗澡": "无反义关系：洗澡与挖土不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26430, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或工具把土从地里弄出来。", "primary_collocate": null, "pronunciation": "wā tǔ", "ipa": "wa˥ tʰu˨˩", "syllable_count": 2, "sentences": [{"text": "春天到了，大家一起去山上挖土种树。", "target_word": "挖土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他挖土挖了一个小时。", "target_word": "挖土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在院子里挖土找骨头。", "target_word": "挖土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你用这把铲子挖土。", "target_word": "挖土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每天在菜地里挖土。", "target_word": "挖土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "挖土以后，要把种子放进去。", "target_word": "挖土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们先挖土，再打地基，然后盖一座新楼。", "target_word": "挖土", "complexity_tier": "T3", "furigana": "gōng rén men xiān wā tǔ, zài dǎ dì jī, rán hòu gài yí zuò xīn lóu.", "sentence_source": "generated"}, {"text": "爷爷教我怎么挖土，怎么浇水。", "target_word": "挖土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子累了，不想再挖土了。", "target_word": "挖土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用机器挖土，比用手快多了。", "target_word": "挖土", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挖了土", "label": "体标"}, {"form": "挖过土", "label": "体标"}, {"form": "挖土机", "label": "复合"}], "register": "中性", "sense_fingerprint": "用手或工具把土从地里弄出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f270e504-0a47-4d31-b06d-9aa60be4a027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26430, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挖土", "is_correct": true, "explanation": "正确：“挖土”是把土从地里弄出来，为种树做准备，与句意相符。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”用于庄稼，不能用于为种树做的准备工作。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：去山上唱歌与种树的准备工作不符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：山上没有游泳的条件，与“种树”的语境不符。"}], "explanations": {"挖土": "正确：“挖土”是把土从地里弄出来，为种树做准备，与句意相符。", "收割": "搭配：“收割”用于庄稼，不能用于为种树做的准备工作。", "唱歌": "语义：去山上唱歌与种树的准备工作不符。", "游泳": "语义：山上没有游泳的条件，与“种树”的语境不符。"}, "sentence_index": 0, "correct_answer": "挖土"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一开口就挖土，大家都不喜欢听。", "explanation": "这里不能用〈挖土〉。挖土指用工具把土取出来，不能表示说话带刺、讽刺人，那要用〈挖苦〉。"}, {"text": "他暗中挖土，想让对手公司破产。", "explanation": "这里不能用〈挖土〉。挖土是取土的动作，不能表示暗中破坏别人，那要用〈挖墙脚〉。"}, {"text": "老师在课堂上挖土讲课。", "explanation": "这里不能用〈挖土〉。挖土是取出泥土的劳动，不能表示讲课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26430, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挖土", "is_correct": true, "explanation": "正确：“挖土”是修建前的准备工作，与“再打地基、盖新楼”的顺序相符。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：下棋与打地基、盖楼的施工步骤无关。"}, {"text": "看书", "is_correct": false, "explanation": "语义：看书不是施工的准备工作，与句意不符。"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”需要宾语，“先喝，再打地基”的结构不成立。"}], "explanations": {"挖土": "正确：“挖土”是修建前的准备工作，与“再打地基、盖新楼”的顺序相符。", "下棋": "语义：下棋与打地基、盖楼的施工步骤无关。", "看书": "语义：看书不是施工的准备工作，与句意不符。", "喝": "配价：“喝”需要宾语，“先喝，再打地基”的结构不成立。"}, "sentence_index": 6, "correct_answer": "挖土"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司到处挖土，把对手的员工都挖走了。", "explanation": "这里不能用〈挖土〉。挖土是取出泥土的劳动，不能表示把别人的员工挖走，那要用〈挖人〉。"}, {"text": "这台电脑挖土得很慢，我们换一台吧。", "explanation": "这里不能用〈挖土〉。挖土指取出泥土，不能用来形容电脑运行的快慢，那要用〈运行〉。"}, {"text": "他为了赚钱，每天都在股市里挖土。", "explanation": "这里不能用〈挖土〉。挖土指取出泥土，不能表示在股市里投机赚钱，那要用〈炒股〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们昨天挖土土，准备种菜。", "corrected_sentence": "我们昨天挖土，准备种菜。", "error_description": "重复错误：多写了一个“土”，“挖土”应为两字词，去掉多余的“土”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们今天挖土土，明天就去种树。", "corrected_sentence": "我们今天挖土，明天就去种树。", "error_description": "重复错误：多写了一个“土”，“挖土”应为两字词，去掉多余的“土”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
