INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26434, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "给植物或花倒水。", "primary_collocate": null, "pronunciation": "jiāo shuǐ", "ipa": "tɕjɑʊ˥ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我每天给小花浇水。", "target_word": "浇水", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水壶在这儿，你去给花浇水吧。", "target_word": "浇水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "阳台上的花几天没浇水，叶子黄了。", "target_word": "浇水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请帮我给植物浇水，我下周出差。", "target_word": "浇水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多肉不用常浇水，一个月一次就够。", "target_word": "浇水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天下班后给院子里的菜浇水。", "target_word": "浇水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "浇水的时候，别把叶子弄湿。", "target_word": "浇水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友拿着小水壶学大人浇水。", "target_word": "浇水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，花园里的树都要浇水。", "target_word": "浇水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早上浇水比中午好，花不容易受伤。", "target_word": "浇水", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "浇了水", "label": "体标（了）"}, {"form": "浇过水", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "浇水：给花草、菜、树等植物倒水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '344206f6-976f-4874-8f0d-c04e78e16151') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26434, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "浇水", "is_correct": true, "explanation": "正确：浇水 jiāo shuǐ，给植物倒水。"}, {"text": "加水", "is_correct": false, "explanation": "jiā（加）与 jiāo（浇）的韵母不同（-a 与 -ao），意思是添加水。"}, {"text": "交税", "is_correct": false, "explanation": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是缴纳税款。"}, {"text": "烧水", "is_correct": false, "explanation": "shāo（烧）与 jiāo（浇）声母不同，意思是加热水。"}], "explanations": {"浇水": "正确：浇水 jiāo shuǐ，给植物倒水。", "加水": "jiā（加）与 jiāo（浇）的韵母不同（-a 与 -ao），意思是添加水。", "交税": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是缴纳税款。", "烧水": "shāo（烧）与 jiāo（浇）声母不同，意思是加热水。"}, "sentence_index": null, "correct_answer": "浇水"}, "level_3": {"options": [{"text": "浇水", "is_correct": true, "explanation": "正确：「浇水」指给植物倒水，与「给小花」「每天」的语境相符。"}, {"text": "批改", "is_correct": false, "explanation": "语义：「批改」的对象是作业或试卷，不能用于花。"}, {"text": "辅导", "is_correct": false, "explanation": "语义：「辅导」的对象须是学习的人，小花不能接受辅导。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：「喂养」多用于动物或幼儿，不用于花草。"}], "explanations": {"浇水": "正确：「浇水」指给植物倒水，与「给小花」「每天」的语境相符。", "批改": "语义：「批改」的对象是作业或试卷，不能用于花。", "辅导": "语义：「辅导」的对象须是学习的人，小花不能接受辅导。", "喂养": "搭配：「喂养」多用于动物或幼儿，不用于花草。"}, "sentence_index": 0, "correct_answer": "浇水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只小猫渴了，你去给它浇水吧。", "explanation": "这里应该用〈喂水〉。浇水只用于给植物倒水，给动物喝水要用喂水。"}, {"text": "他每天早上给书架浇水，书架上的书都很整齐。", "explanation": "这里的「浇水」被误用为「给任何东西加水、弄湿」的意思。书架不是植物，清洁家具应该用〈擦〉。"}, {"text": "我每天给电脑浇水，它运行得更快了。", "explanation": "这里的「浇水」被误用为「给电器降温」的意思。电脑不是植物，给电脑降温应该用〈散热〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浇水", "is_correct": true, "explanation": "正确：「浇水的时候，别把叶子弄湿」指给植物倒水时的注意事项，句意通顺。"}, {"text": "熨", "is_correct": false, "explanation": "搭配：「熨」用于衣物，不能说「熨叶子」。"}, {"text": "指导", "is_correct": false, "explanation": "语义：「指导」的对象须是人，植物不能被指导。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：「表扬」是对人或行为的赞扬，与「别把叶子弄湿」的语境不合。"}], "explanations": {"浇水": "正确：「浇水的时候，别把叶子弄湿」指给植物倒水时的注意事项，句意通顺。", "熨": "搭配：「熨」用于衣物，不能说「熨叶子」。", "指导": "语义：「指导」的对象须是人，植物不能被指导。", "表扬": "语义：「表扬」是对人或行为的赞扬，与「别把叶子弄湿」的语境不合。"}, "sentence_index": 6, "correct_answer": "浇水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一听说我要去留学，大家就纷纷给我浇水。", "explanation": "这里应该用〈泼冷水〉。「浇水」只指给植物倒水，不能单独表示使人灰心（该义为“泼冷水”“浇冷水”）。"}, {"text": "两个孩子在河边互相浇水，笑得很开心。", "explanation": "这里的「浇水」被误用为「互相戏水」的意思。「浇水」只指给植物倒水，玩水应该用〈泼水〉。"}, {"text": "妈妈在厨房里给锅浇水，准备煮面。", "explanation": "这里应该用〈加水〉。「浇水」只指给植物倒水，往锅里放水应该说“加水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每周都要给浇水。", "corrected_sentence": "我每周都要给花浇水。", "error_description": "宾语缺失：“给”引出浇水的对象，须说“给花浇水”，“给浇水”缺少对象，不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每次出差前都给花浇水完。", "corrected_sentence": "我每次出差前都给花浇完水。", "error_description": "补语位置错误：结果补语“完”应紧跟动词，“浇水完”错误，应说“浇完水”，即“给花浇完水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
