INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26442, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人、动物或植物生长，身体变大，逐渐成熟。", "primary_collocate": null, "pronunciation": "zhǎng dà", "ipa": "ʈʂɑŋ˨˩˦ tɑ˥˩", "syllable_count": 2, "sentences": [{"text": "院子里的南瓜长大了，颜色也变黄了。", "target_word": "长大", "complexity_tier": "T3", "furigana": "zhǎng dà", "sentence_source": "generated"}, {"text": "池塘里的荷叶一天天长大，遮住了水面。", "target_word": "长大", "complexity_tier": "T3", "furigana": "zhǎng dà", "sentence_source": "generated"}, {"text": "你种的西瓜长大了吗？", "target_word": "长大", "complexity_tier": "T3", "furigana": "zhǎng dà", "sentence_source": "generated"}, {"text": "这棵小树长大了，可以在下面乘凉。", "target_word": "长大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "田里的稻子长大了，快要收割了。", "target_word": "长大", "complexity_tier": "T3", "furigana": "zhǎng dà", "sentence_source": "generated"}, {"text": "小猫长大以后变得很懒。", "target_word": "长大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些蘑菇长大得很快，几天就能采了。", "target_word": "长大", "complexity_tier": "T3", "furigana": "zhǎng dà", "sentence_source": "generated"}, {"text": "河边的芦苇一天天长大，已经比人还高了。", "target_word": "长大", "complexity_tier": "T3", "furigana": "zhǎng dà", "sentence_source": "generated"}, {"text": "这些小鱼长大以后会游到大海里去。", "target_word": "长大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菜园里的白菜长大了，可以拔下来吃了。", "target_word": "长大", "complexity_tier": "T3", "furigana": "zhǎng dà", "sentence_source": "generated"}], "morphological_forms": [{"form": "长大了", "label": "体标"}, {"form": "长大成人", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：人、动物、植物变大、变成熟（孩子长大了）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b139088-ecac-459a-8b81-09a754a5d1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26442, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "长大", "is_correct": true, "explanation": "长大（zhǎng dà）：生物长成、变大，是正确答案。"}, {"text": "张大", "is_correct": false, "explanation": "张大（zhāng dà）：zhāng（第一声）与 zhǎng（第三声）声调不同，意思是张开。"}, {"text": "胀大", "is_correct": false, "explanation": "胀大（zhàng dà）：zhàng（第四声）与 zhǎng（第三声）声调不同，意思是因膨胀而变大。"}, {"text": "长达", "is_correct": false, "explanation": "长达（cháng dá）：声母、声调都与 zhǎng dà 不同，dá（第二声）与 dà（第四声）也不同，意思是长度或时间达到。"}], "explanations": {"长大": "长大（zhǎng dà）：生物长成、变大，是正确答案。", "张大": "张大（zhāng dà）：zhāng（第一声）与 zhǎng（第三声）声调不同，意思是张开。", "胀大": "胀大（zhàng dà）：zhàng（第四声）与 zhǎng（第三声）声调不同，意思是因膨胀而变大。", "长达": "长达（cháng dá）：声母、声调都与 zhǎng dà 不同，dá（第二声）与 dà（第四声）也不同，意思是长度或时间达到。"}, "sentence_index": null, "correct_answer": "长大"}, "level_3": {"options": [{"text": "飞走", "is_correct": false, "explanation": "语义：南瓜不会飞，“飞走”与句意完全不合。"}, {"text": "长大", "is_correct": true, "explanation": "长大：植物长成、变大，与南瓜生长、颜色变黄的语境相符。"}, {"text": "说话", "is_correct": false, "explanation": "搭配：“说话”要求有语言能力的主语，南瓜不能说话。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”只用于人，南瓜不能结婚。"}], "explanations": {"飞走": "语义：南瓜不会飞，“飞走”与句意完全不合。", "长大": "长大：植物长成、变大，与南瓜生长、颜色变黄的语境相符。", "说话": "搭配：“说话”要求有语言能力的主语，南瓜不能说话。", "结婚": "语义：“结婚”只用于人，南瓜不能结婚。"}, "sentence_index": 0, "correct_answer": "长大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂今年的订单长大了很多。", "explanation": "这里应该用〈增加〉。长大用于人或动植物的成长，订单等数量的变化要用增加。"}, {"text": "今年全国人口长大了很多。", "explanation": "这里应该用〈增长〉。长大指生物长成，人口的增减要用增长。"}, {"text": "这孩子一年长大了十厘米。", "explanation": "这里应该用〈长高〉。说身高增加要用长高；长大指整体成长、变成熟，不说“长大了十厘米”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26442, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发福", "is_correct": false, "explanation": "体貌：“发福”形容人发胖，蘑菇不会发福。"}, {"text": "长大", "is_correct": true, "explanation": "长大：生物长成、变大，与蘑菇迅速长大、几天就能采的语境相符。"}, {"text": "变瘦", "is_correct": false, "explanation": "体貌：“变瘦”形容人或动物的体型，蘑菇不说变瘦。"}, {"text": "生育", "is_correct": false, "explanation": "搭配：“生育”用于人或动物，不用于形容蘑菇。"}], "explanations": {"发福": "体貌：“发福”形容人发胖，蘑菇不会发福。", "长大": "长大：生物长成、变大，与蘑菇迅速长大、几天就能采的语境相符。", "变瘦": "体貌：“变瘦”形容人或动物的体型，蘑菇不说变瘦。", "生育": "搭配：“生育”用于人或动物，不用于形容蘑菇。"}, "sentence_index": 6, "correct_answer": "长大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "最近来参观的游客长大了很多。", "explanation": "这里应该用〈增多〉。长大用于生物的成长，人数的增加要用增多。"}, {"text": "这家店的面积长大了。", "explanation": "这里应该用〈扩大〉。面积的扩展要用扩大，长大只用于生物的成长。"}, {"text": "这台机器的功率长大了一倍。", "explanation": "这里应该用〈增大〉。功率、数值的变大要用增大，长大只用于生物的成长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只小猫长大了了，已经会抓老鼠了。", "corrected_sentence": "这只小猫长大了，已经会抓老鼠了。", "error_description": "错误：“长大”后只用一个“了”，应说“长大了”；“长大了了”重复了体标“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些豆芽长大了很快，两天就能吃了。", "corrected_sentence": "这些豆芽长大得很快，两天就能吃了。", "error_description": "补语标记错误：“长大得很快”中“得”引出补语，“了”不能引出补语，应改为“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
